def _finish_index_update(marker_path: Path, *, owner_token: str,
                         backend: str | None = None,
                         collection_name: str | None = None) -> None:
    """Mark an update clean after its verified manifest has been committed."""
    _index_state._finish_index_update(
        marker_path, owner_token=owner_token, backend=backend,
        collection_name=collection_name,
        marker_owned_by_fn=_index_update_marker_owned_by)


def _load_index_manifest(db_dir: Path, *, backend: str,
                         collection_name: str) -> dict | None:
    """Load a collection-scoped manifest, returning ``None`` if unusable."""
    return _index_state._load_index_manifest(
        db_dir, backend=backend, collection_name=collection_name,
        manifest_path_fn=_index_manifest_path,
        warning_fn=log.warning)


def _index_manifest_mismatch(
        manifest: dict, *, backend: str, collection_name: str,
        embedding_model: str, embedding_dimension: int) -> str | None:
    """Return why *manifest* is incompatible, or ``None`` when safe to use."""
    return _index_state._index_manifest_mismatch(
        manifest, backend=backend, collection_name=collection_name,
        embedding_model=embedding_model,
        embedding_dimension=embedding_dimension,
        embedding_input_policy_version=EMBEDDING_INPUT_POLICY_VERSION,
        model_artifact_lock_sha256=_model_artifact_lock_sha256(),
        manifest_schema_version=INDEX_MANIFEST_SCHEMA_VERSION,
        quality_report_schema_version=(
            _quality_core.QUALITY_REPORT_SCHEMA_VERSION))


def _resolve_incremental_index_state(
        db_dir: Path, *, backend: str, collection_name: str,
        embedding_model: str, embedding_dimension: int,
        collection_exists: bool, full_reindex: bool,
        active_update_token: str | None = None,
) -> tuple[dict[str, str], bool, str]:
    """Resolve hashes and whether the named collection must be rebuilt.

    A legacy database-wide sidecar is deliberately never trusted for a skip:
    it cannot prove which collection or embedding model produced the vectors.
    Rebuilding only the requested collection safely migrates it to the new
    manifest without touching sibling collections or deleting the legacy file.
    """
    return _index_state._resolve_incremental_index_state(
        db_dir, backend=backend, collection_name=collection_name,
        embedding_model=embedding_model,
        embedding_dimension=embedding_dimension,
        collection_exists=collection_exists, full_reindex=full_reindex,
        active_update_token=active_update_token,
        marker_path_fn=_index_update_marker_path,
        marker_owned_by_fn=_index_update_marker_owned_by,
        load_manifest_fn=_load_index_manifest,
        manifest_mismatch_fn=_index_manifest_mismatch)


def _save_index_manifest(
        db_dir: Path, *, backend: str, collection_name: str,
        embedding_model: str, embedding_dimension: int,
        chunk_hashes: dict[str, str], source_sha256: str | None = None,
        source_record_count: int | None = None,
        quality_report_schema_version: int | None = None,
        quality_report_sha256: str | None = None,
        table_child_count: int = 0) -> Path:
    """Atomically persist versioned incremental state for one collection."""
    return _index_state._save_index_manifest(
        db_dir, backend=backend, collection_name=collection_name,
        embedding_model=embedding_model,
        embedding_dimension=embedding_dimension,
        embedding_input_policy_version=EMBEDDING_INPUT_POLICY_VERSION,
        model_artifact_lock_sha256=_model_artifact_lock_sha256(),
        chunk_hashes=chunk_hashes, source_sha256=source_sha256,
        source_record_count=source_record_count,
        quality_report_schema_version=quality_report_schema_version,
        quality_report_sha256=quality_report_sha256,
        table_child_count=table_child_count,
        manifest_schema_version=INDEX_MANIFEST_SCHEMA_VERSION,
        quality_report_policy_schema_version=(
            _quality_core.QUALITY_REPORT_SCHEMA_VERSION),
        manifest_path_fn=_index_manifest_path,
        atomic_write_json_fn=_atomic_write_json)


def _query_manifest_dimension_impl(
        db_dir: Path, *, backend: str, collection_name: str,
        embedding_model: str,
        allow_legacy: bool = True) -> int | None:
    """Validate query/index compatibility and return the indexed dimension.

    Legacy collections without a manifest remain queryable. Once a manifest
    exists, however, querying with a different model or stale schema is refused
    rather than silently comparing vectors from incompatible embedding spaces.
    """
    return _index_state._query_manifest_dimension_impl(
        db_dir, backend=backend, collection_name=collection_name,
        embedding_model=embedding_model,
        embedding_input_policy_version=EMBEDDING_INPUT_POLICY_VERSION,
        model_artifact_lock_sha256=_model_artifact_lock_sha256(),
        manifest_schema_version=INDEX_MANIFEST_SCHEMA_VERSION,
        quality_report_schema_version=(
            _quality_core.QUALITY_REPORT_SCHEMA_VERSION),
        marker_path_fn=_index_update_marker_path,
        manifest_path_fn=_index_manifest_path,
        load_manifest_fn=_load_index_manifest,
        compatible_schema_bindings=(
            _LEGACY_QUERY_SCHEMA_BINDINGS
            if allow_legacy else _CONTEXT_QUERY_SCHEMA_BINDINGS))


def _query_manifest_dimension(
        db_dir: Path, *, backend: str, collection_name: str,
        embedding_model: str,
        allow_legacy: bool = True,
        lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT) -> int | None:
    """Validate query/index compatibility under the database lease."""
    with _vector_store_lock(
            db_dir, backend=backend, collection_name=collection_name,
            operation="manifest inspection", timeout=lock_timeout):
        return _query_manifest_dimension_impl(
            db_dir, backend=backend, collection_name=collection_name,
            embedding_model=embedding_model, allow_legacy=allow_legacy)


def _indexed_table_child_count(
        db_dir: Path, *, backend: str, collection_name: str,
) -> int:
    """Return the manifested row-child count for a current index generation."""
    manifest = _load_index_manifest(
        db_dir, backend=backend, collection_name=collection_name)
    if (manifest is None
            or manifest.get("schema_version") != INDEX_MANIFEST_SCHEMA_VERSION):
        return 0
    count = manifest.get("table_child_count")
    if isinstance(count, bool) or not isinstance(count, int) or count < 0:
        raise ValueError("current index manifest has an invalid table child count")
    return count


_artifact_sha256_cache: dict[
    str, tuple[tuple[int, int, int, int, int], str]
] = {}
_artifact_sha256_cache_lock = _threading.Lock()
_ARTIFACT_SHA256_CACHE_MAX = 16
# Windows ``st_ctime`` is creation time rather than an inode change counter.
# Same-size bytes can therefore alias a restored mtime/ctime fingerprint, so a
# stat-only cache hit cannot prove content identity there.
_ARTIFACT_STAT_HASH_CACHE_SAFE = os.name != "nt"


def _cached_artifact_sha256(path: Path) -> str:
    """Hash one stable artifact snapshot, caching by strong stat identity."""
    path = Path(path)
    cache_key = os.path.normcase(str(path.resolve(strict=True)))
    if _ARTIFACT_STAT_HASH_CACHE_SAFE:
        with path.open("rb") as handle:
            before = _artifact_stat_fingerprint(os.fstat(handle.fileno()))
            with _artifact_sha256_cache_lock:
                cached = _artifact_sha256_cache.get(cache_key)
            if cached is not None and cached[0] == before:
                after = _artifact_stat_fingerprint(os.fstat(handle.fileno()))
                if after == before:
                    return cached[1]

    generation = _hash_file_generation(path)
    value = generation.sha256
    fingerprint = generation.fingerprint
    if _ARTIFACT_STAT_HASH_CACHE_SAFE:
        with _artifact_sha256_cache_lock:
            _artifact_sha256_cache[cache_key] = (fingerprint, value)
            while len(_artifact_sha256_cache) > _ARTIFACT_SHA256_CACHE_MAX:
                oldest = next(iter(_artifact_sha256_cache))
                del _artifact_sha256_cache[oldest]
    return value


def _require_hybrid_chunks_snapshot(
        chunks_path: Path, db_dir: Path, *, backend: str,
        collection_name: str) -> str | None:
    """Validate and return the manifested lexical corpus digest, if proven."""
    return _index_state._require_hybrid_chunks_snapshot(
        chunks_path, db_dir, backend=backend,
        collection_name=collection_name,
        load_manifest_fn=_load_index_manifest,
        artifact_sha256_fn=_cached_artifact_sha256,
        quality_report_path_fn=_quality_core.quality_report_path)


_validate_query_vector_dimension = (
    _index_state._validate_query_vector_dimension)


def _embedding_dimension(
        model_name: str, *,
        security_policy: (
            _release_security.ReleaseSecurityPolicy | None
        ) = None) -> int:
    """Probe and validate the configured document embedding dimension."""
    embeddings = _embed_texts(
        ["RAG index embedding-dimension probe"], model_name,
        input_type="document", security_policy=security_policy)
    if len(embeddings) != 1 or len(embeddings[0]) < 1:
        raise ValueError(
            f"Embedding model '{model_name}' returned no usable vector")
    return len(embeddings[0])


def _qdrant_exact_count(client, collection_name: str) -> int:
    """Return Qdrant's exact physical point count or fail closed."""
    result = client.count(collection_name=collection_name, exact=True)
    count = getattr(result, "count", None)
    if (isinstance(count, bool) or not isinstance(count, int)
            or count < 0):
        raise RuntimeError(
            f"Qdrant collection '{collection_name}' returned an invalid "
            "exact point count")
    return count


def _require_qdrant_update_completed(result: object, operation: str) -> None:
    """Require a waited Qdrant mutation to report completed status."""
    status = getattr(result, "status", None)
    status_value = getattr(status, "value", status)
    if type(status_value) is not str or status_value != "completed":
        raise RuntimeError(
            f"Qdrant {operation} did not report completed status")


def _qdrant_id_key(value: object) -> tuple[object, ...]:
    """Return a hashable key without collapsing distinct ID representations."""
    if type(value) is int:
        return "int", value
    if type(value) is str:
        return "str", value
    if isinstance(value, UUID):
        return "uuid.UUID", value.bytes

    descriptor = getattr(value, "DESCRIPTOR", None)
    if getattr(descriptor, "full_name", None) == "qdrant.PointId":
        try:
            variant = value.WhichOneof("point_id_options")
        except (TypeError, ValueError) as exc:
            raise RuntimeError(
                "Qdrant returned an invalid protobuf point ID") from exc
        if variant == "num":
            return "protobuf", "qdrant.PointId", "num", int(value.num)
        if variant == "uuid":
            return "protobuf", "qdrant.PointId", "uuid", str(value.uuid)
        raise RuntimeError(
            "Qdrant returned an unset or unsupported protobuf point ID")

    raise RuntimeError(
        f"Qdrant returned an unsupported point ID type: "
        f"{type(value).__name__}")


def _qdrant_payload_rows(
        client, collection_name: str, *, payload_fields: tuple[str, ...],
        page_size: int = 1000) -> list[tuple[object, dict]]:
    """Return selected payload through a count-bounded, drift-safe scroll."""
    if (isinstance(page_size, bool) or not isinstance(page_size, int)
            or page_size < 1):
        raise ValueError("Qdrant scroll page_size must be a positive integer")
    if (not isinstance(payload_fields, tuple) or not payload_fields
            or len(set(payload_fields)) != len(payload_fields)
            or not all(isinstance(field, str) and field
                       for field in payload_fields)):
        raise ValueError("Qdrant payload fields must be unique non-empty strings")

    count_before = _qdrant_exact_count(client, collection_name)
    rows: list[tuple[object, dict]] = []
    offset = None
    seen_offsets = set()
    seen_point_ids = set()
    max_scroll_calls = max(1, count_before + 1)
    for _ in range(max_scroll_calls):
        points, next_offset = client.scroll(
            collection_name,
            limit=page_size,
            offset=offset,
            with_payload=list(payload_fields),
            with_vectors=False,
        )
        if len(points) > page_size:
            raise RuntimeError(
                "Qdrant scroll returned more points than its page limit")
        if not points and next_offset is not None:
            raise RuntimeError(
                "Qdrant scroll returned an empty nonterminal page")
        for point in points:
            if len(rows) >= count_before:
                raise RuntimeError(
                    "Qdrant scroll exceeded its exact point count")
            point_key = _qdrant_id_key(point.id)
            if point_key in seen_point_ids:
                raise RuntimeError(
                    "Qdrant scroll repeated a physical point ID")
            seen_point_ids.add(point_key)
            payload = point.payload if isinstance(point.payload, dict) else {}
            rows.append((point.id, payload))
        if next_offset is None:
            count_after = _qdrant_exact_count(client, collection_name)
            if len(rows) != count_before or count_after != count_before:
                raise RuntimeError(
                    f"Qdrant collection '{collection_name}' changed or "
                    "returned an incomplete exact-count scroll")
            return rows
        offset_key = _qdrant_id_key(next_offset)
        if offset_key in seen_offsets:
            raise RuntimeError(
                "Qdrant scroll repeated a continuation offset")
        seen_offsets.add(offset_key)
        offset = next_offset
    raise RuntimeError(
        "Qdrant scroll exceeded its exact-count page budget")


def _qdrant_stable_id_rows(
        client, collection_name: str, *,
        page_size: int = 1000) -> list[tuple[object, str | None]]:
    """Return every stable ID through a count-bounded, drift-safe scroll."""
    rows = _qdrant_payload_rows(
        client, collection_name, payload_fields=("stable_id",),
        page_size=page_size)
    stable_rows = []
    for point_id, payload in rows:
        stable_id = payload.get("stable_id")
        if not isinstance(stable_id, str) or not stable_id.strip():
            stable_id = None
        stable_rows.append((point_id, stable_id))
    return stable_rows


def _qdrant_point_ids_for_stable_ids(client, collection_name: str,
                                      stable_ids: set[str], *,
                                      page_size: int = 1000) -> list:
    """Find every Qdrant point matching the exact requested stable-ID set."""
    requested = set(stable_ids)
    if not requested:
        return []
    rows = _qdrant_stable_id_rows(
        client, collection_name, page_size=page_size)
    found = {stable_id for _, stable_id in rows if stable_id in requested}
    missing = requested - found
    if missing:
        raise RuntimeError(
            f"{len(missing)} requested Qdrant stable ID(s) not found; "
            "refusing an incomplete deletion")
    return [point_id for point_id, stable_id in rows
            if stable_id in requested]


def _require_qdrant_stable_id_rows(
        rows: list[tuple[object, str | None]], collection_name: str,
        expected: set[str]) -> dict[str, list]:
    """Validate one captured Qdrant stable-ID generation."""
    point_ids: dict[str, list] = {}
    untracked = 0
    for point_id, stable_id in rows:
        if stable_id is None:
            untracked += 1
            continue
        point_ids.setdefault(stable_id, []).append(point_id)

    actual = set(point_ids)
    missing = expected - actual
    unexpected = actual - expected
    duplicates = sum(
        len(ids) - 1 for ids in point_ids.values() if len(ids) > 1)
    if missing or unexpected or duplicates or untracked:
        details = []
        if missing:
            details.append(f"{len(missing)} stable ID(s) not found")
        if unexpected:
            details.append(f"{len(unexpected)} unexpected stable ID(s)")
        if duplicates:
            details.append(f"{duplicates} duplicate stable-ID point(s)")
        if untracked:
            details.append(f"{untracked} point(s) without a stable ID")
        raise RuntimeError(
            f"Qdrant collection '{collection_name}' does not match its "
            f"stable-ID manifest ({'; '.join(details)}). Refusing to update "
            "the manifest; run again with --full-reindex.")
    return point_ids


def _require_qdrant_stable_ids(
        client, collection_name: str, expected: set[str], *,
        page_size: int = 1000) -> dict[str, list]:
    """Require one physical point for every expected stable ID and no others."""
    rows = _qdrant_stable_id_rows(
        client, collection_name, page_size=page_size)
    return _require_qdrant_stable_id_rows(
        rows, collection_name, expected)


def _inspect_qdrant_chunk_indexes(
        client, collection_name: str,
        expected_ids: set[str] | frozenset[str],
        expected_chunk_indexes: dict[str, int], *,
        page_size: int = 1000,
) -> tuple[dict[str, list], set[str]]:
    """Validate exact identities and report stale target positions in one scan."""
    if not isinstance(expected_ids, (set, frozenset)):
        raise TypeError("expected Qdrant stable IDs must be a set")
    if not isinstance(expected_chunk_indexes, dict):
        raise TypeError("expected Qdrant chunk indexes must be a dictionary")
    for stable_id, chunk_index in expected_chunk_indexes.items():
        if not isinstance(stable_id, str) or not stable_id.strip():
            raise ValueError("expected Qdrant stable IDs must be non-empty")
        if (isinstance(chunk_index, bool) or not isinstance(chunk_index, int)
                or chunk_index < 0):
            raise ValueError(
                "expected Qdrant chunk indexes must be nonnegative integers")
    if not set(expected_chunk_indexes).issubset(expected_ids):
        raise ValueError(
            "expected Qdrant chunk indexes must belong to expected stable IDs")

    payload_rows = _qdrant_payload_rows(
        client, collection_name,
        payload_fields=("stable_id", "chunk_index"),
        page_size=page_size)
    stable_rows: list[tuple[object, str | None]] = []
    actual_indexes: dict[str, object] = {}
    for point_id, payload in payload_rows:
        stable_id = payload.get("stable_id")
        if not isinstance(stable_id, str) or not stable_id.strip():
            stable_id = None
        stable_rows.append((point_id, stable_id))
        if stable_id in expected_chunk_indexes:
            actual_indexes[stable_id] = payload.get("chunk_index")

    point_ids = _require_qdrant_stable_id_rows(
        stable_rows, collection_name, expected_ids)
    mismatches = {
        stable_id for stable_id, expected in expected_chunk_indexes.items()
        if (isinstance(actual_indexes.get(stable_id), bool)
            or not isinstance(actual_indexes.get(stable_id), int)
            or actual_indexes.get(stable_id) != expected)
    }
    return point_ids, mismatches


def _qdrant_chunk_index_mismatches(
        client, collection_name: str,
        expected: dict[str, int], *, page_size: int = 1000) -> set[str]:
    """Return target stable IDs whose stored positional metadata is stale."""
    if not expected:
        return set()
    _, mismatches = _inspect_qdrant_chunk_indexes(
        client, collection_name, set(expected), expected,
        page_size=page_size)
    return mismatches


def _require_qdrant_chunk_indexes(
        client, collection_name: str,
        expected_ids: set[str] | frozenset[str], expected: dict[str, int], *,
        page_size: int = 1000) -> dict[str, list]:
    """Require exact stored ``chunk_index`` payload for target stable IDs."""
    point_ids, mismatches = _inspect_qdrant_chunk_indexes(
        client, collection_name, expected_ids, expected,
        page_size=page_size)
    if mismatches:
        raise RuntimeError(
            f"Qdrant collection '{collection_name}' has "
            f"{len(mismatches)} stale chunk index value(s)")
    return point_ids


def _qdrant_point_id(stable_id: str) -> int:
    """Map a canonical hexadecimal stable ID to a portable 63-bit point ID."""
    return int(stable_id.removeprefix("chunk_"), 16) % (2**63)


def _qdrant_payload(record: dict, stable_id: str) -> dict:
    """Build payload with canonical fields protected from metadata collisions."""
    return {
        **record["metadata"],
        "text": record["text"],
        "stable_id": stable_id,
    }


def _embed_texts(
        texts: list[str], model_name: str, *,
        input_type: str = "document",
        security_policy: (
            _release_security.ReleaseSecurityPolicy | None
        ) = None) -> list[list[float]]:
    """Embed texts with a cached document- or query-role embedder."""
    policy = _effective_security_policy(security_policy)
    if model_name.startswith(_API_EMBEDDING_MODEL_PREFIXES):
        # Re-authorize before cache lookup.  The process can execute operations
        # with different policies, and ambient network configuration can change
        # after a provider closure was constructed.
        _release_security.require_cloud_egress(
            policy, feature="cloud embedding")
    cache_key = (model_name, input_type, policy)
    if cache_key not in _embed_fn_cache:
        _embed_fn_cache[cache_key] = _get_embedding_fn(
            model_name, input_type=input_type, security_policy=policy)
    return _embed_fn_cache[cache_key](texts)


def _index_chunks_qdrant_impl(
        chunks_path: Path, qdrant_dir: Path, *,
        collection_name: str = DEFAULT_COLLECTION,
        embedding_model: str = DEFAULT_EMBEDDING_MODEL,
        full_reindex: bool = False,
        security_policy: (
            _release_security.ReleaseSecurityPolicy | None
        ) = None,
        _active_update_token: str | None = None,
        _client_owner: _VectorClientOwner,
        _operation_tracker: _IndexOperationalTracker,
        ) -> _operation_contracts.IndexOutcome:
    """Load enriched chunks and index into a local Qdrant collection.

    Uses Qdrant's local mode (on-disk, no server needed) with:
    - Dense vectors from the configured embedding model
    - Sparse vectors for built-in hybrid search (no separate BM25 step)
    - Rich payload filtering on all metadata fields
    """
    from qdrant_client import QdrantClient, models
    from tqdm import tqdm

    _require_file(chunks_path, "Chunks JSONL")

    log.info(f"Loading chunks from {chunks_path}")
    (records, source_sha256, _,
     quality_binding) = _load_index_snapshot_with_quality(
         chunks_path, allow_legacy_quality=False)
    quality_schema_version, quality_report_sha256 = quality_binding
    source_record_count = len(records)
    table_child_count = _table_retrieval_core.table_child_count(records)
    _validate_embedding_token_counts(
        records, embedding_model, recompute=True)
    chunk_info = [(record, _chunk_id(record), _chunk_hash(record))
                  for record in records]
    new_hashes = {chunk_id: chunk_hash
                  for _, chunk_id, chunk_hash in chunk_info}
    qdrant_point_ids = {
        chunk_id: _qdrant_point_id(chunk_id) for chunk_id in new_hashes}
    if len(set(qdrant_point_ids.values())) != len(qdrant_point_ids):
        raise ValueError(
            "Chunks file contains colliding numeric Qdrant point IDs")
    log.info(f"Loaded {len(records)} chunks")

    qdrant_dir = _storage_policy.ensure_private_tree(qdrant_dir)
    client = _client_owner.own(
        QdrantClient(path=str(qdrant_dir)))

    dim = _embedding_dimension(
        embedding_model, security_policy=security_policy)
    collection_exists = client.collection_exists(collection_name)
    old_hashes, rebuild_collection, rebuild_reason = (
        _resolve_incremental_index_state(
            qdrant_dir, backend="qdrant", collection_name=collection_name,
            embedding_model=embedding_model,
            embedding_dimension=dim,
            collection_exists=collection_exists,
            full_reindex=full_reindex,
            active_update_token=_active_update_token,
        )
    )
    collection_existed_at_start = collection_exists
    plan = _vector_lifecycle.plan_reconciliation(chunk_info, old_hashes)
    new_hashes = plan.new_hashes
    expected_chunk_indexes = {
        item.stable_id: item.record["metadata"]["chunk_index"]
        for item in plan.items
    }
    changed_ids = {item.stable_id for item in plan.changed_items}
    unchanged_ids = plan.target_ids.difference(changed_ids)
    update_lifecycle = _new_vector_update_lifecycle(
        qdrant_dir, backend="qdrant", collection_name=collection_name,
        source_sha256=source_sha256,
        source_record_count=source_record_count,
        target_ids=plan.target_ids,
        active_update_token=_active_update_token)
    operation_tracker = _operation_tracker

    if rebuild_collection:
        log.info("Rebuilding Qdrant collection '%s': %s",
                 collection_name, rebuild_reason)

    def _delete_collection() -> None:
        operation_tracker.collection_delete_calls += 1
        client.delete_collection(collection_name)

    def _create_collection():
        operation_tracker.collection_create_calls += 1
        client.create_collection(
            collection_name=collection_name,
            vectors_config=models.VectorParams(
                size=dim,
                distance=models.Distance.COSINE,
            ),
            sparse_vectors_config={
                "bm25": models.SparseVectorParams(
                    modifier=models.Modifier.IDF,
                ),
            },
        )
        return client

    latest_chunk_index_mismatches: set[str] = set()

    def _verify_stable_ids(handle, expected):
        tracked_indexes = {
            stable_id: expected_chunk_indexes[stable_id]
            for stable_id in expected.intersection(unchanged_ids)
        }
        point_ids, mismatches = _inspect_qdrant_chunk_indexes(
            handle, collection_name, expected, tracked_indexes)
        latest_chunk_index_mismatches.clear()
        latest_chunk_index_mismatches.update(mismatches)
        return point_ids

    def _delete_stable_ids(handle, stable_ids, verified_point_ids) -> None:
        # Delete removals and stale versions of changed durable IDs first. A
        # post-delete identity check makes a no-op delete fail closed; the
        # final check likewise catches a no-op replacement upsert.
        points_to_delete = [
            point_id
            for stable_id in stable_ids
            for point_id in verified_point_ids[stable_id]
        ]
        if points_to_delete:
            operation_tracker.record_delete_calls += 1
            delete_result = handle.delete(
                collection_name,
                points_selector=models.PointIdsList(
                    points=points_to_delete),
                wait=True)
            _require_qdrant_update_completed(
                delete_result, "point deletion")

    reconciled = _vector_lifecycle.reconcile_collection(
        lifecycle=update_lifecycle,
        plan=plan,
        handle=client,
        collection_exists=collection_exists,
        rebuild_collection=rebuild_collection,
        delete_collection_fn=_delete_collection,
        create_collection_fn=_create_collection,
        verify_stable_ids_fn=_verify_stable_ids,
        delete_stable_ids_fn=_delete_stable_ids,
    )

    stale_chunk_indexes = set(latest_chunk_index_mismatches)
    metadata_update_count = len(stale_chunk_indexes)
    if stale_chunk_indexes:
        if reconciled.receipt is None:
            raise RuntimeError(
                "Qdrant positional repair requires verified physical IDs")
        verified_point_ids = reconciled.receipt.value
        for item in plan.items:
            if item.stable_id not in stale_chunk_indexes:
                continue
            point_ids = list(verified_point_ids[item.stable_id])
            chunk_index = expected_chunk_indexes[item.stable_id]

            def _update_payload(
                    point_ids=point_ids, chunk_index=chunk_index) -> None:
                operation_tracker.metadata_update_calls += 1
                result = client.set_payload(
                    collection_name=collection_name,
                    payload={"chunk_index": chunk_index},
                    points=point_ids,
                    wait=True,
                )
                _require_qdrant_update_completed(
                    result, "chunk-index payload update")

            update_lifecycle.mutate(_update_payload)
        log.info(
            "Refreshed positional metadata for %d unchanged Qdrant point(s)",
            metadata_update_count)

    def _verify_target_state(expected):
        return _require_qdrant_chunk_indexes(
            client, collection_name, expected, {
                stable_id: expected_chunk_indexes[stable_id]
                for stable_id in expected
            })

    def _save_manifest():
        return _save_index_manifest(
            qdrant_dir, backend="qdrant",
            collection_name=collection_name,
            embedding_model=embedding_model,
            embedding_dimension=dim,
            chunk_hashes=new_hashes, source_sha256=source_sha256,
            source_record_count=source_record_count,
            table_child_count=table_child_count,
            quality_report_schema_version=quality_schema_version,
            quality_report_sha256=quality_report_sha256)

    if old_hashes:
        log.info(
            "Incremental: %d changed, %d unchanged (skipped), %d removed",
            plan.changed_count, plan.unchanged_count, plan.removed_count)

    if not plan.changed_items:
        verification = reconciled.receipt
        if verification is None:
            raise RuntimeError(
                "Vector reconciliation produced no final verification")
        if stale_chunk_indexes:
            verification = update_lifecycle.verify(
                plan.target_ids, _verify_target_state)
        verified_point_ids = update_lifecycle.commit(
            verification,
            close_client_fn=lambda: _client_owner.close(client),
            save_manifest_fn=_save_manifest)
        operation_tracker.committed = True
        verified_count = sum(
            len(ids) for ids in verified_point_ids.values())
        disposition = (
            "created" if not collection_existed_at_start else
            "rebuilt" if rebuild_collection else
            "updated" if plan.removed_count or metadata_update_count else
            "unchanged")
        return _operation_contracts.IndexOutcome(
            backend="qdrant", disposition=disposition,
            total_records=source_record_count,
            changed_records=plan.changed_count,
            unchanged_records=plan.unchanged_count,
            removed_records=plan.removed_count,
            upserted_records=0, batch_count=0,
            physical_count=verified_count, committed=True,
            operations=operation_tracker.contract())
    records = list(plan.changed_records)

    # Pipeline: embed batch N on GPU while upserting batch N-1 to disk
    update_lifecycle.prepare_mutation()
    from concurrent.futures import ThreadPoolExecutor
    BATCH_SIZE = 64
    batches = _batch_index_records(
        records, embedding_model, max_records=BATCH_SIZE)
    pbar = tqdm(total=len(batches), desc="Indexing (Qdrant)", unit="batch")
    upsert_queue: queue.Queue = queue.Queue(maxsize=2)

    def _upsert_worker():
        """Background thread: drain upsert queue."""
        while True:
            item = upsert_queue.get()
            if item is None:
                break

            def _upsert_points() -> None:
                operation_tracker.upsert_calls += 1
                upsert_result = client.upsert(
                    collection_name=collection_name,
                    points=item,
                    wait=True)
                _require_qdrant_update_completed(
                    upsert_result, "point upsert")

            update_lifecycle.mutate(_upsert_points)
            pbar.update(1)
            upsert_queue.task_done()

    upsert_thread = None
    upsert_future = None
    pipeline_error = None
    try:
        upsert_thread = ThreadPoolExecutor(max_workers=1)
        upsert_future = upsert_thread.submit(_upsert_worker)
        for batch in batches:
            # Prepare texts
            texts = []
            for r in batch:
                texts.append(_embedding_text(r))

            # GPU: embed this batch (while previous batch upserts in background)
            dense_vectors = _embed_texts(
                texts, embedding_model, security_policy=security_policy)

            # Build points
            points = []
            for i, r in enumerate(batch):
                stable_id = _chunk_id(r)
                idx = qdrant_point_ids[stable_id]
                payload = _qdrant_payload(r, stable_id)
                lexical_text = _lexical_document_text(
                    r["text"], r.get("metadata", {}))
                sp_indices, sp_values = _sparse_token_vector(lexical_text)
                points.append(models.PointStruct(
                    id=idx,
                    vector={
                        "": dense_vectors[i],
                        "bm25": models.SparseVector(
                            indices=sp_indices, values=sp_values,
                        ),
                    },
                    payload=payload,
                ))

            # Queue for background upsert (blocks if queue full — backpressure)
            _put_unless_worker_failed(
                upsert_queue, points, upsert_future,
                metrics=operation_tracker.queue)
    except BaseException as exc:
        pipeline_error = exc
        raise
    finally:
        _finish_queue_worker(
            upsert_queue, upsert_future, upsert_thread, pbar,
            worker_name="Qdrant upsert worker",
            primary_error=pipeline_error)

    verification = update_lifecycle.verify(
        plan.target_ids, _verify_target_state)
    verified_point_ids = update_lifecycle.commit(
        verification,
        close_client_fn=lambda: _client_owner.close(client),
        save_manifest_fn=_save_manifest)
    operation_tracker.committed = True

    verified_count = sum(len(ids) for ids in verified_point_ids.values())
    log.info(
        f"Qdrant collection '{collection_name}' -> {verified_count} points")
    log.info(f"Embedding: {embedding_model} (dim={dim})")
    log.info("Sparse vectors: BM25 (built-in hybrid search)")
    log.info(f"Persisted to {qdrant_dir}")
    disposition = (
        "created" if not collection_existed_at_start else
        "rebuilt" if rebuild_collection else
        "updated")
    return _operation_contracts.IndexOutcome(
        backend="qdrant", disposition=disposition,
        total_records=source_record_count,
        changed_records=plan.changed_count,
        unchanged_records=plan.unchanged_count,
        removed_records=plan.removed_count,
        upserted_records=plan.changed_count, batch_count=len(batches),
        physical_count=verified_count, committed=True,
        operations=operation_tracker.contract())


def index_chunks_qdrant(chunks_path: Path, qdrant_dir: Path, *,
                        collection_name: str = DEFAULT_COLLECTION,
                        embedding_model: str = DEFAULT_EMBEDDING_MODEL,
                        full_reindex: bool = False,
                        security_policy: (
                            _release_security.ReleaseSecurityPolicy | None
                        ) = None,
                        lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT,
                        _active_update_token: str | None = None,
                        _operation_observer: Callable[
                            [dict[str, int | float | bool]], None]
                        | None = None,
                        ) -> _operation_contracts.IndexOutcome:
    """Index Qdrant under a path-wide, process-safe exclusive lease."""
    operation_tracker = _IndexOperationalTracker()
    try:
        with _vector_store_lock(
                qdrant_dir, backend="qdrant",
                collection_name=collection_name,
                operation="Qdrant indexing", timeout=lock_timeout):
            client_owner = _VectorClientOwner("Qdrant")
            operation_error = None
            try:
                return _index_chunks_qdrant_impl(
                    chunks_path, qdrant_dir,
                    collection_name=collection_name,
                    embedding_model=embedding_model,
                    full_reindex=full_reindex,
                    security_policy=security_policy,
                    _active_update_token=_active_update_token,
                    _client_owner=client_owner,
                    _operation_tracker=operation_tracker,
                )
            except BaseException as exc:
                operation_error = exc
                raise
            finally:
                client_owner.finish(operation_error)
    except BaseException:
        _observe_failed_index_operation(
            _operation_observer, operation_tracker)
        raise


def query_index_qdrant(query: str, qdrant_dir: Path, *,
                       n_results: int = 5,
                       content_type: Optional[str] = None,
                       chapter_num: Optional[int] = None,
                       collection_name: str = DEFAULT_COLLECTION,
                       embedding_model: str = DEFAULT_EMBEDDING_MODEL,
                       output_json: bool = False,
                       use_reranker: bool | None = None,
                       hybrid: bool | None = None,
                       chunks_path: Path = DEFAULT_CHUNKS_PATH,
                       reranker_model: str = DEFAULT_RERANKER_MODEL,
                       overfetch: int = RERANK_OVERFETCH,
                       rrf_k: int = DEFAULT_RRF_K,
                       dense_weight: float = DEFAULT_DENSE_RRF_WEIGHT,
                       sparse_weight: float = DEFAULT_SPARSE_RRF_WEIGHT,
                       context_window: int = 0,
                       context_max_characters: int = (
                           DEFAULT_CONTEXT_MAX_CHARACTERS),
                       context_segment_characters: int = (
                           DEFAULT_CONTEXT_SEGMENT_CHARACTERS),
                       answer: bool = False,
                       cloud_url: str = DEFAULT_CLOUD_URL,
                       cloud_model: str = DEFAULT_CLOUD_MODEL,
                       cloud_key: str = "",
                       ollama_url: str = DEFAULT_OLLAMA_URL,
                       ollama_model: str = DEFAULT_OLLAMA_MODEL,
                       gemini_key: str = "",
                       llm_workers: int = DEFAULT_LLM_WORKERS,
                       thinking: bool = False,
                       lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT,
                       security_policy: (
                           _release_security.ReleaseSecurityPolicy | None
                       ) = None) -> None:
    """Query Qdrant and preserve the legacy CLI/JSON output contract."""
    try:
        response = search_index(
            query, qdrant_dir, db_backend="qdrant", n_results=n_results,
            content_type=content_type, chapter_num=chapter_num,
            collection_name=collection_name, embedding_model=embedding_model,
            use_reranker=use_reranker, hybrid=hybrid,
            chunks_path=chunks_path,
            reranker_model=reranker_model, overfetch=overfetch, rrf_k=rrf_k,
            dense_weight=dense_weight, sparse_weight=sparse_weight,
            context_window=context_window,
            context_max_characters=context_max_characters,
            context_segment_characters=context_segment_characters,
            lock_timeout=lock_timeout,
            security_policy=security_policy,
        )
    except (FileNotFoundError, LookupError) as exc:
        log.error(str(exc))
        log.error("  Run: python rag.py index --db-backend qdrant")
        raise SystemExit(1) from exc

    llm_answer = _answer_search_results(
        query, response,
        answer=answer, cloud_url=cloud_url, cloud_model=cloud_model,
        cloud_key=cloud_key, ollama_url=ollama_url,
        ollama_model=ollama_model, gemini_key=gemini_key,
        llm_workers=llm_workers, thinking=thinking,
        security_policy=security_policy,
    )
    _write_search_output(
        query, response, output_json=output_json, llm_answer=llm_answer,
        content_type=content_type, chapter_num=chapter_num,
    )


# ---------------------------------------------------------------------------
# Step 4: Query (ChromaDB — see query_index_qdrant above for Qdrant)
# ---------------------------------------------------------------------------

_bm25_cache: dict[str, tuple] = {}  # path -> records, BM25, fingerprint, terms
_bm25_cache_lock = _threading.Lock()
_BM25_CACHE_MAX = 5  # evict oldest when exceeded


def _bm25_search(query: str, chunks_path: Path, n_results: int,
                 content_type: Optional[str] = None,
                 chapter_num: Optional[int] = None, *,
                 expected_source_sha256: str | None = None) -> tuple:
    """BM25 keyword search over chunks JSONL.

    Caches the BM25 index per file (reloads only if file changed).
    Returns (documents, metadatas, scores) sorted by BM25 score descending.
    """
    from rank_bm25 import BM25Okapi

    cache_key = str(chunks_path.resolve())
    raw, source_sha256, artifact_fingerprint = (
        _read_index_artifact_snapshot(chunks_path))
    if (expected_source_sha256 is not None
            and source_sha256 != expected_source_sha256):
        raise ValueError(
            f"BM25 chunks snapshot changed from the indexed corpus: "
            f"{chunks_path}")
    fingerprint = (
        artifact_fingerprint, source_sha256, INDEX_MANIFEST_SCHEMA_VERSION)

    with _bm25_cache_lock:
        cached = _bm25_cache.get(cache_key)
    if cached is not None and cached[2] == fingerprint:
        all_records, bm25 = cached[0], cached[1]
        corpus_terms = cached[3]
    else:
        all_records = _parse_index_records_strict(raw, chunks_path)

        corpus = [
            _legal_search_tokens(_lexical_document_text(
                rec["text"], rec.get("metadata", {}))) or ["__rag_empty__"]
            for rec in all_records
        ]
        bm25 = BM25Okapi(corpus) if corpus else None
        corpus_terms = [set(tokens) for tokens in corpus]
        with _bm25_cache_lock:
            _bm25_cache[cache_key] = (
                all_records, bm25, fingerprint, corpus_terms)
            # Evict oldest entries if cache exceeds limit
            while len(_bm25_cache) > _BM25_CACHE_MAX:
                oldest = next(iter(_bm25_cache))
                del _bm25_cache[oldest]

    if not all_records or bm25 is None:
        return [], [], []

    # Apply metadata filters post-cache
    filtered_indices = []
    for i, rec in enumerate(all_records):
        if content_type and rec["metadata"].get("content_type") != content_type:
            continue
        if chapter_num is not None and rec["metadata"].get("chapter_num") != chapter_num:
            continue
        filtered_indices.append(i)

    if not filtered_indices:
        return [], [], []

    # Score all documents, then filter
    query_tokens = _legal_search_tokens(query)
    if not query_tokens:
        return [], [], []
    all_scores = bm25.get_scores(query_tokens)

    scored = [
        (all_scores[i], all_records[i]) for i in filtered_indices
        if (math.isfinite(float(all_scores[i]))
            and bool(corpus_terms[i].intersection(query_tokens)))
    ]
    scored.sort(key=lambda x: x[0], reverse=True)
    scored = scored[:n_results]
    return (
        [s[1]["text"] for s in scored],
        [
            {
                **s[1]["metadata"],
                "stable_id": _chunk_id(s[1]),
            }
            for s in scored
        ],
        [float(s[0]) for s in scored],
    )


_reciprocal_rank_fusion = _retrieval_core._reciprocal_rank_fusion


_build_chroma_where = _retrieval_core._build_chroma_where


def _record_search_warning(warnings: list[str], message: str) -> None:
    """Record a machine-readable warning and also surface it in logs."""
    warnings.append(message)
    log.warning(message)


def _unpack_chroma_results(results: dict) -> tuple[list[str], list[dict],
                                                    list[float]]:
    """Normalize Chroma's nested single-query result shape."""
    documents = results.get("documents") or [[]]
    metadatas = results.get("metadatas") or [[]]
    distances = results.get("distances") or [[]]
    docs = list(documents[0] or [])
    metas = [dict(meta or {}) for meta in (metadatas[0] or [])]
    # Older Chroma indexes stored ``context + text`` as the document.  New
    # indexes store raw text, but normalize legacy results during migration so
    # callers receive the same payload shape from both backends.
    for index, (doc, meta) in enumerate(zip(docs, metas)):
        context = meta.get("context", "")
        prefix = f"{context}\n\n" if context else ""
        if prefix and doc.startswith(prefix):
            docs[index] = doc[len(prefix):]
    scores = [1.0 - float(distance) for distance in (distances[0] or [])]
    return docs, metas, scores


def _search_chroma_candidates_impl(
        query: str, db_dir: Path, *, n_results: int,
        content_type: str | None, chapter_num: int | None,
        collection_name: str, embedding_model: str, hybrid: bool,
        chunks_path: Path, warnings: list[str],
        rrf_k: int = DEFAULT_RRF_K,
        dense_weight: float = DEFAULT_DENSE_RRF_WEIGHT,
        sparse_weight: float = DEFAULT_SPARSE_RRF_WEIGHT,
        expected_dimension: int | None = None,
        expected_source_sha256: str | None = None,
        security_policy: (
            _release_security.ReleaseSecurityPolicy | None
        ) = None,
        _client_owner: _VectorClientOwner,
) -> tuple[list[str], list[dict], list[float], str]:
    """Retrieve Chroma candidates, falling back cleanly from BM25."""
    import chromadb

    client = _client_owner.own(
        chromadb.PersistentClient(
            path=str(db_dir), **_chroma_settings_kwargs(chromadb)))
    try:
        collection = client.get_collection(collection_name)
    except Exception as exc:
        raise LookupError(
            f"Collection '{collection_name}' not found in {db_dir}") from exc

    where = _build_chroma_where(content_type, chapter_num)
    fetch_n = n_results
    query_vector = _embed_texts(
        [query], embedding_model, input_type="query",
        security_policy=security_policy)[0]
    _validate_query_vector_dimension(
        query_vector, expected_dimension, embedding_model)
    query_kwargs = {
        "query_embeddings": [query_vector],
        "n_results": fetch_n,
        "include": ["documents", "metadatas", "distances"],
    }
    if where is not None:
        query_kwargs["where"] = where

    def vector_search():
        return collection.query(**query_kwargs)

    if not hybrid:
        return (*_unpack_chroma_results(vector_search()), "vector")

    if not chunks_path.is_file():
        _record_search_warning(
            warnings,
            f"Hybrid search requested but chunks file '{chunks_path}' is "
            "unavailable; used vector search.",
        )
        return (*_unpack_chroma_results(vector_search()), "vector")

    from concurrent.futures import ThreadPoolExecutor

    with ThreadPoolExecutor(max_workers=2) as pool:
        vector_future = pool.submit(vector_search)
        bm25_future = pool.submit(
            _bm25_search, query, chunks_path, fetch_n,
            content_type=content_type, chapter_num=chapter_num,
            expected_source_sha256=expected_source_sha256,
        )
        vector_results = vector_future.result()
        try:
            bm25_docs, bm25_metas, bm25_scores = bm25_future.result()
        except Exception as exc:
            _record_search_warning(
                warnings,
                f"Hybrid BM25 search failed ({exc}); used vector search.",
            )
            return (*_unpack_chroma_results(vector_results), "vector")

    docs, metas, scores = _unpack_chroma_results(vector_results)
    if not bm25_docs:
        _record_search_warning(
            warnings,
            "Hybrid BM25 search returned no candidates; used vector search.",
        )
        return docs, metas, scores, "vector"

    dense_ranked = list(zip(docs, metas, scores))
    sparse_ranked = list(zip(bm25_docs, bm25_metas, bm25_scores))
    merged = _reciprocal_rank_fusion(
        [dense_ranked, sparse_ranked], k=rrf_k, top_n=fetch_n,
        weights=[dense_weight, sparse_weight])
    log.debug(
        "Hybrid: %d vector + %d BM25 -> %d merged",
        len(dense_ranked), len(sparse_ranked), len(merged),
    )
    return (
        [item[0] for item in merged],
        [dict(item[1] or {}) for item in merged],
        [float(item[2]) for item in merged],
        "hybrid",
    )


def _search_chroma_candidates(
        query: str, db_dir: Path, *, n_results: int,
        content_type: str | None, chapter_num: int | None,
        collection_name: str, embedding_model: str, hybrid: bool,
        chunks_path: Path, warnings: list[str],
        rrf_k: int = DEFAULT_RRF_K,
        dense_weight: float = DEFAULT_DENSE_RRF_WEIGHT,
        sparse_weight: float = DEFAULT_SPARSE_RRF_WEIGHT,
        expected_dimension: int | None = None,
        expected_source_sha256: str | None = None,
        security_policy: (
            _release_security.ReleaseSecurityPolicy | None
        ) = None,
) -> tuple[list[str], list[dict], list[float], str]:
    """Retrieve Chroma candidates and deterministically close the client."""
    client_owner = _VectorClientOwner("Chroma")
    operation_error = None
    try:
        return _search_chroma_candidates_impl(
            query, db_dir, n_results=n_results,
            content_type=content_type, chapter_num=chapter_num,
            collection_name=collection_name,
            embedding_model=embedding_model, hybrid=hybrid,
            chunks_path=chunks_path, warnings=warnings,
            rrf_k=rrf_k, dense_weight=dense_weight,
            sparse_weight=sparse_weight,
            expected_dimension=expected_dimension,
            expected_source_sha256=expected_source_sha256,
            security_policy=security_policy,
            _client_owner=client_owner,
        )
    except BaseException as exc:
        operation_error = exc
        raise
    finally:
        client_owner.finish(operation_error)


def _search_qdrant_candidates(
        query: str, db_dir: Path, *, n_results: int,
        content_type: str | None, chapter_num: int | None,
        collection_name: str, embedding_model: str, hybrid: bool,
        warnings: list[str], expected_dimension: int | None = None,
        security_policy: (
            _release_security.ReleaseSecurityPolicy | None
        ) = None,
) -> tuple[list[str], list[dict], list[float], str]:
    """Retrieve Qdrant candidates with native dense/sparse fusion."""
    from qdrant_client import QdrantClient, models

    client = None
    operation_error = None
    try:
        client = QdrantClient(path=str(db_dir))
        if not client.collection_exists(collection_name):
            raise LookupError(
                f"Collection '{collection_name}' not found in {db_dir}")

        conditions = []
        if content_type:
            conditions.append(models.FieldCondition(
                key="content_type",
                match=models.MatchValue(value=content_type),
            ))
        if chapter_num is not None:
            conditions.append(models.FieldCondition(
                key="chapter_num",
                match=models.MatchValue(value=chapter_num),
            ))
        query_filter = models.Filter(must=conditions) if conditions else None

        fetch_n = n_results
        query_vector = _embed_texts(
            [query], embedding_model, input_type="query",
            security_policy=security_policy)[0]
        _validate_query_vector_dimension(
            query_vector, expected_dimension, embedding_model)
        effective_mode = "vector"

        if hybrid:
            sparse_indices, sparse_values = _sparse_token_vector(query)
            sparse_vector = models.SparseVector(
                indices=sparse_indices,
                values=sparse_values,
            )
            try:
                results = client.query_points(
                    collection_name=collection_name,
                    prefetch=[
                        models.Prefetch(
                            query=query_vector, using="", limit=fetch_n,
                            filter=query_filter,
                        ),
                        models.Prefetch(
                            query=sparse_vector, using="bm25", limit=fetch_n,
                            filter=query_filter,
                        ),
                    ],
                    query=models.FusionQuery(fusion=models.Fusion.RRF),
                    limit=fetch_n,
                )
                effective_mode = "hybrid"
            except Exception as exc:
                _record_search_warning(
                    warnings,
                    f"Qdrant hybrid search failed ({exc}); used vector search.",
                )
                results = client.query_points(
                    collection_name=collection_name,
                    query=query_vector, using="", limit=fetch_n,
                    query_filter=query_filter,
                )
        else:
            results = client.query_points(
                collection_name=collection_name,
                query=query_vector, using="", limit=fetch_n,
                query_filter=query_filter,
            )

        docs = []
        metas = []
        scores = []
        for point in results.points:
            payload = dict(point.payload or {})
            docs.append(str(payload.pop("text", "")))
            metas.append(payload)
            scores.append(float(point.score))
        return docs, metas, scores, effective_mode
    except BaseException as exc:
        operation_error = exc
        raise
    finally:
        _finish_vector_client(
            client, client_name="Qdrant",
            primary_error=operation_error)


def _search_hit_source_id(hit: SearchHit) -> str:
    """Resolve a source ID through the compatibility facade's chunk helper."""
    return _retrieval_core._search_hit_source_id(
        hit, chunk_id_fn=_chunk_id)


def _search_index_impl(query: str, db_dir: Path, *,
                       db_backend: str = DEFAULT_DB_BACKEND,
                       n_results: int = 5,
                       content_type: Optional[str] = None,
                       chapter_num: Optional[int] = None,
                       collection_name: str = DEFAULT_COLLECTION,
                       embedding_model: str = DEFAULT_EMBEDDING_MODEL,
                       use_reranker: bool | None = None,
                       hybrid: bool | None = None,
                       chunks_path: Path = DEFAULT_CHUNKS_PATH,
                       reranker_model: str = DEFAULT_RERANKER_MODEL,
                       overfetch: int = RERANK_OVERFETCH,
                       rrf_k: int = DEFAULT_RRF_K,
                       dense_weight: float = DEFAULT_DENSE_RRF_WEIGHT,
                       sparse_weight: float = DEFAULT_SPARSE_RRF_WEIGHT,
                       context_window: int = 0,
                       context_max_characters: int = (
                           DEFAULT_CONTEXT_MAX_CHARACTERS),
                       context_segment_characters: int = (
                           DEFAULT_CONTEXT_SEGMENT_CHARACTERS),
                       lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT,
                       security_policy: (
                           _release_security.ReleaseSecurityPolicy | None
                       ) = None,
                       ) -> SearchResponse:
    """Search either supported vector backend and return structured results.

    Hybrid and reranker requests over-fetch candidates before reducing them to
    ``n_results``.  Any recoverable hybrid or reranking failure is reflected in
    ``effective_mode``, ``reranker_applied``, and ``warnings`` rather than being
    mislabeled as a successful requested mode.
    """
    policy = _effective_security_policy(security_policy)
    if embedding_model.startswith(_API_EMBEDDING_MODEL_PREFIXES):
        _release_security.require_cloud_egress(
            policy, feature="cloud embedding")
    if (
        use_reranker is not False
        and reranker_model.startswith(("cohere-rerank", "jina-reranker"))
    ):
        _release_security.require_cloud_egress(
            policy, feature="cloud reranking")
    backend = db_backend.lower()
    if backend not in {"chroma", "qdrant"}:
        raise ValueError("db_backend must be 'chroma' or 'qdrant'")
    if not query.strip():
        raise ValueError("query must not be blank")
    if n_results < 1:
        raise ValueError("n_results must be at least 1")
    if isinstance(overfetch, bool) or not isinstance(overfetch, int) \
            or not 1 <= overfetch <= 20:
        raise ValueError("overfetch must be an integer from 1 to 20")
    if isinstance(rrf_k, bool) or not isinstance(rrf_k, int) or rrf_k < 1:
        raise ValueError("rrf_k must be a positive integer")
    if (isinstance(context_window, bool)
            or not isinstance(context_window, int)
            or not 0 <= context_window <= MAX_CONTEXT_WINDOW):
        raise ValueError(
            f"context_window must be an integer from 0 to {MAX_CONTEXT_WINDOW}")
    if (isinstance(context_max_characters, bool)
            or not isinstance(context_max_characters, int)
            or not 1 <= context_max_characters <= MAX_CONTEXT_CHARACTERS):
        raise ValueError(
            "context_max_characters must be an integer from 1 to "
            f"{MAX_CONTEXT_CHARACTERS}")
    if (isinstance(context_segment_characters, bool)
            or not isinstance(context_segment_characters, int)
            or not 1 <= context_segment_characters
            <= MAX_CONTEXT_SEGMENT_CHARACTERS):
        raise ValueError(
            "context_segment_characters must be an integer from 1 to "
            f"{MAX_CONTEXT_SEGMENT_CHARACTERS}")
    try:
        dense_weight = float(dense_weight)
        sparse_weight = float(sparse_weight)
    except (TypeError, ValueError) as exc:
        raise ValueError("fusion weights must be numeric") from exc
    if (not math.isfinite(dense_weight) or not math.isfinite(sparse_weight)
            or dense_weight < 0 or sparse_weight < 0
            or dense_weight + sparse_weight == 0):
        raise ValueError(
            "fusion weights must be finite, non-negative, and not both zero")

    db_path = Path(db_dir)
    if not db_path.is_dir():
        raise FileNotFoundError(f"{backend.title()} directory not found: {db_path}")

    requested_mode = (
        "auto" if hybrid is None else "hybrid" if hybrid else "vector")
    warnings: list[str] = []
    chunks_file = Path(chunks_path)
    context_records: list[dict] | None = None
    context_source_sha256: str | None = None
    indexed_table_children = 0
    if context_window:
        if not chunks_file.is_file():
            raise FileNotFoundError(
                f"Context assembly requires chunks JSONL: {chunks_file}")
        context_records, context_source_sha256, _, _ = (
            _load_index_snapshot_with_quality(chunks_file))
    hybrid_enabled = (
        backend == "qdrant" or chunks_file.is_file()) if hybrid is None else hybrid
    if backend == "qdrant" and hybrid_enabled and rrf_k != DEFAULT_RRF_K:
        _record_search_warning(
            warnings,
            "Custom RRF k applies only to Chroma; Qdrant used its native RRF.",
        )
    if (backend == "qdrant" and hybrid_enabled
            and (dense_weight != DEFAULT_DENSE_RRF_WEIGHT
                 or sparse_weight != DEFAULT_SPARSE_RRF_WEIGHT)):
        _record_search_warning(
            warnings,
            "Custom fusion weights apply only to Chroma; Qdrant used native RRF.",
        )
    with _vector_store_lock(
            db_path, backend=backend, collection_name=collection_name,
            operation="vector search", timeout=lock_timeout):
        db_path = _storage_policy.ensure_private_tree(db_path)
        expected_dimension = _query_manifest_dimension(
            db_path, backend=backend, collection_name=collection_name,
            embedding_model=embedding_model,
            allow_legacy=not bool(context_window))
        indexed_table_children = _indexed_table_child_count(
            db_path, backend=backend, collection_name=collection_name)
        hybrid_source_sha256 = None
        if context_records is not None:
            manifested_source_sha256 = _require_hybrid_chunks_snapshot(
                chunks_file, db_path, backend=backend,
                collection_name=collection_name)
            if (manifested_source_sha256 is None
                    or manifested_source_sha256 != context_source_sha256):
                raise ValueError(
                    "Context chunks snapshot does not match the indexed corpus")
            if backend == "chroma":
                hybrid_source_sha256 = manifested_source_sha256
        if backend == "chroma" and hybrid_enabled and chunks_file.is_file():
            if hybrid_source_sha256 is None:
                hybrid_source_sha256 = _require_hybrid_chunks_snapshot(
                    chunks_file, db_path, backend=backend,
                    collection_name=collection_name)
            if hybrid_source_sha256 is None:
                _record_search_warning(
                    warnings,
                    "Hybrid search requires a manifested chunks SHA-256; used "
                    "vector search for this legacy or incomplete index.",
                )
                hybrid_enabled = False
        fetch_n = (
            n_results * overfetch
            if (hybrid_enabled or use_reranker is not False
                or indexed_table_children) else n_results)

        if backend == "chroma":
            docs, metas, scores, effective_mode = _search_chroma_candidates(
                query, db_path, n_results=fetch_n,
                content_type=content_type, chapter_num=chapter_num,
                collection_name=collection_name,
                embedding_model=embedding_model,
                hybrid=hybrid_enabled, chunks_path=chunks_file,
                warnings=warnings, rrf_k=rrf_k,
                dense_weight=dense_weight, sparse_weight=sparse_weight,
                expected_dimension=expected_dimension,
                expected_source_sha256=hybrid_source_sha256,
                security_policy=policy,
            )
        else:
            docs, metas, scores, effective_mode = _search_qdrant_candidates(
                query, db_path, n_results=fetch_n,
                content_type=content_type, chapter_num=chapter_num,
                collection_name=collection_name,
                embedding_model=embedding_model, hybrid=hybrid_enabled,
                warnings=warnings, expected_dimension=expected_dimension,
                security_policy=policy,
            )

        if (backend == "chroma" and effective_mode == "hybrid"
                and chunks_file.is_file()):
            # Close the lexical-artifact TOCTOU window: a standalone atomic
            # replacement racing this search must be checked again after BM25
            # has consumed its exact snapshot.
            _require_hybrid_chunks_snapshot(
                chunks_file, db_path, backend=backend,
                collection_name=collection_name)

    if indexed_table_children:
        docs, metas, scores = _table_retrieval_core.collapse_table_families(
            docs, metas, scores)

    reranker_enabled = (
        effective_mode == "vector" if use_reranker is None else use_reranker)
    reranker_applied = False
    if reranker_enabled and len(docs) > 1:
        try:
            docs, metas, scores = _rerank(
                query, docs, metas, [1.0 - score for score in scores],
                n_results, reranker_model=reranker_model,
                security_policy=policy,
            )
            reranker_applied = True
        except Exception as exc:
            _record_search_warning(
                warnings,
                f"Reranker failed ({exc}); kept {effective_mode} ranking.",
            )
    elif reranker_enabled:
        _record_search_warning(
            warnings,
            "Reranker requested but fewer than two candidates were available; "
            "reranking was not applied.",
        )

    hits = []
    for doc, meta, score in zip(
            docs[:n_results], metas[:n_results], scores[:n_results]):
        hit = SearchHit(
            text=doc, metadata=dict(meta or {}), score=float(score))
        hit.source_id = _search_hit_source_id(hit)
        hits.append(hit)
    response = SearchResponse(
        hits=hits, backend=backend, requested_mode=requested_mode,
        effective_mode=effective_mode,
        reranker_applied=reranker_applied, warnings=warnings,
        candidate_depth=fetch_n,
        reranker_model=reranker_model if reranker_applied else None,
    )
    if context_records is not None:
        _retrieval_core._assemble_retrieval_context(
            response, context_records,
            context_window=context_window,
            content_type=content_type,
            chapter_num=chapter_num,
            max_characters=context_max_characters,
            segment_characters=context_segment_characters,
            source_id_fn=_search_hit_source_id,
        )
    return response


def search_index(query: str, db_dir: Path, *,
                 db_backend: str = DEFAULT_DB_BACKEND,
                 n_results: int = 5,
                 content_type: Optional[str] = None,
                 chapter_num: Optional[int] = None,
                 collection_name: str = DEFAULT_COLLECTION,
                 embedding_model: str = DEFAULT_EMBEDDING_MODEL,
                 use_reranker: bool | None = None,
                 hybrid: bool | None = None,
                 chunks_path: Path = DEFAULT_CHUNKS_PATH,
                 reranker_model: str = DEFAULT_RERANKER_MODEL,
                 overfetch: int = RERANK_OVERFETCH,
                 rrf_k: int = DEFAULT_RRF_K,
                 dense_weight: float = DEFAULT_DENSE_RRF_WEIGHT,
                 sparse_weight: float = DEFAULT_SPARSE_RRF_WEIGHT,
                 context_window: int = 0,
                 context_max_characters: int = (
                     DEFAULT_CONTEXT_MAX_CHARACTERS),
                 context_segment_characters: int = (
                     DEFAULT_CONTEXT_SEGMENT_CHARACTERS),
                 lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT,
                 security_policy: (
                     _release_security.ReleaseSecurityPolicy | None
                 ) = None,
                 ) -> SearchResponse:
    """Search a coherent local index generation under its exclusive lease."""
    backend = db_backend.lower()
    if backend not in {"chroma", "qdrant"}:
        # Preserve the public validation error without creating a lock sidecar.
        return _search_index_impl(
            query, db_dir, db_backend=db_backend, n_results=n_results,
            content_type=content_type, chapter_num=chapter_num,
            collection_name=collection_name,
            embedding_model=embedding_model, use_reranker=use_reranker,
            hybrid=hybrid, chunks_path=chunks_path,
            reranker_model=reranker_model, overfetch=overfetch, rrf_k=rrf_k,
            dense_weight=dense_weight, sparse_weight=sparse_weight,
            context_window=context_window,
            context_max_characters=context_max_characters,
            context_segment_characters=context_segment_characters,
            lock_timeout=lock_timeout,
            security_policy=security_policy)
    db_path = Path(db_dir)
    return _search_index_impl(
        query, db_path, db_backend=backend, n_results=n_results,
        content_type=content_type, chapter_num=chapter_num,
        collection_name=collection_name,
        embedding_model=embedding_model, use_reranker=use_reranker,
        hybrid=hybrid, chunks_path=chunks_path,
        reranker_model=reranker_model, overfetch=overfetch, rrf_k=rrf_k,
        dense_weight=dense_weight, sparse_weight=sparse_weight,
        context_window=context_window,
        context_max_characters=context_max_characters,
        context_segment_characters=context_segment_characters,
        lock_timeout=lock_timeout,
        security_policy=security_policy)


_ANSWER_SOURCE_LIMIT = _retrieval_core._ANSWER_SOURCE_LIMIT
_ANSWER_SOURCE_CHAR_LIMIT = _retrieval_core._ANSWER_SOURCE_CHAR_LIMIT
_INSUFFICIENT_EVIDENCE_TEXT = _retrieval_core._INSUFFICIENT_EVIDENCE_TEXT
_BRACKETED_TEXT_RE = _retrieval_core._BRACKETED_TEXT_RE
_SOURCE_CITATION_RE = _retrieval_core._SOURCE_CITATION_RE
_DIRECT_QUOTE_RE = _retrieval_core._DIRECT_QUOTE_RE


_useful_source_metadata = _retrieval_core._useful_source_metadata


_query_centered_excerpt = _retrieval_core._query_centered_excerpt


def _grounded_sources(response: SearchResponse,
                      query: str = "") -> list[GroundedSource]:
    """Build sources through the facade's dynamically replaceable resolver."""
    return _retrieval_core._grounded_sources(
        response, query, source_id_fn=_search_hit_source_id)


_grounded_answer_prompt = _retrieval_core._grounded_answer_prompt


_validate_grounded_answer = _retrieval_core._validate_grounded_answer


def _answer_search_results(query: str, response: SearchResponse, *,
                           answer: bool, cloud_url: str, cloud_model: str,
                           cloud_key: str, ollama_url: str,
                           ollama_model: str, gemini_key: str,
                           llm_workers: int = DEFAULT_LLM_WORKERS,
                           thinking: bool = False,
                           security_policy: (
                               _release_security.ReleaseSecurityPolicy | None
                           ) = None) -> GroundedAnswer | None:
    """Optionally generate a source-grounded answer from structured hits."""
    if not answer:
        return None
    sources = _grounded_sources(response, query)
    if not sources:
        return GroundedAnswer(
            text=_INSUFFICIENT_EVIDENCE_TEXT,
            citations=[], sources=[],
            warnings=["No retrieved sources were available for answer generation."],
            abstained=True,
        )

    answer_prompt = _grounded_answer_prompt(query, sources)
    llm_answer = _call_llm(
        answer_prompt, cloud_url=cloud_url, cloud_model=cloud_model,
        cloud_key=cloud_key, ollama_url=ollama_url,
        ollama_model=ollama_model, gemini_key=gemini_key,
        llm_workers=llm_workers, thinking=thinking,
        operation="query.grounded_answer",
        security_policy=security_policy,
    )
    if not llm_answer:
        return GroundedAnswer(
            text=_INSUFFICIENT_EVIDENCE_TEXT,
            citations=[], sources=sources,
            warnings=["The configured language model returned no answer."],
            abstained=True,
        )
    return _validate_grounded_answer(llm_answer, sources)


def _write_search_output(query: str, response: SearchResponse, *,
                         output_json: bool,
                         llm_answer: GroundedAnswer | str | None,
                         content_type: str | None,
                         chapter_num: int | None) -> None:
    """Render structured results using the existing CLI/JSON schema."""
    output_hits = []
    for hit in response.hits:
        output_hit = {
            "score": round(hit.score, 4),
            "search_mode": response.effective_mode,
            "reranked": response.reranker_applied,
            "text": hit.text,
            "metadata": hit.metadata,
        }
        if response.context_window:
            output_hit["source_id"] = hit.source_id
            output_hit["equivalent_sources"] = [
                {
                    "source_id": alias.source_id,
                    "metadata": alias.metadata,
                }
                for alias in hit.source_aliases
            ]
            output_hit["context"] = [
                {
                    "source_id": segment.source_id,
                    "relation": segment.relation,
                    "distance": segment.distance,
                    "text": segment.text,
                    "metadata": segment.metadata,
                    "equivalent_sources": [
                        {
                            "source_id": alias.source_id,
                            "metadata": alias.metadata,
                        }
                        for alias in segment.source_aliases
                    ],
                }
                for segment in hit.context_segments
            ]
        output_hits.append(output_hit)
    if output_json:
        payload: object = output_hits
        if llm_answer:
            if isinstance(llm_answer, GroundedAnswer):
                # Preserve the established string-valued ``answer`` and
                # ``results`` keys while adding machine-readable grounding.
                payload = {
                    "answer": llm_answer.text,
                    "citations": llm_answer.citations,
                    "sources": llm_answer.source_mapping(),
                    "answer_warnings": llm_answer.warnings,
                    "abstained": llm_answer.abstained,
                    "results": output_hits,
                }
            else:
                payload = {"answer": llm_answer, "results": output_hits}
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return

    if llm_answer:
        answer_text = (
            llm_answer.text
            if isinstance(llm_answer, GroundedAnswer)
            else llm_answer
        )
        print(f"\n{'=' * 80}")
        print("ANSWER")
        print("=" * 80)
        print(answer_text)
        if isinstance(llm_answer, GroundedAnswer):
            cited_sources = llm_answer.source_mapping(cited_only=True)
            if cited_sources:
                print("\nSources:")
                for citation_id, source in cited_sources.items():
                    meta = source["metadata"]
                    location = " | ".join(str(value) for value in (
                        meta.get("source_file"),
                        meta.get("page_range"),
                        meta.get("section_path"),
                    ) if value not in (None, ""))
                    suffix = f" — {location}" if location else ""
                    print(
                        f"  [{citation_id}] {source['source_id']}{suffix}")
            for warning in llm_answer.warnings:
                print(f"Warning: {warning}")

    print(f"\n{'=' * 80}")
    print(f"Query: {query}")
    mode = response.effective_mode
    if response.backend == "qdrant":
        mode = f"qdrant {mode}"
    if response.reranker_applied:
        mode += " + reranked"
    requested = (f"; requested={response.requested_mode}"
                 if response.requested_mode != response.effective_mode else "")
    print(f"Mode:  {mode}{requested}")
    print(f"Candidate depth: {response.candidate_depth}")
    if response.reranker_model:
        print(f"Reranker: {response.reranker_model}")
    if content_type or chapter_num is not None:
        print(f"Filters: content_type={content_type}, chapter={chapter_num}")
    score_label = ("rerank" if response.reranker_applied else
                   "rrf" if response.effective_mode == "hybrid" else
                   "similarity")
    print(f"{'=' * 80}\n")

    for index, hit in enumerate(response.hits, 1):
        meta = hit.metadata
        print(f"--- Result {index} ({score_label}: {hit.score:.3f}) ---")
        print(f"  Type:    {meta.get('content_type', '?')}")
        print(f"  Section: {meta.get('section_path', '?')}")
        print(f"  Case:    {meta.get('primary_case', 'n/a')}")
        print(f"  Pages:   {meta.get('page_range', '?')}")
        context = meta.get("context", "")
        if context:
            print(f"  Context: {context}")
        print(f"  Text:    {hit.text[:300]}...")
        for segment in hit.context_segments:
            label = f"{segment.relation} {segment.distance}"
            print(
                f"  Neighbor ({label}, {segment.source_id}): "
                f"{segment.text[:300]}...")
        print()


def query_index(query: str, chroma_dir: Path, *,
                n_results: int = 5,
                content_type: Optional[str] = None,
                chapter_num: Optional[int] = None,
                collection_name: str = DEFAULT_COLLECTION,
                embedding_model: str = DEFAULT_EMBEDDING_MODEL,
                output_json: bool = False,
                use_reranker: bool | None = None,
                hybrid: bool | None = None,
                chunks_path: Path = DEFAULT_CHUNKS_PATH,
                reranker_model: str = DEFAULT_RERANKER_MODEL,
                overfetch: int = RERANK_OVERFETCH,
                rrf_k: int = DEFAULT_RRF_K,
                dense_weight: float = DEFAULT_DENSE_RRF_WEIGHT,
                sparse_weight: float = DEFAULT_SPARSE_RRF_WEIGHT,
                context_window: int = 0,
                context_max_characters: int = (
                    DEFAULT_CONTEXT_MAX_CHARACTERS),
                context_segment_characters: int = (
                    DEFAULT_CONTEXT_SEGMENT_CHARACTERS),
                answer: bool = False,
                cloud_url: str = DEFAULT_CLOUD_URL,
                cloud_model: str = DEFAULT_CLOUD_MODEL,
                cloud_key: str = "",
                ollama_url: str = DEFAULT_OLLAMA_URL,
                ollama_model: str = DEFAULT_OLLAMA_MODEL,
                gemini_key: str = "",
                llm_workers: int = DEFAULT_LLM_WORKERS,
                thinking: bool = False,
                lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT,
                security_policy: (
                    _release_security.ReleaseSecurityPolicy | None
                ) = None) -> None:
    """Query Chroma and preserve the legacy CLI/JSON output contract."""
    try:
        response = search_index(
            query, chroma_dir, db_backend="chroma", n_results=n_results,
            content_type=content_type, chapter_num=chapter_num,
            collection_name=collection_name, embedding_model=embedding_model,
            use_reranker=use_reranker, hybrid=hybrid,
            chunks_path=chunks_path,
            reranker_model=reranker_model, overfetch=overfetch, rrf_k=rrf_k,
            dense_weight=dense_weight, sparse_weight=sparse_weight,
            context_window=context_window,
            context_max_characters=context_max_characters,
            context_segment_characters=context_segment_characters,
            lock_timeout=lock_timeout,
            security_policy=security_policy,
        )
    except (FileNotFoundError, LookupError) as exc:
        log.error(str(exc))
        log.error("  Run: python rag.py index")
        raise SystemExit(1) from exc

    llm_answer = _answer_search_results(
        query, response,
        answer=answer, cloud_url=cloud_url, cloud_model=cloud_model,
        cloud_key=cloud_key, ollama_url=ollama_url,
        ollama_model=ollama_model, gemini_key=gemini_key,
        llm_workers=llm_workers, thinking=thinking,
        security_policy=security_policy,
    )
    _write_search_output(
        query, response, output_json=output_json, llm_answer=llm_answer,
        content_type=content_type, chapter_num=chapter_num,
    )


# ---------------------------------------------------------------------------
# Step 5: Export — clean, LLM-ready markdown
# ---------------------------------------------------------------------------

_MARKDOWN_ENDNOTE_SERIALIZATION_VERSION = 10
_MARKDOWN_CURRENCY_ESCAPE_VERSION = 3
_MARKDOWN_SOURCE_LITERAL_ESCAPE_VERSION = 5
_MARKDOWN_TABLE_CELL_PADDING_VERSION = 2
_MARKDOWN_EMPHASIS_MARKER = "_"
_MARKDOWN_THEMATIC_BREAK_NORMALIZATION_VERSION = 2
_MARKDOWN_IMPLICIT_REFERENCE_ESCAPE_VERSION = 2
_MARKDOWN_ORDERED_LIST_LITERAL_ESCAPE_VERSION = 1
_MARKDOWN_SPLIT_MATTER_PARTITION_VERSION = 1
_MARKDOWN_HEADING_HIERARCHY_VERSION = 2
_MARKDOWN_CASE_HEADING_VERSION = 2
_MARKDOWN_FIGURE_ASSET_VERSION = 1
_MARKDOWN_CONTENT_TYPE_RENDERING_VERSION = 2
_MARKDOWN_PAGE_MARKER_VERSION = 1
_MARKDOWN_FOOTNOTE_DIALECT = "pandoc"
_MARKDOWN_ENDNOTE_STABLE_ID_RE = re.compile(
    r"^chunk_([0-9a-f]{16})$")
_MARKDOWN_ENDNOTE_OPENING_RE = re.compile(
    r"(?m)^\s*(\d{1,4}|[a-z]|\*(?!\s*\*))(?:[.)])?(?:\s+|$)")
_MARKDOWN_INTERNAL_FOOTNOTE_REFERENCE_RE = re.compile(
    r"\[\^(rag-fn-[0-9a-f]{16})\]")
_MARKDOWN_SUPERSCRIPT_DIGIT_RE = re.compile(r"[\u2070\u00b9\u00b2\u00b3\u2074-\u2079]{1,4}")
_MARKDOWN_SUPERSCRIPT_DIGITS = str.maketrans({
    "\u2070": "0", "\u00b9": "1", "\u00b2": "2", "\u00b3": "3",
    "\u2074": "4", "\u2075": "5", "\u2076": "6", "\u2077": "7",
    "\u2078": "8", "\u2079": "9",
})
_MARKDOWN_CAPTION_TERMINAL_DECIMAL_RE = re.compile(
    r"(?<=[^\W\d_])(\d{1,4})$", re.UNICODE)
_MARKDOWN_SHA256_RE = re.compile(r"[0-9a-f]{64}")
_MARKDOWN_CURRENCY_RE = re.compile(
    r"(?<!\\)((?:\\\\)*)\$"
    r"(?=[^\S\r\n]*[+-]?[^\S\r\n]*"
    r"(?:\d|[.,]\d|\([^\S\r\n]*\d))")
_MARKDOWN_LITERAL_DOUBLE_DOLLAR_RE = re.compile(
    r"(?<!\\)((?:\\\\)*)\$\$(?=[,.;:!?)](?:['\"’”])?(?:[ \t]|$))",
    re.MULTILINE,
)
_MARKDOWN_LITERAL_SINGLE_DOLLAR_RE = re.compile(
    r"(?<!\\)((?:\\\\)*)\$(?=(?:[ \t]+[A-Za-z]"
    r"|[ \t]*[,.;:!?)](?:[ \t]|$)|[ \t]*$))",
    re.MULTILINE,
)
_MARKDOWN_CURRENCY_PROTECTED_RE = re.compile(
    r"\$\$.*?\$\$"
    r"|(?<!`)(?P<ticks>`+)(?!`).*?(?<!`)(?P=ticks)(?!`)"
    r"|<[^>\r\n]*>"
    r"|(?<=\]\()[^)\r\n]*(?=\))"
    r"|(?:https?|ftp)://[^\s<>()]+"
    r"|mailto:[^\s<>()]+",
    re.IGNORECASE | re.DOTALL,
)
_MARKDOWN_PANDOC_CITATION_RE = re.compile(
    r"(?<![\\\w@])((?:\\\\)*)@(?=[A-Za-z0-9_])")
_MARKDOWN_PANDOC_LITERAL_PROTECTED_RE = re.compile(
    r"\$\$.*?\$\$"
    r"|(?<!\\)\$(?!\$)[^\r\n$]*?(?<!\\)\$(?!\$)"
    r"|(?<!`)(?P<ticks>`+)(?!`).*?(?<!`)(?P=ticks)(?!`)"
    r"|<[^>\r\n]*>"
    r"|(?<=\]\()[^)\r\n]*(?=\))"
    r"|(?:https?|ftp)://[^\s<>()]+"
    r"|mailto:[^\s<>()]+",
    re.IGNORECASE | re.DOTALL,
)
_MARKDOWN_CONSECUTIVE_BLANK_LINES_RE = re.compile(
    r"\n(?:[ \t]*\n){2,}")
_MARKDOWN_UNESCAPED_UNDERSCORE_RE = re.compile(
    r"(?<!\\)((?:\\\\)*)_")
_MARKDOWN_SPACED_THEMATIC_BREAK_RE = re.compile(
    r"^(?P<indent>[ \t]{0,3})-(?:[ \t]*-){2,}[ \t]*$")
_MARKDOWN_BARE_ALNUM_BRACKET_RE = re.compile(
    r"(?<!!)(?<!\\)(?<!\[)(?P<slashes>(?:\\\\)*)"
    r"\[(?P<label>[A-Za-z0-9])\]"
    r"(?!\]|\[(?:[^\]\r\n]{2,})?\]|\(|\{|:)")
_MARKDOWN_SINGLE_TOKEN_DEFINITION_RE = re.compile(
    r"(?mi)^[ \t]{0,3}\[([A-Za-z0-9])\]:")
_MARKDOWN_FENCE_LINE_RE = re.compile(
    r"^[ ]{0,3}(?P<fence>`{3,}|~{3,})")
_MARKDOWN_LARGE_ORDERED_LIST_MARKER_RE = re.compile(
    r"^(?P<indent>[ \t]{0,3})(?P<number>\d{3,4})\)(?=[ \t])")
_MARKDOWN_SOURCE_HASHTAG_RE = re.compile(
    r"^(?P<indent>[ \t]{0,3})#(?=[A-Za-z0-9_])")
_MARKDOWN_SOURCE_SPACED_ASTERISKS_RE = re.compile(
    r"(?<!\\)\*(?:[ \t]+(?<!\\)\*){2,}")
_MARKDOWN_SOURCE_ASTERISK_RUN_RE = re.compile(
    r"(?<!\\)(?P<slashes>(?:\\\\)*)(?P<markers>\*{3,})")
_MARKDOWN_SOURCE_IN_WORD_ASTERISKS_RE = re.compile(
    r"(?P<left>[A-Za-z])(?P<slashes>(?:\\\\)*)"
    r"(?P<markers>\*+)(?=[A-Za-z])")
_MARKDOWN_SOURCE_NESTED_ORDERED_MARKER_RE = re.compile(
    r"^(?P<prefix>[ ]{0,3}[-+]?[ \t]*\d{1,2})\)(?=[ \t])")
_MARKDOWN_SOURCE_OMISSION_LINE_RE = re.compile(
    r"^\s*\*(?:\s+\*){2,}(?:\s|$)")
_MARKDOWN_SOURCE_BRACKETED_SPEAKER_RE = re.compile(
    r"^(?P<indent>[ \t]{0,3})(?<!\\)\["
    r"(?!\^)(?P<label>[^\]\r\n]+)\]:(?=[ \t]|$)")
_MARKDOWN_SOURCE_BARE_BRACKET_RE = re.compile(
    r"(?<!!)(?<!\\)(?<!\[)(?P<slashes>(?:\\\\)*)"
    r"\[(?!\^)(?P<label>[^\[\]\r\n]+)\]"
    r"(?!\]|\[(?:[^\]\r\n]*)?\]|\(|\{|:)")


def _escape_markdown_currency(text: str) -> str:
    """Escape monetary dollar signs without creating inline math.

    The source corpus is PDF-derived rather than Markdown-authored. Currency
    pairs such as ``$100 ... $50`` can nevertheless be consumed as one math
    span by Markdown renderers with a dollar-math extension. Protect syntax
    whose contents must remain byte-for-byte stable, then escape numeric
    currency sigils with backslash-parity awareness so repeated calls are
    idempotent.
    """
    if "$" not in text:
        return text

    def escape_segment(segment: str) -> str:
        return _MARKDOWN_CURRENCY_RE.sub(
            lambda match: match.group(1) + r"\$", segment)

    parts: list[str] = []
    cursor = 0
    for protected in _MARKDOWN_CURRENCY_PROTECTED_RE.finditer(text):
        parts.append(escape_segment(text[cursor:protected.start()]))
        parts.append(protected.group(0))
        cursor = protected.end()
    parts.append(escape_segment(text[cursor:]))
    text = "".join(parts)

    # Legal source text can also use the dollar glyph itself as a named symbol
    # (``$ motivates`` or ``& $$,``). After numeric currency is escaped,
    # preserve complete authored math/code spans and escape only unambiguous
    # remaining literal forms.
    def escape_literal_segment(segment: str) -> str:
        segment = _MARKDOWN_LITERAL_DOUBLE_DOLLAR_RE.sub(
            lambda match: match.group(1) + r"\$\$", segment)
        return _MARKDOWN_LITERAL_SINGLE_DOLLAR_RE.sub(
            lambda match: match.group(1) + r"\$", segment)

    literal_parts: list[str] = []
    cursor = 0
    for protected in _MARKDOWN_PANDOC_LITERAL_PROTECTED_RE.finditer(text):
        literal_parts.append(escape_literal_segment(
            text[cursor:protected.start()]))
        literal_parts.append(protected.group(0))
        cursor = protected.end()
    literal_parts.append(escape_literal_segment(text[cursor:]))
    return "".join(literal_parts)


def _escape_markdown_source_line_literals(text: str) -> str:
    """Keep PDF line syntax from becoming Markdown structure.

    Preserve a complete fenced block emitted by the converter, but make an
    unmatched PDF-derived fence visible as literal text. Otherwise one stray
    ````` or ``~~~`` line can consume every later block in the export.
    """
    if not any(character in text for character in "#*[`~)"):
        return text

    raw_lines = text.splitlines(keepends=True)
    protected_fence_lines: set[int] = set()
    opening_fence: tuple[int, str, int] | None = None
    for index, raw_line in enumerate(raw_lines):
        content = raw_line.rstrip("\r\n")
        fence = _MARKDOWN_FENCE_LINE_RE.match(content)
        if opening_fence is None:
            if fence is not None:
                marker = fence.group("fence")
                opening_fence = (index, marker[0], len(marker))
            continue
        if fence is None:
            continue
        marker = fence.group("fence")
        opening_index, fence_character, fence_length = opening_fence
        if (marker[0] == fence_character
                and len(marker) >= fence_length
                and not content[fence.end():].strip()):
            protected_fence_lines.update(range(opening_index, index + 1))
            opening_fence = None

    output: list[str] = []
    for index, raw_line in enumerate(raw_lines):
        content = raw_line.rstrip("\r\n")
        ending = raw_line[len(content):]
        if index in protected_fence_lines:
            output.append(raw_line)
            continue

        fence = _MARKDOWN_FENCE_LINE_RE.match(content)
        if fence is not None:
            marker = fence.group("fence")
            escaped_marker = "".join(
                "\\" + character for character in marker)
            content = (
                content[:fence.start("fence")]
                + escaped_marker
                + content[fence.end("fence"):])

        content = _MARKDOWN_SOURCE_NESTED_ORDERED_MARKER_RE.sub(
            lambda match: match.group("prefix") + r"\)",
            content,
            count=1,
        )
        content = _MARKDOWN_SOURCE_ASTERISK_RUN_RE.sub(
            lambda match: (
                match.group("slashes")
                + match.group("markers").replace("*", r"\*")),
            content,
        )
        content = _MARKDOWN_SOURCE_IN_WORD_ASTERISKS_RE.sub(
            lambda match: (
                match.group("left")
                + match.group("slashes")
                + match.group("markers").replace("*", r"\*")),
            content,
        )
        content = _MARKDOWN_SOURCE_SPACED_ASTERISKS_RE.sub(
            lambda match: match.group(0).replace("*", r"\*"), content)
        content = _MARKDOWN_SOURCE_HASHTAG_RE.sub(
            lambda match: match.group("indent") + r"\#", content)
        content = _MARKDOWN_SOURCE_BRACKETED_SPEAKER_RE.sub(
            lambda match: (
                match.group("indent") + r"\["
                + match.group("label") + "]:"),
            content,
            count=1,
        )
        content = _MARKDOWN_SOURCE_BARE_BRACKET_RE.sub(
            lambda match: (
                match.group("slashes") + r"\["
                + match.group("label") + "]"),
            content,
        )
        output.append(content + ending)
    return "".join(output)


def _escape_markdown_pandoc_literals(text: str) -> str:
    """Keep PDF-derived currency and social handles literal in Pandoc.

    Pandoc's citation extension treats a standalone ``@name`` as a citation
    key. PDF-derived exports have no authored citation-key intent, so escape
    such handles outside protected Markdown syntax. Email addresses are not
    matched, and backslash-parity handling makes repeated calls idempotent.
    """
    text = _escape_markdown_source_line_literals(
        _escape_markdown_currency(text))
    if "@" not in text:
        return text

    def escape_segment(segment: str) -> str:
        return _MARKDOWN_PANDOC_CITATION_RE.sub(
            lambda match: match.group(1) + r"\@", segment)

    parts: list[str] = []
    cursor = 0
    for protected in _MARKDOWN_PANDOC_LITERAL_PROTECTED_RE.finditer(text):
        parts.append(escape_segment(text[cursor:protected.start()]))
        parts.append(protected.group(0))
        cursor = protected.end()
    parts.append(escape_segment(text[cursor:]))
    return "".join(parts)


def _is_markdown_source_omission_record(record: dict) -> bool:
    """Identify a bottom-of-page omission misclassified as a footnote."""
    return bool(
        _is_footnote_record(record)
        and _MARKDOWN_SOURCE_OMISSION_LINE_RE.match(
            str(record.get("text") or ""))
    )


def _is_markdown_endnote_record(record: dict) -> bool:
    """Return whether one retrieval record is an actual export endnote."""
    return (
        _is_footnote_record(record)
        and not _is_markdown_source_omission_record(record)
    )


def _markdown_emphasis(text: str) -> str:
    """Serialize exporter-owned emphasis using the configured marker."""
    escaped = _escape_markdown_pandoc_literals(str(text))
    escaped = _MARKDOWN_UNESCAPED_UNDERSCORE_RE.sub(
        lambda match: match.group(1) + r"\_", escaped)
    trailing_backslashes = len(escaped) - len(escaped.rstrip("\\"))
    if trailing_backslashes % 2:
        escaped += "\\"
    return f"{_MARKDOWN_EMPHASIS_MARKER}{escaped}{_MARKDOWN_EMPHASIS_MARKER}"


def _normalize_markdown_thematic_breaks(markdown: str) -> str:
    """Canonicalize PDF-derived hyphen rules outside code and Setext."""
    lines = markdown.splitlines(keepends=True)
    normalized: list[str] = []
    fence_character: str | None = None
    fence_length = 0

    for index, raw_line in enumerate(lines):
        content = raw_line.rstrip("\r\n")
        ending = raw_line[len(content):]
        fence = _MARKDOWN_FENCE_LINE_RE.match(content)
        if fence_character is not None:
            normalized.append(raw_line)
            if fence is not None:
                marker = fence.group("fence")
                if (marker[0] == fence_character
                        and len(marker) >= fence_length
                        and not content[fence.end():].strip()):
                    fence_character = None
                    fence_length = 0
            continue
        if fence is not None:
            marker = fence.group("fence")
            fence_character = marker[0]
            fence_length = len(marker)
            normalized.append(raw_line)
            continue

        candidate = _MARKDOWN_SPACED_THEMATIC_BREAK_RE.fullmatch(content)
        previous_blank = index == 0 or not lines[index - 1].strip()
        next_blank = index + 1 == len(lines) or not lines[index + 1].strip()
        if candidate is not None and previous_blank:
            if next_blank:
                normalized.append(
                    candidate.group("indent") + "---" + ending)
            else:
                # A following blank disambiguates the canonical rule from
                # both YAML metadata and Pandoc multiline-table boundaries.
                normalized.append(
                    candidate.group("indent") + "---" + ending)
                normalized.append(ending or "\n")
        else:
            normalized.append(raw_line)
    return "".join(normalized)


def _escape_markdown_large_ordered_list_literals(markdown: str) -> str:
    """Keep wrapped years/page numbers from becoming huge ordered lists."""
    escaped: list[str] = []
    fence_character: str | None = None
    fence_length = 0
    for raw_line in markdown.splitlines(keepends=True):
        content = raw_line.rstrip("\r\n")
        ending = raw_line[len(content):]
        fence = _MARKDOWN_FENCE_LINE_RE.match(content)
        if fence_character is not None:
            escaped.append(raw_line)
            if fence is not None:
                marker = fence.group("fence")
                if (marker[0] == fence_character
                        and len(marker) >= fence_length
                        and not content[fence.end():].strip()):
                    fence_character = None
                    fence_length = 0
            continue
        if fence is not None:
            marker = fence.group("fence")
            fence_character = marker[0]
            fence_length = len(marker)
            escaped.append(raw_line)
            continue

        escaped.append(_MARKDOWN_LARGE_ORDERED_LIST_MARKER_RE.sub(
            lambda match: (
                match.group("indent") + match.group("number") + r"\)"),
            content,
            count=1,
        ) + ending)
    return "".join(escaped)


def _escape_markdown_implicit_reference_literals(markdown: str) -> str:
    """Escape bare PDF editorial tokens that Pandoc turns into links.

    Single-character insertions such as ``[a]`` frequently occur in quoted
    legal text. Pandoc's implicit-header-reference extension silently links
    them when an outline heading has the same label. Preserve deliberate
    Markdown constructs and protect code/math/HTML/URLs while escaping only
    otherwise bare alphanumeric tokens.
    """
    definition_labels = {
        match.group(1).casefold()
        for match in _MARKDOWN_SINGLE_TOKEN_DEFINITION_RE.finditer(markdown)
    }

    def escape_unprotected(segment: str) -> str:
        def replace(match: re.Match[str]) -> str:
            if match.group("label").casefold() in definition_labels:
                return match.group(0)
            return (
                match.group("slashes") + r"\["
                + match.group("label") + "]")

        return _MARKDOWN_BARE_ALNUM_BRACKET_RE.sub(replace, segment)

    output: list[str] = []
    fence_character: str | None = None
    fence_length = 0
    display_math = False
    for raw_line in markdown.splitlines(keepends=True):
        content = raw_line.rstrip("\r\n")
        fence = _MARKDOWN_FENCE_LINE_RE.match(content)
        if fence_character is not None:
            output.append(raw_line)
            if fence is not None:
                marker = fence.group("fence")
                if (marker[0] == fence_character
                        and len(marker) >= fence_length
                        and not content[fence.end():].strip()):
                    fence_character = None
                    fence_length = 0
            continue
        if fence is not None:
            marker = fence.group("fence")
            fence_character = marker[0]
            fence_length = len(marker)
            output.append(raw_line)
            continue
        if display_math:
            output.append(raw_line)
            if "$$" in content:
                display_math = False
            continue
        if content.lstrip().startswith("$$"):
            output.append(raw_line)
            if content.count("$$") == 1:
                display_math = True
            continue
        if content.startswith(("    ", "\t")):
            output.append(raw_line)
            continue

        parts: list[str] = []
        cursor = 0
        for protected in _MARKDOWN_PANDOC_LITERAL_PROTECTED_RE.finditer(
                raw_line):
            parts.append(escape_unprotected(raw_line[cursor:protected.start()]))
            parts.append(protected.group(0))
            cursor = protected.end()
        parts.append(escape_unprotected(raw_line[cursor:]))
        output.append("".join(parts))
    return "".join(output)


def _normalize_markdown_blank_lines(markdown: str) -> str:
    """Canonicalize line endings and retain at most one blank line."""
    normalized = markdown.replace("\r\n", "\n").replace("\r", "\n")
    normalized = _MARKDOWN_CONSECUTIVE_BLANK_LINES_RE.sub(
        "\n\n", normalized)
    normalized = re.sub(r"\A(?:[ \t]*\n)+", "", normalized)
    normalized = re.sub(r"(?:\n[ \t]*)+\Z", "", normalized)
    return normalized + ("\n" if normalized else "")


def _normalize_markdown_table_cell_padding(markdown: str) -> str:
    """Serialize one valid pipe table with consistent padded cells.

    Docling emits padded header/body cells but compact delimiter cells.  A
    ``consistent`` remark-lint policy then chooses one style for the entire
    document and reports the other rows.  Reuse the strict table parser so
    escaped pipes and the source schema remain authoritative, and fail closed
    for malformed or ambiguous input.  Separator contents are retained
    verbatim because colons encode alignment and dash counts can encode
    relative column widths in Pandoc.
    """
    table = _table_retrieval_core._parse_markdown_table(markdown)
    if table is None:
        return markdown

    def padded_row(row: str) -> str:
        cells = _table_retrieval_core._split_markdown_row(row)
        if cells is None:
            raise ValueError("parsed Markdown table contains an invalid row")
        return "| " + " | ".join(cells) + " |"

    preamble = (*table.preamble, "") if table.preamble else ()
    return "\n".join((
        *preamble,
        padded_row(table.header),
        padded_row(table.separator),
        *(padded_row(row) for row in table.rows),
    ))


def _markdown_source_bound_case_name(metadata: dict) -> str:
    """Return a case name only when source headings bind it to this chunk.

    ``primary_case`` is inferred from citations in a chunk's body, so it can
    name a case discussed inside a different opinion.  Treating that inference
    as a Markdown heading creates false case sections.  The section path and
    captured source headings are the authoritative structural evidence.
    """
    case_name = str(metadata.get("primary_case") or "").strip()
    case_identity = _native_lexeme_key(case_name)
    if not case_identity:
        return ""

    candidates: list[str] = []
    section_path = str(metadata.get("section_path") or "")
    if section_path:
        candidates.extend(re.split(r"\s*(?:→|->|>)\s*", section_path))

    headings = metadata.get("headings") or []
    if isinstance(headings, str):
        candidates.append(headings)
    elif isinstance(headings, (list, tuple)):
        candidates.extend(str(heading) for heading in headings
                          if isinstance(heading, str))

    if any(_native_lexeme_key(candidate) == case_identity
           for candidate in candidates):
        return case_name
    return ""


def _markdown_pdf_page_marker(metadata: dict) -> str:
    """Return one visible physical-page locator for a rendered source chunk."""
    start = metadata.get("pdf_page_start", metadata.get("page_start"))
    end = metadata.get("pdf_page_end", metadata.get("page_end"))
    if not isinstance(start, int) or isinstance(start, bool) or start <= 0:
        return ""
    if not isinstance(end, int) or isinstance(end, bool) or end < start:
        end = start
    if start == end:
        return f"[PDF page {start}]"
    return f"[PDF pages {start}\u2013{end}]"


def _format_chunk(
        rec: dict, *, figure_asset_prefix: str = "",
        include_content_type_tag: bool = True) -> list[str]:
    """Format a single chunk record as markdown lines."""
    meta = rec["metadata"]
    ct = meta["content_type"]
    if _is_markdown_source_omission_record(rec):
        ct = "author_narrative"
    source_text = str(rec["text"])
    if ct == "table":
        source_text = _normalize_markdown_table_cell_padding(source_text)
    text = _escape_markdown_pandoc_literals(source_text)
    lines: list[str] = []
    source_bound_case = (
        _markdown_source_bound_case_name(meta)
        if ct == "case_opinion" else "")

    # --- Content-type HTML comment tag ---
    _CONTENT_TYPE_TAGS = {
        "case_opinion": lambda m: (
            f"<!-- CASE: {source_bound_case} -->"
            if source_bound_case else "<!-- CASE OPINION -->"),
        "notes_and_questions": lambda m: "<!-- NOTES AND QUESTIONS -->",
        "statutory_excerpt": lambda m: "<!-- STATUTE -->",
        "footnote": lambda m: "<!-- FOOTNOTE -->",
        "table": lambda m: "<!-- TABLE -->",
        "chapter_introduction": lambda m: "<!-- CHAPTER INTRODUCTION -->",
    }
    tag_fn = _CONTENT_TYPE_TAGS.get(ct)
    if tag_fn and include_content_type_tag:
        lines.append(tag_fn(meta))

    ctx = meta.get("context", "")
    if ctx:
        lines.append(f"\n{_markdown_emphasis(str(ctx))}\n")

    if ct == "case_opinion":
        case_name = source_bound_case
        page_ref = str(meta.get("page_range") or "").strip()
        path_case_bound = bool(
            case_name
            and any(
                _native_lexeme_key(part) == _native_lexeme_key(case_name)
                for part in re.split(
                    r"\s*(?:\u2192|->|>)\s*",
                    str(meta.get("section_path") or ""),
                )
            )
        )
        if case_name and not path_case_bound:
            lines.append(
                "\n##### " + _escape_markdown_pandoc_literals(case_name))
        if page_ref:
            lines.append(f"{_markdown_emphasis(page_ref)}\n")
        lines.append(text)
        lines.append("")
    elif ct == "statutory_excerpt":
        lines.append(f"\n> **Statutory Text** ({meta.get('page_range', '')})")
        for sline in text.split("\n"):
            lines.append(f"> {sline}")
        lines.append("")
    elif ct == "table":
        lines.append(f"\n{text}\n")
    elif ct == "notes_and_questions":
        lines.append(f"\n**Notes and Questions** ({meta.get('page_range', '')})\n")
        lines.append(text)
        lines.append("")
    elif ct == "footnote":
        lines.append("\n<details><summary>Footnote</summary>\n")
        lines.append(text)
        lines.append("\n</details>\n")
    elif ct == "chapter_introduction":
        # The source-derived chapter/section heading already says that this is
        # an introduction.  Repeating a synthetic visible label for every
        # physical chunk makes a multi-chunk introduction look like many
        # separate introductions.  Keep the machine-readable comment tag and
        # render the source prose without another display label.
        lines.append(f"\n{text}\n")
    else:
        lines.append(f"\n{text}\n")

    figure_image_path = meta.get("figure_image_path")
    if figure_image_path is not None:
        if (not isinstance(figure_image_path, str)
                or not re.fullmatch(
                    r"assets/figure-p\d{4,}-[A-Za-z0-9_-]+\.png",
                    figure_image_path)
                or figure_asset_prefix not in {"", "../"}):
            raise ValueError("invalid Markdown figure asset path")
        page = meta.get("page_start")
        page_label = (
            f" from PDF page {page}"
            if isinstance(page, int) and not isinstance(page, bool) else "")
        lines.append(
            "\n![Source figure"
            f"{page_label}]({figure_asset_prefix}{figure_image_path})\n")

    return lines


def _filter_chunk_records(records: list[dict], *,
                          include_types: list[str] | None = None,
                          exclude_types: list[str] | None = None,
                          chapters: list[int] | None = None) -> list[dict]:
    """Apply export filters to one already-captured chunks generation."""
    log.info(f"Loaded {len(records)} chunks for export")

    if exclude_types is None:
        exclude_types = ["structural", "empty"]

    filtered = []
    for rec in records:
        if _table_retrieval_core.is_table_child(rec.get("metadata")):
            continue
        ct = rec["metadata"]["content_type"]
        if ct in exclude_types:
            continue
        if include_types and ct not in include_types:
            continue
        if chapters and rec["metadata"].get("chapter_num") not in chapters:
            continue
        filtered.append(rec)

    log.info(f"After filtering: {len(filtered)} chunks "
             f"(excluded {len(records) - len(filtered)})")
    return filtered


def _load_and_filter_chunks(chunks_path: Path, *,
                            include_types: list[str] | None = None,
                            exclude_types: list[str] | None = None,
                            chapters: list[int] | None = None) -> list[dict]:
    """Load chunks JSONL and apply filters."""
    _require_file(chunks_path, "Chunks JSONL")
    records, _, _ = _load_index_snapshot_strict(chunks_path)
    return _filter_chunk_records(
        records, include_types=include_types,
        exclude_types=exclude_types, chapters=chapters)


def _section_heading_level(part: str, depth: int) -> str:
    """Return a markdown heading prefix for a section_path part at *depth*.

    Depth mapping:
        0 (chapter)          -> # (handled separately)
        1 (letter A-Z)       -> ##
        2 (number 1-9)       -> ###
        3 (letter a-z)       -> ####
        4+ (anything else)   -> #####
    """
    if depth <= 0:
        return "#"
    if depth == 1:
        return "##"
    if depth == 2:
        return "###"
    if depth == 3:
        return "####"
    return "#####"


def _display_division_title(ordinal: int, title: str) -> str:
    """Render a normalized division without duplicating its designation."""
    cleaned = str(title or "").strip()
    if re.match(
            r"^(?:Chapter|Part|Unit)\s+"
            r"(?:\d{1,3}|[IVXLCDM]+|[A-Za-z-]+)\b",
            cleaned, re.I):
        return cleaned
    if cleaned:
        return f"Chapter {ordinal} - {cleaned}"
    return f"Chapter {ordinal}"


def _footnote_source_ref_numbers(record: dict) -> tuple[int, ...]:
    """Return ordered Docling text ordinals carried by one footnote chunk."""
    numbers: list[int] = []
    for item in (record.get("metadata") or {}).get("source_items") or []:
        if not isinstance(item, dict):
            continue
        match = re.fullmatch(r"#/texts/(\d+)", str(item.get("ref") or ""))
        if match is not None:
            numbers.append(int(match.group(1)))
    return tuple(numbers)


def _footnote_source_refs(record: dict) -> frozenset[str]:
    return frozenset(
        str(item.get("ref"))
        for item in (record.get("metadata") or {}).get("source_items") or []
        if isinstance(item, dict) and item.get("ref")
    )


def _footnote_has_opening_marker(record: dict) -> bool:
    matches = list(_MARKDOWN_ENDNOTE_OPENING_RE.finditer(
        str(record.get("text") or "")))
    return bool(matches and matches[0].start() == 0)


def _footnote_opening_match(record: dict) -> re.Match[str] | None:
    match = _MARKDOWN_ENDNOTE_OPENING_RE.search(
        str(record.get("text") or ""))
    return match if match is not None and match.start() == 0 else None


def _footnote_edge_source_span(
        record: dict, *, first: bool,
) -> tuple[int, float, float, float, float] | None:
    """Return one ordered source span as ``page, left, top, right, bottom``."""
    spans: list[tuple[int, float, float, float, float]] = []
    for item in (record.get("metadata") or {}).get("source_items") or []:
        if not isinstance(item, dict):
            continue
        for span in item.get("spans") or []:
            if not isinstance(span, dict):
                continue
            page = span.get("page")
            bbox = span.get("bbox")
            if (not isinstance(page, int) or isinstance(page, bool)
                    or not isinstance(bbox, list) or len(bbox) != 4
                    or not all(isinstance(value, (int, float))
                               and not isinstance(value, bool)
                               for value in bbox)):
                continue
            spans.append((page, *(float(value) for value in bbox)))
    if not spans:
        return None
    return spans[0] if first else spans[-1]


def _footnote_displaced_opening(
        previous: dict, current: dict,
) -> bool:
    """Detect a source marker displaced behind text on the same baseline."""
    if (_footnote_has_opening_marker(previous)
            or _footnote_opening_match(current) is None):
        return False
    previous_span = _footnote_edge_source_span(previous, first=False)
    current_span = _footnote_edge_source_span(current, first=True)
    if previous_span is None or current_span is None:
        return False
    return (
        previous_span[0] == current_span[0]
        and abs(previous_span[2] - current_span[2]) <= 1.0
    )


def _footnote_false_structural_opening(
        previous: dict, current: dict,
) -> bool:
    """Recognize indented statute/list continuations that resemble notes."""
    current_match = _footnote_opening_match(current)
    if current_match is None:
        return False
    previous_metadata = previous.get("metadata") or {}
    current_metadata = current.get("metadata") or {}
    if (previous_metadata.get("page_end") != current_metadata.get("page_start")
            or not previous_metadata.get("footnote_parent_stable_id")
            or previous_metadata.get("footnote_parent_stable_id")
            != current_metadata.get("footnote_parent_stable_id")):
        return False
    previous_refs = _footnote_source_ref_numbers(previous)
    current_refs = _footnote_source_ref_numbers(current)
    if (not previous_refs or not current_refs
            or min(current_refs) != max(previous_refs) + 1):
        return False

    current_text = str(current.get("text") or "")
    remainder = current_text[current_match.end():].lstrip()
    label = current_match.group(1)
    if label.isdecimal() and re.match(
            r"(?:U\.S\.C\.|years?\b)", remainder, re.IGNORECASE):
        return True

    current_marker = current_text[:current_match.end()].strip()
    current_span = _footnote_edge_source_span(current, first=True)
    indented = current_span is not None and current_span[1] >= 100.0
    if (indented and current_marker.endswith(".")
            and str(previous.get("text") or "").rstrip().endswith(":")):
        return True

    previous_match = _footnote_opening_match(previous)
    if (indented and label.isdecimal() and current_marker.endswith(".")
            and previous_match is not None
            and previous_match.group(1).isdecimal()
            and str(previous.get("text") or "")[
                :previous_match.end()].strip().endswith(".")
            and int(label) == int(previous_match.group(1)) + 1):
        return True
    return False


def _markdown_footnote_continuation(
        previous: dict, current: dict,
) -> tuple[bool, str]:
    """Return whether two physical chunks form one logical source note."""
    previous_metadata = previous.get("metadata") or {}
    current_metadata = current.get("metadata") or {}
    if (previous_metadata.get("chapter_num")
            != current_metadata.get("chapter_num")):
        return False, ""
    if (previous_metadata.get("source_file")
            != current_metadata.get("source_file")):
        return False, ""

    shared_refs = _footnote_source_refs(previous) & _footnote_source_refs(current)
    if shared_refs:
        return True, "shared_ref"
    if _footnote_displaced_opening(previous, current):
        return True, "displaced_opener"
    if _footnote_false_structural_opening(previous, current):
        return True, "list"
    if _footnote_has_opening_marker(current):
        return False, ""

    previous_page = previous_metadata.get("page_end")
    if not isinstance(previous_page, int) or isinstance(previous_page, bool):
        previous_page = previous_metadata.get("page_start")
    current_page = current_metadata.get("page_start")
    if (not isinstance(previous_page, int) or isinstance(previous_page, bool)
            or not isinstance(current_page, int)
            or isinstance(current_page, bool)):
        return False, ""

    previous_refs = _footnote_source_ref_numbers(previous)
    current_refs = _footnote_source_ref_numbers(current)
    same_parent = (
        bool(previous_metadata.get("footnote_parent_stable_id"))
        and previous_metadata.get("footnote_parent_stable_id")
        == current_metadata.get("footnote_parent_stable_id")
    )
    if (current_page == previous_page and same_parent
            and previous_refs and current_refs
            and min(current_refs) == max(previous_refs) + 1):
        return True, "block"
    if (current_page == previous_page and same_parent
            and previous_refs and current_refs
            and min(current_refs) <= max(previous_refs) + 2
            and str(previous.get("text") or "").rstrip().endswith(":")):
        return True, "block"

    if current_page != previous_page + 1:
        return False, ""
    if (not _footnote_source_refs(previous)
            or not _footnote_source_refs(current)):
        return False, ""
    previous_text = str(previous.get("text") or "").rstrip()
    current_text = str(current.get("text") or "").lstrip()
    previous_span = _footnote_edge_source_span(previous, first=False)
    current_span = _footnote_edge_source_span(current, first=True)
    if (previous_span is not None and current_span is not None
            and previous_span[0] + 1 == current_span[0]
            and previous_span[4] <= 90.0
            and current_span[1] <= 107.0):
        return True, "block"
    if (not previous_text or not current_text
            or re.search(r"[.!?][\"')\]]*$", previous_text)):
        return False, ""
    if (current_text[0].islower() or current_text[0].isdigit()
            or current_text[0] in ",;:)]}"):
        return True, "sentence"
    return False, ""


def _merge_markdown_footnote_group(
        group: list[tuple[dict, str]],
) -> dict:
    """Create one export-only logical note without changing retrieval chunks."""
    first = group[0][0]
    merged_metadata = dict(first.get("metadata") or {})
    merged_text = str(first.get("text") or "")
    source_items: list[dict] = []
    seen_source_items: set[str] = set()

    def append_source_items(record: dict) -> None:
        for item in (record.get("metadata") or {}).get("source_items") or []:
            if not isinstance(item, dict):
                continue
            identity = json.dumps(item, sort_keys=True, ensure_ascii=False)
            if identity not in seen_source_items:
                seen_source_items.add(identity)
                source_items.append(item)

    append_source_items(first)
    page_ends = [
        value for value in (
            merged_metadata.get("page_start"),
            merged_metadata.get("page_end"),
        ) if isinstance(value, int) and not isinstance(value, bool)
    ]
    for record, reason in group[1:]:
        current_text = str(record.get("text") or "")
        if current_text:
            if reason == "displaced_opener":
                opening = _footnote_opening_match(record)
                if opening is None:
                    raise ValueError("displaced footnote opener is missing")
                marker = current_text[:opening.end()].strip()
                remainder = current_text[opening.end():].strip()
                merged_text = marker + " " + merged_text.lstrip()
                if remainder:
                    merged_text = merged_text.rstrip() + " " + remainder
            elif current_text.lstrip().startswith(tuple(",;:)]}")):
                separator = ""
                merged_text = (
                    merged_text.rstrip() + separator + current_text.lstrip())
            elif reason == "sentence":
                separator = " "
                merged_text = (
                    merged_text.rstrip() + separator + current_text.lstrip())
            elif reason == "list":
                separator = "\n"
                merged_text = (
                    merged_text.rstrip() + separator + current_text.lstrip())
            else:
                separator = "\n\n"
                merged_text = (
                    merged_text.rstrip() + separator + current_text.lstrip())
        append_source_items(record)
        metadata = record.get("metadata") or {}
        for value in (metadata.get("page_start"), metadata.get("page_end")):
            if isinstance(value, int) and not isinstance(value, bool):
                page_ends.append(value)
    if source_items:
        merged_metadata["source_items"] = source_items
    if page_ends:
        merged_metadata["page_start"] = min(page_ends)
        merged_metadata["page_end"] = max(page_ends)
    return {**first, "text": merged_text, "metadata": merged_metadata}


def _markdown_footnote_group_tail(
        group: list[tuple[dict, str]],
) -> dict:
    """Expose the physical tail plus every source ref already in a note.

    Continuation geometry and parent identity belong to the last physical
    block, while ref adjacency must account for blocks that preceded a
    same-baseline marker.  A fully merged record loses that tail identity;
    using only the last record loses the earlier ref needed to bridge the
    displaced marker.  This comparison-only view preserves both.
    """
    last = group[-1][0]
    metadata = dict(last.get("metadata") or {})
    source_items: list[dict] = []
    seen_source_items: set[str] = set()
    for record, _ in group:
        for item in (record.get("metadata") or {}).get("source_items") or []:
            if not isinstance(item, dict):
                continue
            identity = json.dumps(item, sort_keys=True, ensure_ascii=False)
            if identity in seen_source_items:
                continue
            seen_source_items.add(identity)
            source_items.append(item)
    if source_items:
        metadata["source_items"] = source_items
    return {**last, "metadata": metadata}


def _logical_markdown_footnote_records(chunks: list[dict]) -> list[dict]:
    """Coalesce physical continuation chunks into logical Markdown notes."""
    physical = [
        (input_index, record) for input_index, record in enumerate(chunks)
        if _is_markdown_endnote_record(record)
    ]

    def source_order(pair: tuple[int, dict]) -> tuple:
        input_index, record = pair
        metadata = record.get("metadata") or {}
        spans = []
        for item in metadata.get("source_items") or []:
            if not isinstance(item, dict):
                continue
            for span in item.get("spans") or []:
                if not isinstance(span, dict):
                    continue
                page = span.get("page")
                bbox = span.get("bbox")
                if (not isinstance(page, int) or isinstance(page, bool)
                        or not isinstance(bbox, list) or len(bbox) != 4
                        or not all(isinstance(value, (int, float))
                                   and not isinstance(value, bool)
                                   for value in bbox)):
                    continue
                left, top, right, bottom = (
                    float(value) for value in bbox)
                origin = str(span.get("origin") or "").upper()
                vertical = (
                    -max(top, bottom) if origin == "BOTTOMLEFT"
                    else min(top, bottom))
                spans.append((page, vertical, min(left, right)))
        if spans:
            return (*min(spans), input_index)
        page = metadata.get("page_start")
        if not isinstance(page, int) or isinstance(page, bool):
            page = sys.maxsize
        chunk_index = metadata.get("chunk_index")
        if not isinstance(chunk_index, int) or isinstance(chunk_index, bool):
            chunk_index = input_index
        return (page, math.inf, math.inf, chunk_index, input_index)

    physical.sort(key=source_order)
    groups: list[list[tuple[dict, str]]] = []
    for _, record in physical:
        if not groups:
            groups.append([(record, "first")])
            continue
        previous = (
            _markdown_footnote_group_tail(groups[-1])
            if len(groups[-1]) > 1 else groups[-1][-1][0])
        merge, reason = _markdown_footnote_continuation(
            previous, record)
        if merge:
            groups[-1].append((record, reason))
        else:
            groups.append([(record, "first")])
    return [_merge_markdown_footnote_group(group) for group in groups]


def _markdown_endnote_records(chunks: list[dict]) -> list[dict]:
    """Describe deterministic Pandoc footnotes for one export.

    A source footnote chunk is intentionally kept intact. Some source records
    contain an internal numbered list or more than one merged footnote, so
    splitting on apparent numbers would silently corrupt the source text.
    """
    logical_footnotes = _logical_markdown_footnote_records(chunks)
    stable_id_counts = Counter(
        str((record.get("metadata") or {}).get("stable_id") or "")
        for record in logical_footnotes)
    scope_serials: dict[int | None, int] = {}
    endnotes: list[dict] = []

    for record in logical_footnotes:
        metadata = record.get("metadata") or {}
        scope = metadata.get("chapter_num")
        serial = scope_serials.get(scope, 0) + 1
        scope_serials[scope] = serial

        stable_id = str(metadata.get("stable_id") or "")
        stable_match = _MARKDOWN_ENDNOTE_STABLE_ID_RE.fullmatch(stable_id)
        internal_label = None
        if stable_match is not None and stable_id_counts[stable_id] == 1:
            internal_label = f"rag-fn-{stable_match.group(1)}"

        opening_matches = list(
            _MARKDOWN_ENDNOTE_OPENING_RE.finditer(
                str(record.get("text") or "")))
        opening_label = (
            opening_matches[0].group(1)
            if opening_matches and opening_matches[0].start() == 0 else None)
        linkable_label = (
            opening_label if len(opening_matches) == 1 else None)
        endnotes.append({
            "record": record,
            "scope": scope,
            "serial": serial,
            "internal_label": internal_label,
            "serialized_label": None,
            "opening_label": opening_label,
            "opening_end": (
                opening_matches[0].end() if opening_label is not None else 0),
            "linkable_label": linkable_label,
            "reference_record_key": None,
            "reference_kind": None,
        })
    return endnotes


def _markdown_exact_source_segments(record: dict) -> list[dict]:
    """Return hash-bound, single-page source segments rendered by *record*.

    The chunk lineage does not duplicate source text, so candidate strings are
    bound back to an exact source item only when an entire rendered segment has
    the source item's exact text hash and charspan. Any repaired, opaque,
    multi-span, or duplicate source occurrence fails closed.
    """
    metadata = record.get("metadata") or {}
    if (metadata.get("source_lineage_schema_version")
            != _quality_core.SOURCE_LINEAGE_SCHEMA_VERSION):
        return []
    page_start = metadata.get("page_start")
    page_end = metadata.get("page_end")
    chapter = metadata.get("chapter_num")
    if (not isinstance(page_start, int) or isinstance(page_start, bool)
            or page_start < 1 or page_end != page_start
            or not isinstance(chapter, int) or isinstance(chapter, bool)):
        return []

    text = str(record.get("text") or "")
    rendered_segments = {(0, len(text), text)} if text else set()
    rendered_segments.update(
        (match.start(), match.end(), match.group(0))
        for match in re.finditer(r"[^\r\n]+", text)
    )
    rendered_segments.update(
        (match.start(), match.end(), match.group(0))
        for match in re.finditer(r"[^\r\n]+(?:\r?\n(?!\r?\n)[^\r\n]+)*", text)
    )

    source_items = [
        item for item in metadata.get("source_items") or []
        if isinstance(item, dict)
    ]
    results: list[dict] = []
    seen: set[tuple[int, int, str]] = set()
    for item in source_items:
        source_ref = str(item.get("ref") or "")
        label = str(item.get("label") or "").casefold().rsplit(".", 1)[-1]
        source_hash = item.get("source_text_sha256")
        oracle_hash = item.get("oracle_text_sha256")
        spans = item.get("spans")
        if (not source_ref or item.get("transform") not in {"plain", "list"}
                or not isinstance(source_hash, str)
                or _MARKDOWN_SHA256_RE.fullmatch(source_hash) is None
                or oracle_hash != source_hash
                or not isinstance(spans, list) or len(spans) != 1):
            continue
        span = spans[0]
        charspan = span.get("charspan") if isinstance(span, dict) else None
        if (not isinstance(span, dict) or span.get("page") != page_start
                or not isinstance(charspan, list) or len(charspan) != 2
                or charspan[0] != 0
                or not isinstance(charspan[1], int)
                or isinstance(charspan[1], bool)):
            continue
        for output_start, output_end, segment in rendered_segments:
            if (len(segment) != charspan[1]
                    or _source_fidelity_core.text_sha256(segment)
                    != source_hash):
                continue
            identity = (output_start, output_end, source_ref)
            if identity in seen:
                continue
            seen.add(identity)
            results.append({
                "record": record,
                "text": segment,
                "output_start": output_start,
                "source_ref": source_ref,
                "source_offset": 0,
                "source_label": label,
                "parent_refs": tuple(
                    str(ref) for ref in item.get("parent_refs") or []
                    if isinstance(ref, str) and ref),
                "page": page_start,
                "chapter": chapter,
                "record_source_items": source_items,
            })
    return results


def _markdown_source_callout_candidates(record: dict) -> list[dict]:
    """Return the closed set of exact body/table callout candidates."""
    candidates: list[dict] = []
    for segment in _markdown_exact_source_segments(record):
        text = segment["text"]
        marker_matches: list[tuple[re.Match[str], str, str]] = []
        marker_matches.extend(
            (match, match.group(0).translate(_MARKDOWN_SUPERSCRIPT_DIGITS),
             "unicode_superscript_digits")
            for match in _MARKDOWN_SUPERSCRIPT_DIGIT_RE.finditer(text)
        )
        if text.endswith("*") and text.count("*") == 1:
            marker_matches.append((
                re.search(r"\*$", text), "*", "terminal_star"))

        caption_match = _MARKDOWN_CAPTION_TERMINAL_DECIMAL_RE.search(text)
        if caption_match is not None and segment["source_label"] == "caption":
            table_refs = {
                str(item.get("ref"))
                for item in segment["record_source_items"]
                if (isinstance(item, dict)
                    and str(item.get("label") or "").casefold().rsplit(
                        ".", 1)[-1] == "table")
            }
            if table_refs.intersection(segment["parent_refs"]):
                marker_matches.append((
                    caption_match, caption_match.group(1),
                    "caption_terminal_decimal"))

        for match, label, proof in marker_matches:
            if match is None:
                continue
            candidates.append({
                **segment,
                "label": label,
                "proof": proof,
                "target": "body",
                "start": segment["output_start"] + match.start(),
                "end": segment["output_start"] + match.end(),
                "source_offset": match.start(),
            })
    return candidates


def _markdown_rendered_section_parts(metadata: dict) -> list[str]:
    """Mirror the source-section parts that the Markdown exporter can emit."""
    section_path = str(metadata.get("section_path") or "")
    if not section_path:
        return []
    parts = re.split(r"\s+(?:\u2192|->|>)\s+", section_path)
    chapter = metadata.get("chapter_num")
    chapter_title = metadata.get("chapter_title", "")
    if (parts and chapter is not None and (
            parts[0].strip() == str(chapter_title).strip()
            or re.match(r"^(?:Chapter|Part|Unit)\s+", parts[0], re.I))):
        parts = parts[1:]
    return [part.strip() for part in parts if part.strip()]


def _markdown_heading_callout_candidates(record: dict) -> list[dict]:
    """Return callouts carried by exact, occurrence-bound source headings."""
    metadata = record.get("metadata") or {}
    page = metadata.get("page_start")
    chapter = metadata.get("chapter_num")
    if (metadata.get(_heading_lineage.HEADING_SCHEMA_FIELD)
            != _heading_lineage.HEADING_LINEAGE_SCHEMA_VERSION
            or not isinstance(page, int) or isinstance(page, bool) or page < 1
            or metadata.get("page_end") != page
            or not isinstance(chapter, int) or isinstance(chapter, bool)):
        return []
    direct = metadata.get(_heading_lineage.DIRECT_HEADING_FIELD)
    components = metadata.get(_heading_lineage.HEADING_COMPONENTS_FIELD)
    if (not isinstance(direct, list) or not isinstance(components, list)
            or any(not isinstance(ref, str) or not ref for ref in direct)):
        return []
    rendered_parts = _markdown_rendered_section_parts(metadata)
    candidates: list[dict] = []
    for component in components:
        if not isinstance(component, dict):
            continue
        display = component.get("display")
        occurrence_ids = component.get("occurrence_ids")
        if (not isinstance(display, str) or rendered_parts.count(display) != 1
                or component.get("binding") not in {
                    "source_heading", "local_source_heading"}
                or not isinstance(occurrence_ids, list)
                or len(occurrence_ids) != 1
                or occurrence_ids[0] not in direct):
            continue
        marker_matches: list[tuple[re.Match[str], str, str]] = [
            (match, match.group(0).translate(_MARKDOWN_SUPERSCRIPT_DIGITS),
             "unicode_superscript_digits")
            for match in _MARKDOWN_SUPERSCRIPT_DIGIT_RE.finditer(display)
        ]
        if display.endswith("*") and display.count("*") == 1:
            terminal_star = re.search(r"\*$", display)
            if terminal_star is not None:
                marker_matches.append(
                    (terminal_star, "*", "terminal_star"))
        for match, label, proof in marker_matches:
            candidates.append({
                "record": record,
                "heading_display": display,
                "source_ref": occurrence_ids[0],
                "source_offset": match.start(),
                "page": page,
                "chapter": chapter,
                "label": label,
                "proof": proof,
                "target": "heading",
                "start": match.start(),
                "end": match.end(),
            })
    return candidates


def _markdown_endnote_reference_replacements(
        chunks: list[dict], endnotes: list[dict],
) -> tuple[
        dict[int, list[tuple[int, int, str, dict]]],
        dict[int, dict[str, list[tuple[int, int, str, dict]]]],
]:
    """Resolve only unique, source-bound callouts from a closed proof set.

    Supported evidence is deliberately narrow: Unicode superscript digits, a
    unique terminal non-omission ``*``, and an attached terminal decimal in a
    hash-bound table caption. A page/chapter/label scope must contain exactly
    one candidate and one note. Everything else retains the related-context
    fallback instead of guessing.
    """
    candidates: list[dict] = []
    for record in chunks:
        if _is_markdown_endnote_record(record):
            continue
        candidates.extend(_markdown_source_callout_candidates(record))
        candidates.extend(_markdown_heading_callout_candidates(record))

    candidates_by_scope: defaultdict[tuple[str, int, int], list[dict]] = (
        defaultdict(list))
    for candidate in candidates:
        candidates_by_scope[(
            candidate["label"], candidate["page"], candidate["chapter"],
        )].append(candidate)

    notes_by_scope: defaultdict[tuple[str, int, int], list[dict]] = defaultdict(
        list)
    for endnote in endnotes:
        label = endnote["linkable_label"]
        internal_label = endnote["internal_label"]
        metadata = endnote["record"].get("metadata") or {}
        page = metadata.get("page_start")
        chapter = endnote["scope"]
        if (label is None or internal_label is None
                or not (label.isdecimal() or label == "*")
                or not isinstance(page, int) or isinstance(page, bool)
                or metadata.get("page_end") != page
                or not isinstance(chapter, int) or isinstance(chapter, bool)):
            continue
        notes_by_scope[(label, page, chapter)].append(endnote)

    body_replacements: dict[int, list[tuple[int, int, str, dict]]] = {}
    heading_replacements: dict[
        int, dict[str, list[tuple[int, int, str, dict]]]] = {}
    for scope, scoped_endnotes in notes_by_scope.items():
        scoped_candidates = candidates_by_scope.get(scope, [])
        if len(scoped_endnotes) != 1 or len(scoped_candidates) != 1:
            continue
        endnote = scoped_endnotes[0]
        candidate = scoped_candidates[0]
        replacement = f"[^{endnote['internal_label']}]"
        replacement_span = (
            candidate["start"], candidate["end"], replacement, endnote)
        target = candidate["record"]
        if candidate["target"] == "body":
            body_replacements.setdefault(id(target), []).append(
                replacement_span)
        else:
            by_display = heading_replacements.setdefault(id(target), {})
            by_display.setdefault(candidate["heading_display"], []).append(
                replacement_span)
        endnote.update({
            "reference_record_key": id(target),
            "reference_kind": "exact",
            "reference_target": candidate["target"],
            "reference_proof": candidate["proof"],
            "reference_source_ref": candidate["source_ref"],
            "reference_source_offset": candidate["source_offset"],
            "reference_page": candidate["page"],
            "reference_chapter": candidate["chapter"],
        })

    return body_replacements, heading_replacements


def _markdown_with_endnote_references(
        record: dict,
        replacements: list[tuple[int, int, str, dict]],
) -> dict:
    """Return a shallow record copy with non-overlapping marker links."""
    text = str(record.get("text") or "")
    previous_start = len(text) + 1
    for start, end, replacement, _ in sorted(
            replacements, key=lambda item: item[0], reverse=True):
        if start < 0 or end < start or end > len(text) or end > previous_start:
            raise ValueError("overlapping or invalid endnote reference spans")
        text = text[:start] + replacement + text[end:]
        previous_start = start
    return {**record, "text": text}


def _append_markdown_endnotes(
        lines: list[str], referenced_endnotes: list[dict],
        unlinked_endnotes: list[dict],
) -> None:
    """Append one final Pandoc-footnote section and visible fallbacks."""
    if not referenced_endnotes and not unlinked_endnotes:
        return
    lines.append("\n\n---\n")

    if unlinked_endnotes:
        lines.append("\n## Unlinked source notes\n")
        for fallback_serial, endnote in enumerate(unlinked_endnotes, 1):
            source_text = _escape_markdown_pandoc_literals(
                str(endnote["record"].get("text") or "").strip())
            source_lines = source_text.splitlines() or [""]
            block_lines = [
                f"**Unlinked source note {fallback_serial}.** "
                f"{source_lines[0]}",
                *source_lines[1:],
            ]
            lines.append("\n" + "\n".join(block_lines) + "\n")

    if referenced_endnotes:
        lines.append("\n## Endnotes\n")

    for endnote in referenced_endnotes:
        serialized_label = endnote["serialized_label"]
        if serialized_label is None:
            raise ValueError("referenced endnote lacks a serialized label")

        source_text = str(endnote["record"].get("text") or "").strip()
        opening_label = endnote["opening_label"]
        if opening_label is not None:
            source_text = str(endnote["record"].get("text") or "")[
                endnote["opening_end"]:].strip()
        source_text = _escape_markdown_pandoc_literals(source_text)
        # Escape PDF editorial insertions before indenting continuation lines.
        # Once indented as native-footnote content, the document-wide pass
        # deliberately treats them like code and leaves them untouched.
        source_text = _escape_markdown_implicit_reference_literals(source_text)
        serial = endnote["serial"]
        annotations: list[str] = []
        if endnote["reference_kind"] == "related":
            annotations.append(
                "_Related page context; exact source marker unresolved._")
        if opening_label is not None and opening_label != str(serial):
            annotations.append(f"_(source footnote {opening_label})_")
        definition_text = " ".join([*annotations, source_text]).strip()
        definition_lines = definition_text.splitlines() or [""]
        block_lines = [
            f"[^{serialized_label}]: {definition_lines[0]}",
            *(f"    {line}" for line in definition_lines[1:]),
        ]
        lines.append("\n" + "\n".join(block_lines) + "\n")


def _validate_markdown_endnote_links(markdown: str) -> None:
    """Reject malformed native footnotes and legacy generated HTML links."""
    legacy_patterns = (
        r'<a\s+name=["\']rag-fn',
        r'\brag-fnref-[0-9a-f]{16}',
        r'\]\(#rag-fn-[0-9a-f]{16}\)',
        r'\[\^rag-fn-[0-9a-f]{16}\]',
        r'\bBack to (?:reference|related page context)\b',
    )
    if any(re.search(pattern, markdown, re.IGNORECASE)
           for pattern in legacy_patterns):
        raise ValueError("legacy serialized endnote HTML is not permitted")

    reference_ids = re.findall(
        r"\[\^([1-9][0-9]*)\](?!:)", markdown)
    definition_ids = re.findall(
        r"(?m)^\[\^([1-9][0-9]*)\]:", markdown)
    reference_counts = Counter(reference_ids)
    definition_counts = Counter(definition_ids)
    duplicate_references = sorted(
        label for label, count in reference_counts.items() if count != 1)
    if duplicate_references:
        raise ValueError(
            "duplicate serialized footnote references: "
            f"{duplicate_references[:3]}")
    duplicate_definitions = sorted(
        label for label, count in definition_counts.items() if count != 1)
    if duplicate_definitions:
        raise ValueError(
            "duplicate serialized footnote definitions: "
            f"{duplicate_definitions[:3]}")
    dangling = sorted(set(reference_ids) - set(definition_ids))
    if dangling:
        raise ValueError(
            f"dangling serialized footnote references: {dangling[:3]}")
    orphaned = sorted(set(definition_ids) - set(reference_ids))
    if orphaned:
        raise ValueError(
            f"orphaned serialized footnote definitions: {orphaned[:3]}")
    expected = [str(index) for index in range(1, len(reference_ids) + 1)]
    if reference_ids != expected or definition_ids != expected:
        raise ValueError(
            "serialized footnote labels are not in first-reference order")


def _assemble_markdown(
        chunks: list[dict], *, body_footer: str = "",
        figure_asset_prefix: str = "") -> str:
    """Assemble filtered chunks into a single structured markdown string."""
    lines: list[str] = []
    chapter_sentinel = object()
    current_chapter: object | int | None = chapter_sentinel
    # Track emitted headings per depth so we don't repeat them
    emitted_sections: dict[int, str] = {}
    emitted_intro_scopes: set[tuple[int | None, str]] = set()
    previous_page_marker = ""
    endnotes = _markdown_endnote_records(chunks)
    replacements, heading_replacements = (
        _markdown_endnote_reference_replacements(chunks, endnotes))
    body_by_stable_id: dict[str, list[dict]] = {}
    for record in chunks:
        if _is_markdown_endnote_record(record):
            continue
        stable_id = str(
            (record.get("metadata") or {}).get("stable_id") or "")
        if stable_id:
            body_by_stable_id.setdefault(stable_id, []).append(record)
    related_endnotes_by_parent: dict[str, list[dict]] = {}
    for endnote in endnotes:
        if endnote["reference_kind"] is not None:
            continue
        internal_label = endnote["internal_label"]
        metadata = endnote["record"].get("metadata") or {}
        parent_id = str(metadata.get("footnote_parent_stable_id") or "")
        parents = body_by_stable_id.get(parent_id, [])
        if internal_label is None or len(parents) != 1:
            continue
        parent_metadata = parents[0].get("metadata") or {}
        if parent_metadata.get("chapter_num") != endnote["scope"]:
            continue
        endnote["reference_record_key"] = id(parents[0])
        endnote["reference_kind"] = "related"
        related_endnotes_by_parent.setdefault(parent_id, []).append(endnote)
    referenced_endnotes: list[dict] = []
    referenced_internal_labels: set[str] = set()

    def register_referenced_endnotes(
            applied: list[tuple[int, int, str, dict]]) -> None:
        for _, _, _, endnote in sorted(applied, key=lambda item: item[0]):
            internal_label = endnote["internal_label"]
            if (internal_label is not None
                    and internal_label not in referenced_internal_labels):
                referenced_internal_labels.add(internal_label)
                referenced_endnotes.append(endnote)

    for rec in chunks:
        meta = rec["metadata"]
        newly_emitted_parts: list[str] = []

        ch = meta.get("chapter_num")
        ch_title = meta.get("chapter_title", "")
        if ch != current_chapter:
            current_chapter = ch
            previous_page_marker = ""
            if ch:
                display_title = _escape_markdown_pandoc_literals(
                    _display_division_title(ch, ch_title))
                separator = "\n\n---\n\n" if lines else ""
                lines.append(f"{separator}# {display_title}\n")
            emitted_sections.clear()

        if _is_markdown_endnote_record(rec):
            continue

        # The chapter H1 above is an export-document wrapper.  Physical page
        # markers must otherwise precede every source heading introduced by
        # this record so that a page-start heading is not attributed to the
        # preceding PDF page.
        page_marker = _markdown_pdf_page_marker(meta)
        if page_marker and page_marker != previous_page_marker:
            lines.append(f"\n{page_marker}\n")
            previous_page_marker = page_marker

        sp = meta.get("section_path", "")
        if sp and sp != emitted_sections.get(-1, ""):
            emitted_sections[-1] = sp  # raw path tracker
            parts = _markdown_rendered_section_parts(meta)
            # Emit each new level heading that hasn't been emitted yet
            for depth_idx, part in enumerate(parts):
                part_stripped = part.strip()
                if not part_stripped:
                    continue
                prev = emitted_sections.get(depth_idx)
                if prev == part_stripped:
                    continue
                # Clear deeper levels when a parent changes
                for k in list(emitted_sections.keys()):
                    if isinstance(k, int) and k > depth_idx and k >= 0:
                        del emitted_sections[k]
                emitted_sections[depth_idx] = part_stripped
                heading_depth = depth_idx + 1 if ch is not None else depth_idx
                prefix = _section_heading_level(
                    part_stripped, heading_depth)
                part_replacements = heading_replacements.get(
                    id(rec), {}).get(part_stripped, [])
                rendered_part = (
                    _markdown_with_endnote_references(
                        {"text": part_stripped}, part_replacements)["text"]
                    if part_replacements else part_stripped)
                display_part = _escape_markdown_pandoc_literals(rendered_part)
                lines.append(f"\n{prefix} {display_part}\n")
                newly_emitted_parts.append(part_stripped)
                register_referenced_endnotes(part_replacements)

        record_replacements = replacements.get(id(rec), [])
        rendered_record = (
            _markdown_with_endnote_references(rec, record_replacements)
            if record_replacements else rec)
        if (newly_emitted_parts
                and _is_casebook_case_heading(newly_emitted_parts[-1])):
            rendered_text = str(rendered_record.get("text") or "")
            rendered_lines = rendered_text.splitlines()
            first_index = next((
                index for index, value in enumerate(rendered_lines)
                if value.strip()
            ), None)
            if (first_index is not None
                    and _source_heading_identity(
                        rendered_lines[first_index])
                    == _source_heading_identity(newly_emitted_parts[-1])):
                rendered_record = {
                    **rendered_record,
                    "text": "\n".join(
                        rendered_lines[first_index + 1:]).lstrip("\n"),
                }
        intro_scope = (
            (ch, str(sp))
            if meta.get("content_type") == "chapter_introduction" else None)
        include_content_type_tag = not (
            intro_scope is not None and intro_scope in emitted_intro_scopes)
        lines.extend(_format_chunk(
            rendered_record,
            figure_asset_prefix=figure_asset_prefix,
            include_content_type_tag=include_content_type_tag,
        ))
        if intro_scope is not None:
            emitted_intro_scopes.add(intro_scope)
        register_referenced_endnotes(record_replacements)

        stable_id = str(meta.get("stable_id") or "")
        related_endnotes = related_endnotes_by_parent.get(stable_id, [])
        if related_endnotes:
            related_references = []
            for endnote in related_endnotes:
                internal_label = endnote["internal_label"]
                if internal_label is None:
                    continue
                related_references.append(f"[^{internal_label}]")
                if internal_label not in referenced_internal_labels:
                    referenced_internal_labels.add(internal_label)
                    referenced_endnotes.append(endnote)
            if len(related_references) == 1:
                lines.append(
                    "\nRelated page-context note"
                    f"{related_references[0]}\n")
            elif related_references:
                lines.append(
                    "\nRelated page-context notes: "
                    + " ".join(related_references) + "\n")

    serialized_labels: dict[str, str] = {}
    for serialized_number, endnote in enumerate(referenced_endnotes, 1):
        internal_label = endnote["internal_label"]
        if internal_label is None:
            raise ValueError("referenced endnote lacks an internal label")
        serialized_label = str(serialized_number)
        endnote["serialized_label"] = serialized_label
        serialized_labels[internal_label] = serialized_label

    def serialize_reference(match: re.Match[str]) -> str:
        internal_label = match.group(1)
        serialized_label = serialized_labels.get(internal_label)
        if serialized_label is None:
            raise ValueError(
                f"unregistered internal footnote label: {internal_label}")
        return f"[^{serialized_label}]"

    lines = [
        _MARKDOWN_INTERNAL_FOOTNOTE_REFERENCE_RE.sub(
            serialize_reference, line)
        for line in lines
    ]

    if body_footer:
        lines.append(body_footer)

    unlinked_endnotes = [
        endnote for endnote in endnotes
        if endnote["internal_label"] not in referenced_internal_labels
    ]
    _append_markdown_endnotes(
        lines, referenced_endnotes, unlinked_endnotes)
    output = _normalize_markdown_blank_lines("\n".join(lines))
    output = _normalize_markdown_thematic_breaks(output)
    output = _escape_markdown_large_ordered_list_literals(output)
    output = _escape_markdown_implicit_reference_literals(output)
    _validate_markdown_endnote_links(output)
    return output


def _export_plaintext(chunks: list[dict], export_path: Path) -> None:
    """Export chunks as a plain-text file + JSON metadata sidecar.

    Writes two files:
      <export_path>.txt             -- plain text, one chunk per block
      <export_path>.metadata.json   -- chunk metadata with char_start/char_end
                                       offsets for Anthropic citation API
    """
    txt_path = export_path.with_suffix(".txt")
    meta_path = export_path.parent / (export_path.stem + ".metadata.json")
    _storage_policy.ensure_private_directory(export_path.parent)

    text_parts: list[str] = []
    metadata_records: list[dict] = []
    char_cursor = 0

    for i, rec in enumerate(chunks):
        meta = rec["metadata"]
        text = rec["text"]

        ct = meta.get("content_type", "")
        page_start = meta.get("page_start")
        page_end = meta.get("page_end")
        primary_case = meta.get("primary_case", "")

        page_part = ""
        if page_start is not None and page_end is not None:
            page_part = f" | pp.{page_start}-{page_end}"
        elif page_start is not None:
            page_part = f" | p.{page_start}"

        case_part = f" | {primary_case}" if primary_case else ""
        delimiter = f"[CHUNK {i} | {ct}{page_part}{case_part}]"
        block = f"{delimiter}\n{text}"

        if i > 0:
            separator = "\n\n"
            char_cursor += len(separator)
            text_parts.append(separator)

        char_start = char_cursor
        char_end = char_cursor + len(block)
        char_cursor = char_end
        text_parts.append(block)

        metadata_records.append({
            "chunk_index": meta.get("chunk_index", i),
            "content_type": ct,
            "source_file": meta.get("source_file", ""),
            "page_start": page_start,
            "page_end": page_end,
            "section_path": meta.get("section_path", ""),
            "primary_case": primary_case,
            "content_source": meta.get("content_source", ""),
            "context": meta.get("context", ""),
            "chapter_num": meta.get("chapter_num"),
            "chapter_title": meta.get("chapter_title", ""),
            "case_names": meta.get("case_names", []),
            "char_start": char_start,
            "char_end": char_end,
        })

    full_text = "".join(text_parts)
    # The sidecar's char_start/char_end index this exact string, so the
    # published file must contain exactly these characters.
    _atomic_write_exact_utf8(txt_path, full_text)
    _atomic_write_text(
        meta_path,
        json.dumps(metadata_records, indent=2, ensure_ascii=False),
    )
    log.info(f"Exported {len(chunks)} chunks (plaintext) -> {txt_path} "
             f"({len(full_text) / 1e6:.1f} MB)")
    log.info(f"Metadata sidecar -> {meta_path}")


def _markdown_export_parameters(*, include_types: list[str] | None,
                                exclude_types: list[str] | None,
                                chapters: list[int] | None,
                                split_chapters: bool,
                                validation_policy: str = "auto") -> dict:
    validation_policy = _markdown_validation.normalize_validation_policy(
        validation_policy)
    effective_excludes = (
        ["structural", "empty"]
        if exclude_types is None else exclude_types)
    return {
        "format": "markdown",
        "endnote_serialization_version": (
            _MARKDOWN_ENDNOTE_SERIALIZATION_VERSION),
        "footnote_dialect": _MARKDOWN_FOOTNOTE_DIALECT,
        "currency_escape_version": _MARKDOWN_CURRENCY_ESCAPE_VERSION,
        "source_literal_escape_version": (
            _MARKDOWN_SOURCE_LITERAL_ESCAPE_VERSION),
        "table_cell_padding_version": (
            _MARKDOWN_TABLE_CELL_PADDING_VERSION),
        "emphasis_marker": _MARKDOWN_EMPHASIS_MARKER,
        "thematic_break_normalization_version": (
            _MARKDOWN_THEMATIC_BREAK_NORMALIZATION_VERSION),
        "implicit_reference_escape_version": (
            _MARKDOWN_IMPLICIT_REFERENCE_ESCAPE_VERSION),
        "ordered_list_literal_escape_version": (
            _MARKDOWN_ORDERED_LIST_LITERAL_ESCAPE_VERSION),
        "split_matter_partition_version": (
            _MARKDOWN_SPLIT_MATTER_PARTITION_VERSION),
        "heading_hierarchy_version": _MARKDOWN_HEADING_HIERARCHY_VERSION,
        "case_heading_version": _MARKDOWN_CASE_HEADING_VERSION,
        "figure_asset_version": _MARKDOWN_FIGURE_ASSET_VERSION,
        "content_type_rendering_version": (
            _MARKDOWN_CONTENT_TYPE_RENDERING_VERSION),
        "page_marker_version": _MARKDOWN_PAGE_MARKER_VERSION,
        "markdown_validation_policy_version": (
            _markdown_validation.MARKDOWN_VALIDATION_POLICY_VERSION),
        "markdown_validation": validation_policy,
        "include_types": sorted(set(include_types or [])),
        "exclude_types": sorted(set(effective_excludes)),
        "chapters": sorted(set(chapters or [])),
        "split_chapters": split_chapters,
    }


def _chunks_identity(path: Path) -> tuple[str, int] | None:
    try:
        records, source_sha256, _ = _load_index_snapshot_strict(path)
        return source_sha256, len(records)
    except (OSError, UnicodeError, ValueError, RuntimeError):
        return None


def _markdown_validation_manifest_complete(
        manifest_path: Path, *, parameters: dict,
        candidate_count: int) -> bool:
    """Return whether a completion manifest carries a valid gate receipt."""
    try:
        if (not manifest_path.is_file()
                or manifest_path.stat().st_size > 2 * 1024 * 1024):
            return False
        payload = json.loads(manifest_path.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            return False
        receipt = payload.get("markdown_validation")
        return _markdown_validation.validation_receipt_is_complete(
            receipt,
            policy=str(parameters.get("markdown_validation") or ""),
            candidate_count=candidate_count,
        )
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError):
        return False


def _unified_export_complete(chunks_path: Path, export_path: Path, *,
                             parameters: dict) -> bool:
    try:
        records, source_sha256, _ = _load_index_snapshot_strict(chunks_path)
        filtered = _filter_chunk_records(
            records,
            include_types=parameters.get("include_types") or None,
            exclude_types=parameters.get("exclude_types") or None,
            chapters=parameters.get("chapters") or None,
        )
        figure_outputs = _verified_markdown_figure_assets(
            filtered, export_path.parent)
    except (OSError, UnicodeError, ValueError, RuntimeError):
        return False
    source_count = len(records)
    manifest_path = _artifact_completion_path(
        export_path, stage="unified_export")
    return _fixed_artifacts_complete(
        manifest_path,
        stage="unified_export", source_sha256=source_sha256,
        source_record_count=source_count, parameters=parameters,
        outputs={"markdown": export_path, **figure_outputs}) and (
            _markdown_validation_manifest_complete(
                manifest_path, parameters=parameters, candidate_count=1))


def _record_source_page(record: dict) -> int | None:
    """Return one validated source-page start from chunk metadata."""
    metadata = record.get("metadata") or {}
    page = metadata.get("page_start")
    if isinstance(page, int) and not isinstance(page, bool) and page > 0:
        return page
    match = re.search(r"\d+", str(metadata.get("page_range") or ""))
    if match:
        parsed = int(match.group(0))
        return parsed if parsed > 0 else None
    return None


def _group_split_markdown_records(
        records: list[dict], *, anchor_records: list[dict] | None = None,
) -> dict[int | str, list[dict]]:
    """Group chapter chunks while keeping front and back matter distinct.

    Chapter assignment is authoritative. Unassigned chunks before the first
    assigned source page are front matter; chunks after the last assigned page
    are retained back matter. An unassigned chunk inside the chapter span is a
    structural defect and fails closed instead of being mislabeled.
    """
    anchor_records = records if anchor_records is None else anchor_records
    assigned_pages = [
        page for record in anchor_records
        if (record.get("metadata") or {}).get("chapter_num") is not None
        if (page := _record_source_page(record)) is not None
    ]
    first_assigned = min(assigned_pages) if assigned_pages else None
    last_assigned = max(assigned_pages) if assigned_pages else None
    unassigned_candidates = [
        record for record in records
        if (record.get("metadata") or {}).get("chapter_num") is None
    ]
    if unassigned_candidates and not assigned_pages:
        raise ValueError(
            "cannot partition unassigned Markdown chunks without full-corpus "
            "chapter page anchors")
    grouped: dict[int | str, list[dict]] = {}
    for record in records:
        metadata = record.get("metadata") or {}
        chapter_num = metadata.get("chapter_num")
        if chapter_num is not None:
            key: int | str = chapter_num
        else:
            page = _record_source_page(record)
            if page is None:
                raise ValueError(
                    "cannot partition an unassigned Markdown chunk without "
                    "source-page metadata")
            if (page is not None and last_assigned is not None
                    and page > last_assigned):
                key = "back_matter"
            elif (page is not None and first_assigned is not None
                  and page >= first_assigned):
                raise ValueError(
                    "unassigned chunk falls inside the assigned chapter "
                    f"span at source page {page}")
            else:
                key = "front_matter"
        grouped.setdefault(key, []).append(record)
    return grouped


def _split_markdown_group_sort_key(value: int | str) -> tuple[int, int]:
    """Order front matter, numbered chapters, then retained back matter."""
    if value == "front_matter":
        return 0, 0
    if isinstance(value, int) and not isinstance(value, bool):
        return 1, value
    if value == "back_matter":
        return 2, 0
    raise ValueError(f"unsupported split Markdown group: {value!r}")


def _owned_chapter_filename(name: str) -> bool:
    return bool(
        name in {"front_matter.md", "back_matter.md"}
        or re.fullmatch(r"ch\d+(?:_[\w-]+)?\.md", name))


def _split_export_complete(chunks_path: Path, chapters_dir: Path, *,
                           parameters: dict) -> bool:
    identity = _chunks_identity(chunks_path)
    if identity is None:
        return False
    manifest_path = _artifact_completion_path(
        chapters_dir, stage="split_export")
    try:
        payload = json.loads(manifest_path.read_text(encoding="utf-8"))
        records = payload.get("outputs") if isinstance(payload, dict) else None
        if not isinstance(records, list) or not records:
            return False
        names = []
        for record in records:
            if not isinstance(record, dict):
                return False
            name = record.get("name")
            if (not isinstance(name, str) or not _owned_chapter_filename(name)
                    or record.get("role") != name):
                return False
            names.append(name)
        if len(names) != len(set(names)):
            return False
        if not _markdown_validation_manifest_complete(
                manifest_path, parameters=parameters,
                candidate_count=len(names)):
            return False
        actual_names = {
            path.name for path in chapters_dir.glob("*.md")
            if _owned_chapter_filename(path.name)
        }
        if actual_names != set(names):
            return False
        source_sha256, source_count = identity
        return _fixed_artifacts_complete(
            manifest_path, stage="split_export",
            source_sha256=source_sha256,
            source_record_count=source_count, parameters=parameters,
            outputs={name: chapters_dir / name for name in names})
    except (OSError, UnicodeError, json.JSONDecodeError):
        return False


def _markdown_table_record_count(records: list[dict]) -> int:
    return sum(
        (record.get("metadata") or {}).get("content_type") == "table"
        for record in records)


def _log_markdown_validation_receipt(receipt: dict) -> None:
    log.info(
        "Markdown validation PASS (%d file(s); internal=%s, Pandoc=%s, "
        "Zettlr=%s)",
        receipt["candidate_count"],
        receipt["internal"]["status"],
        receipt["pandoc"]["status"],
        receipt["zettlr"]["status"],
    )


def _verified_markdown_figure_assets(
        records: list[dict], output_root: Path) -> dict[str, Path]:
    """Return hash-verified local image assets referenced by figure records."""
    expected: dict[str, str] = {}
    for record in records:
        metadata = record.get("metadata") or {}
        relative = metadata.get("figure_image_path")
        digest = metadata.get("figure_image_sha256")
        if relative is None and digest is None:
            continue
        if (not isinstance(relative, str)
                or not re.fullmatch(
                    r"assets/figure-p\d{4,}-[A-Za-z0-9_-]+\.png",
                    relative)
                or not isinstance(digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", digest) is None):
            raise ValueError("invalid figure asset metadata")
        previous = expected.setdefault(relative, digest)
        if previous != digest:
            raise ValueError("conflicting figure asset digests")
    outputs: dict[str, Path] = {}
    for index, (relative, digest) in enumerate(sorted(expected.items()), 1):
        path = Path(output_root) / Path(*relative.split("/"))
        if (not path.is_file() or path.stat().st_size <= 8
                or _cached_artifact_sha256(path) != digest):
            raise ValueError(f"missing or changed figure asset: {relative}")
        outputs[f"figure_asset_{index:04d}"] = path
    return outputs


def export_markdown(chunks_path: Path, export_path: Path, *,
                    include_types: list[str] | None = None,
                    exclude_types: list[str] | None = None,
                    chapters: list[int] | None = None,
                    split_chapters: bool = False,
                    chapters_dir: Optional[Path] = None,
                    format: str = "markdown",
                    validation_policy: str = "auto",
                    cloud_url: str = DEFAULT_CLOUD_URL,
                    cloud_model: str = DEFAULT_CLOUD_MODEL,
                    cloud_key: str = "",
                    ollama_url: str = DEFAULT_OLLAMA_URL,
                    ollama_model: str = DEFAULT_OLLAMA_MODEL,
                    gemini_key: str = "",
                    llm_workers: int = DEFAULT_LLM_WORKERS,
                    thinking: bool = False,
                    security_policy: (
                        _release_security.ReleaseSecurityPolicy | None
                    ) = None) -> None:
    """Produce clean export file(s) optimized for LLM consumption.

    With --format plaintext: writes a .txt + .metadata.json sidecar
    (char offsets for Anthropic citation API).

    With ``split_chapters=True`` (markdown only), writes ``chNN_title.md``
    files (plus ``front_matter.md`` and ``back_matter.md`` when needed) to
    ``chapters_dir`` or, by
    default, ``export_path.parent / "Chapters"``. The unified ``export_path``
    file is not written in this mode.

    Without: writes a single combined markdown file.
    """
    if split_chapters and format != "markdown":
        raise ValueError("split_chapters is supported only for markdown exports")
    validation_policy = _markdown_validation.normalize_validation_policy(
        validation_policy)

    records, source_sha256, _ = _load_index_snapshot_strict(chunks_path)
    source_record_count = len(records)
    filtered = _filter_chunk_records(
        records,
        include_types=include_types,
        exclude_types=exclude_types,
        chapters=chapters,
    )

    if not filtered:
        log.warning("No chunks to export after filtering.")
        return

    figure_asset_outputs = _verified_markdown_figure_assets(
        filtered, export_path.parent)

    if format == "plaintext":
        _export_plaintext(filtered, export_path)
        return

    if format == "flashcards":
        _export_flashcards(filtered, export_path,
                           cloud_url=cloud_url, cloud_model=cloud_model,
                           cloud_key=cloud_key, ollama_url=ollama_url,
                           ollama_model=ollama_model, gemini_key=gemini_key,
                           llm_workers=llm_workers, thinking=thinking,
                           security_policy=security_policy)
        return

    validation_session = _markdown_validation.MarkdownValidationSession(
        validation_policy)

    if split_chapters:
        # Keep retained front/back matter separate from numbered chapters.
        by_chapter = _group_split_markdown_records(
            filtered, anchor_records=records)

        # Use Chapters/ subdirectory under the export path's parent
        # e.g., output/Constitutional Law/Chapters/
        out_dir = chapters_dir if chapters_dir else (
            export_path.parent / "Chapters")
        # Build chapter index for cross-references
        chapter_index: dict[int, str] = {}  # ch_num -> filename
        for ch_num in sorted(
                by_chapter.keys(), key=_split_markdown_group_sort_key):
            ch_chunks = by_chapter[ch_num]
            ch_title = ""
            for rec in ch_chunks:
                t = rec["metadata"].get("chapter_title", "")
                if t:
                    ch_title = t
                    break
            if isinstance(ch_num, int) and not isinstance(ch_num, bool):
                safe_title = re.sub(r"[^\w\s-]", "", ch_title).strip()
                safe_title = re.sub(r"\s+", "_", safe_title)[:40]
                filename = f"ch{ch_num:02d}_{safe_title}.md" if safe_title else f"ch{ch_num:02d}.md"
                chapter_index[ch_num] = filename

        candidates: dict[str, tuple[str, int]] = {}
        validation_receipts: list[dict] = []
        for ch_num in sorted(
                by_chapter.keys(), key=_split_markdown_group_sort_key):
            ch_chunks = by_chapter[ch_num]
            ch_title = ""
            for rec in ch_chunks:
                t = rec["metadata"].get("chapter_title", "")
                if t:
                    ch_title = t
                    break

            if isinstance(ch_num, int) and not isinstance(ch_num, bool):
                filename = chapter_index[ch_num]
            else:
                filename = f"{ch_num}.md"

            # Add cross-reference footer linking to other chapters. It must
            # remain before native footnote definitions so ``## Endnotes`` is
            # the final ordinary block in Pandoc/Zettlr output.
            cross_reference_lines: list[str] = []
            if isinstance(ch_num, int) and not isinstance(ch_num, bool):
                # Collect cross-refs found in this chapter's chunks
                xref_chapters = set()
                for rec in ch_chunks:
                    for xref in rec["metadata"].get("cross_references", []):
                        # Normalize built-in profile displays (``Ch.12`` or
                        # ``Part.IV``) back to the integer division contract.
                        m = re.match(
                            r"(?:Ch|Chapter|Part|Unit)\."
                            r"([A-Za-z0-9-]+)", xref, re.I)
                        if m:
                            ref_ch = _document_profiles.parse_division_ordinal(
                                m.group(1), maximum=3999)
                            if ref_ch is None:
                                continue
                            if ref_ch != ch_num and ref_ch in chapter_index:
                                xref_chapters.add(ref_ch)

                if xref_chapters:
                    cross_reference_lines.extend([
                        "\n\n---\n\n**Cross-References:**\n",
                    ])
                    for ref_ch in sorted(xref_chapters):
                        ref_file = chapter_index[ref_ch]
                        ref_title = ""
                        if ref_ch in by_chapter:
                            for rec in by_chapter[ref_ch]:
                                t = rec["metadata"].get("chapter_title", "")
                                if t:
                                    ref_title = t
                                    break
                        label = _display_division_title(ref_ch, ref_title)
                        display_label = _escape_markdown_pandoc_literals(label)
                        cross_reference_lines.append(
                            f"- [{display_label}]({ref_file})")

            md = _assemble_markdown(
                ch_chunks, body_footer="\n".join(cross_reference_lines),
                figure_asset_prefix="../")

            validation_receipts.append(validation_session.validate(
                md,
                expected_table_count=_markdown_table_record_count(ch_chunks),
                source_name=filename,
            ))
            candidates[filename] = (md, len(ch_chunks))

        validation_receipt = (
            _markdown_validation.combine_validation_receipts(
                validation_receipts, policy=validation_policy))
        _log_markdown_validation_receipt(validation_receipt)

        _storage_policy.ensure_private_directory(out_dir)
        published_files: dict[str, Path] = {}
        total_words = 0
        for filename, (md, chunk_count) in candidates.items():
            filepath = out_dir / filename
            _atomic_write_text(filepath, md)
            published_files[filename] = filepath
            word_count = len(md.split())
            total_words += word_count
            log.info(
                f"  {filename} ({chunk_count} chunks, "
                f"{word_count:,} words)")

        for prior_path in out_dir.glob("*.md"):
            if (_owned_chapter_filename(prior_path.name)
                    and prior_path.name not in published_files):
                prior_path.unlink()
        parameters = _markdown_export_parameters(
            include_types=include_types, exclude_types=exclude_types,
            chapters=chapters, split_chapters=True,
            validation_policy=validation_policy)
        _write_artifact_completion(
            _artifact_completion_path(out_dir, stage="split_export"),
            stage="split_export", source_sha256=source_sha256,
            source_record_count=source_record_count, parameters=parameters,
            outputs=published_files,
            extra_fields={"markdown_validation": validation_receipt})
        log.info(f"Exported {len(candidates)} chapter files -> {out_dir}/ "
                 f"({total_words:,} words total)")
        log.info(
            "Upload only the manifested Markdown files in %s; do not mix "
            "unified, chunk, or vector artifacts into one project.", out_dir)
    else:
        # Single combined file
        output = _assemble_markdown(filtered)
        validation_receipt = (
            _markdown_validation.combine_validation_receipts(
                [validation_session.validate(
                    output,
                    expected_table_count=_markdown_table_record_count(filtered),
                    source_name=export_path.name,
                )],
                policy=validation_policy,
            ))
        _log_markdown_validation_receipt(validation_receipt)
        _atomic_write_text(export_path, output)
        parameters = _markdown_export_parameters(
            include_types=include_types, exclude_types=exclude_types,
            chapters=chapters, split_chapters=False,
            validation_policy=validation_policy)
        _write_artifact_completion(
            _artifact_completion_path(export_path, stage="unified_export"),
            stage="unified_export", source_sha256=source_sha256,
            source_record_count=source_record_count, parameters=parameters,
            outputs={"markdown": export_path, **figure_asset_outputs},
            extra_fields={"markdown_validation": validation_receipt})
        word_count = len(output.split())
        log.info(f"Exported {len(filtered)} chunks -> {export_path} "
                 f"({len(output) / 1e6:.1f} MB, {word_count:,} words)")


def _pipeline_paths_from_published_chunks(chunks_path: Path) -> PipelinePaths:
    """Derive one conventional run layout from its canonical chunks path."""
    chunks_path = Path(chunks_path)
    run_root = chunks_path.parent
    name = run_root.name
    expected_chunks = run_root / f"{name}_chunks.jsonl"
    try:
        supplied = chunks_path.resolve(strict=True)
        expected = expected_chunks.resolve(strict=True)
    except OSError as exc:
        raise FileNotFoundError(
            f"published chunks file is missing: {chunks_path}") from exc
    if supplied != expected:
        raise ValueError(
            "AI target exports require the conventional published run chunks "
            f"path: {expected_chunks}")
    return {
        "doc": run_root / f"{name}.json",
        "converted_markdown": run_root / f"{name}_docling.md",
        "chunks": expected_chunks,
        "quality_report": _quality_core.quality_report_path(expected_chunks),
        "publication_receipt": run_root / ".rag-publication.json",
        "export": run_root / f"{name}.md",
        "chapters_dir": run_root / "Chapters",
        "chroma": run_root / f"{name}_chroma",
        "qdrant": run_root / f"{name}_qdrant",
        "preprocessed": run_root.parent / f"{name}_preprocessed.pdf",
        "collection": name.lower().replace(" ", "_"),
    }


def _ai_project_receipt_path(output_dir: Path) -> Path:
    output_dir = Path(output_dir)
    return output_dir.with_name(
        f".{output_dir.name}.ai_project_export.complete.json")


@contextmanager
def _ai_project_source_lease(
        chunks_path: Path, *, timeout: float = DEFAULT_DB_LOCK_TIMEOUT):
    """Hold the run-wide writer lease for one READY derivative snapshot."""
    paths = _pipeline_paths_from_published_chunks(chunks_path)
    run_root = paths["doc"].parent
    output_root = run_root.parent
    _, observed = _retention.load_pipeline_run_manifest(
        output_root, run_root.name)
    if observed.get("state") != "complete":
        raise RuntimeError("AI target export requires a completed owned run")
    with _pipeline_job_lock(
            scope_name=observed["job_scope"], timeout=timeout,
            output_root=output_root):
        _, current = _retention.load_pipeline_run_manifest(
            output_root, run_root.name)
        if (current.get("state") != "complete"
                or current.get("ownership_token")
                != observed.get("ownership_token")
                or os.path.normcase(current.get("job_scope", ""))
                != os.path.normcase(observed.get("job_scope", ""))):
            raise RuntimeError(
                "pipeline ownership changed while acquiring the AI export "
                "source lease")
        yield paths


@contextmanager
def _ai_project_output_lease(
        output_dir: Path, *, timeout: float = DEFAULT_DB_LOCK_TIMEOUT):
    """Serialize every writer of a target directory and its sidecar receipt."""
    output_dir = Path(output_dir)
    with _VectorStoreLease(
            output_dir,
            backend="ai-project",
            collection_name=output_dir.name,
            operation="AI project derivative publication",
            timeout=timeout,
            resource_description=f"AI project target '{output_dir}'",
            timeout_option="AI project export lock timeout"):
        yield


def _load_ready_ai_project_source(
        chunks_path: Path,
) -> tuple[PipelinePaths, dict, dict, list[_ai_project_export.SourceDocument]]:
    """Load exact receipt-bound chapters from one currently READY run."""
    paths = _pipeline_paths_from_published_chunks(chunks_path)
    if not _pipeline_publication_complete(paths):
        raise RuntimeError(
            "AI target export requires a currently READY five-gate "
            "publication")
    receipt_raw = paths["publication_receipt"].read_bytes()
    receipt = _publication_core.parse_publication_receipt_bytes(receipt_raw)
    markdown_gate = _publication_receipt_gate(
        receipt, "markdown_validity")["evidence"]
    if markdown_gate.get("split_requested") is not True:
        raise RuntimeError(
            "AI target export requires receipt-bound chapter Markdown; "
            "rerun or resume the full pipeline with --split-chapters")

    split_manifest_path = _artifact_completion_path(
        paths["chapters_dir"], stage="split_export")
    split_raw = split_manifest_path.read_bytes()
    if len(split_raw) > 2 * 1024 * 1024:
        raise ValueError("canonical chapter manifest exceeds its byte limit")
    try:
        split_manifest = json.loads(split_raw.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("canonical chapter manifest cannot be parsed") from exc
    outputs = split_manifest.get("outputs") if isinstance(
        split_manifest, dict) else None
    if not isinstance(outputs, list) or not outputs:
        raise ValueError("canonical chapter manifest has no outputs")

    documents: list[_ai_project_export.SourceDocument] = []
    observed_names: set[str] = set()
    for record in outputs:
        if not isinstance(record, dict):
            raise ValueError("canonical chapter output record is invalid")
        name = record.get("name")
        if (not isinstance(name, str) or not _owned_chapter_filename(name)
                or record.get("role") != name or name in observed_names):
            raise ValueError("canonical chapter output inventory is invalid")
        observed_names.add(name)
        path = paths["chapters_dir"] / name
        raw = path.read_bytes()
        digest = hashlib.sha256(raw).hexdigest()
        if (record.get("size") != len(raw)
                or record.get("sha256") != digest):
            raise ValueError(
                f"canonical chapter changed after publication: {name}")
        try:
            text = raw.decode("utf-8")
        except UnicodeError as exc:
            raise ValueError(
                f"canonical chapter is not UTF-8: {name}") from exc
        documents.append(_ai_project_export.SourceDocument(name, text))
    return paths, receipt, split_manifest, documents


def _ai_project_record_matches(path: Path, record: dict) -> bool:
    """Return whether one regular file exactly matches a receipt record."""
    path = Path(path)
    try:
        return (
            not _storage_policy.path_is_link_like(path)
            and path.is_file()
            and path.stat().st_size == record.get("size")
            and _cached_artifact_sha256(path) == record.get("sha256")
        )
    except (OSError, ValueError):
        return False


def _existing_ai_project_owned_records(
        output_dir: Path, *, target: str,
        expected_records: dict[str, dict], paths: PipelinePaths,
        publication_receipt: dict, split_manifest: dict,
        sources: list[_ai_project_export.SourceDocument]) -> dict[str, dict]:
    """Verify prior bytes or an exact interrupted copy of current bytes.

    A sidecar is an ownership claim, not an authority by itself.  Rebuild its
    entire package from the current READY source before any claimed record can
    authorize replacing or deleting a target file.
    """
    output_dir = Path(output_dir)
    receipt_path = _ai_project_receipt_path(output_dir)
    prior_records: dict[str, dict] = {}
    if receipt_path.exists() or _storage_policy.path_is_link_like(receipt_path):
        if (_storage_policy.path_is_link_like(receipt_path)
                or not receipt_path.is_file()):
            raise ValueError("AI target ownership receipt is not a regular file")
        prior = _ai_project_export.parse_export_receipt_bytes(
            receipt_path.read_bytes())
        if prior["target"] != _ai_project_export.target_profile(target).name:
            raise ValueError("AI target directory belongs to another profile")
        if not _pipeline_publication_complete(
                paths, expected_receipt=publication_receipt):
            raise ValueError(
                "AI target ownership source is no longer a READY publication")
        split_records = {
            record.get("name"): record
            for record in split_manifest.get("outputs", [])
            if isinstance(record, dict)
        }
        for source in sources:
            record = split_records.get(source.name)
            source_path = paths["chapters_dir"] / source.name
            raw = source_path.read_bytes()
            if (not isinstance(record, dict)
                    or record.get("size") != len(raw)
                    or record.get("sha256")
                    != hashlib.sha256(raw).hexdigest()
                    or raw != source.text.encode("utf-8")):
                raise ValueError(
                    "AI target ownership chapter binding changed")
        prior_documents, prior_parameters = (
            _ai_project_export.build_project_documents(
                sources, target=target,
                max_files=prior["parameters"]["max_files"],
                validation_policy=(
                    prior["parameters"]["markdown_validation"])))
        reconstructed_records = _ai_project_output_records(prior_documents)
        publication_raw = paths["publication_receipt"].read_bytes()
        split_raw = _artifact_completion_path(
            paths["chapters_dir"], stage="split_export").read_bytes()
        try:
            current_publication = (
                _publication_core.parse_publication_receipt_bytes(
                    publication_raw))
            current_split = json.loads(split_raw.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise ValueError(
                "AI target ownership source binding cannot be parsed") from exc
        if (current_publication != publication_receipt
                or current_split != split_manifest):
            raise ValueError("AI target ownership source binding changed")
        reconstructed = _ai_project_export.build_export_receipt(
            target=target,
            publication_receipt_sha256=hashlib.sha256(
                publication_raw).hexdigest(),
            publication_evidence_root_sha256=(
                publication_receipt["evidence_root_sha256"]),
            canonical_split_manifest_sha256=hashlib.sha256(
                split_raw).hexdigest(),
            canonical_chunks_sha256=str(split_manifest["source_sha256"]),
            source_record_count=int(split_manifest["source_record_count"]),
            parameters=prior_parameters,
            documents=prior_documents,
            output_records=reconstructed_records,
        )
        if prior != reconstructed:
            raise ValueError(
                "AI target ownership receipt is stale or modified")
        prior_records = {
            record["name"]: record for record in reconstructed_records
        }

    if not output_dir.exists():
        return prior_records
    if (_storage_policy.path_is_link_like(output_dir)
            or not output_dir.is_dir()):
        raise ValueError("AI target output must be a real directory")
    for entry in output_dir.iterdir():
        if (_storage_policy.path_is_link_like(entry) or not entry.is_file()):
            raise ValueError("AI target directory contains a non-regular file")
        candidates = [
            record for record in (
                prior_records.get(entry.name), expected_records.get(entry.name))
            if record is not None
        ]
        if not any(_ai_project_record_matches(entry, record)
                   for record in candidates):
            raise ValueError(
                "AI target directory contains modified or unmanifested content")
    return prior_records


def _reject_nested_ai_project_target(
        output_dir: Path, *, run_root: Path, target: str) -> Path:
    """Return the one canonical, direct-child directory for this target."""
    profile = _ai_project_export.target_profile(target)
    run_root = Path(run_root).resolve(strict=True)
    expected = run_root / profile.directory_name
    candidate = Path(output_dir).resolve(strict=False)
    expected_identity = os.path.normcase(str(expected))
    if (os.path.normcase(str(candidate)) != expected_identity
            or candidate.parent != run_root):
        raise ValueError(
            "AI target output must be its canonical target directory directly "
            "under the source run")
    _storage_policy.assert_no_link_components(candidate)
    return candidate


def _ai_project_output_records(
        documents: list[_ai_project_export.ProjectDocument]) -> list[dict]:
    records = []
    for document in documents:
        raw = document.text.encode("utf-8")
        records.append({
            "role": document.name,
            "name": document.name,
            "size": len(raw),
            "sha256": hashlib.sha256(raw).hexdigest(),
        })
    return records


def _validate_ai_project_documents(
        documents: list[_ai_project_export.ProjectDocument],
        sources: list[_ai_project_export.SourceDocument], *,
        validation_policy: str) -> dict:
    """Validate transformed upload documents against canonical table counts."""
    policy = _markdown_validation.normalize_validation_policy(
        validation_policy)
    table_counts = {
        source.name: sum(
            line.strip() == "<!-- TABLE -->"
            for line in source.text.splitlines())
        for source in sources
    }
    if len(table_counts) != len(sources):
        raise ValueError("AI project canonical source names are not unique")
    session = _markdown_validation.MarkdownValidationSession(policy)
    receipts = []
    for document in documents:
        if any(source not in table_counts for source in document.sources):
            raise ValueError("AI project group references an unknown source")
        receipts.append(session.validate(
            document.text,
            expected_table_count=sum(
                table_counts[source] for source in document.sources),
            source_name=document.name,
            require_table_markers=False,
        ))
    combined = _markdown_validation.combine_validation_receipts(
        receipts, policy=policy)
    _log_markdown_validation_receipt(combined)
    return combined


def _remove_ai_project_staging(stage_dir: Path, *, output_dir: Path) -> None:
    """Remove only the unique sibling staging directory created by this call."""
    stage_dir = Path(stage_dir)
    output_dir = Path(output_dir)
    parent = output_dir.parent.resolve(strict=True)
    resolved = stage_dir.resolve(strict=False)
    prefix = f".{output_dir.name}.ai-project-stage-"
    if (resolved.parent != parent or not resolved.name.startswith(prefix)
            or _storage_policy.path_is_link_like(stage_dir)):
        raise RuntimeError("AI project staging path lost its owned identity")
    if stage_dir.exists():
        if not stage_dir.is_dir():
            raise RuntimeError("AI project staging path is not a directory")
        shutil.rmtree(stage_dir)


def _promote_ai_project_staging(
        stage_dir: Path, output_dir: Path, *, expected_records: dict[str, dict],
        prior_records: dict[str, dict]) -> None:
    """Atomically promote each staged file; the receipt is the logical commit."""
    _storage_policy.ensure_private_directory(output_dir)
    for name in sorted(expected_records):
        staged = stage_dir / name
        target = output_dir / name
        if not _ai_project_record_matches(staged, expected_records[name]):
            raise RuntimeError("AI project staged output changed before promotion")
        if target.exists() or _storage_policy.path_is_link_like(target):
            candidates = [
                record for record in (
                    prior_records.get(name), expected_records.get(name))
                if record is not None
            ]
            if not any(_ai_project_record_matches(target, record)
                       for record in candidates):
                raise ValueError(
                    "AI target file changed after ownership verification")
            if _ai_project_record_matches(target, expected_records[name]):
                staged.unlink()
                continue
        os.replace(staged, target)

    for entry in list(output_dir.iterdir()):
        if entry.name in expected_records:
            continue
        record = prior_records.get(entry.name)
        if record is None or not _ai_project_record_matches(entry, record):
            raise ValueError("refusing to remove an unverified stale target file")
        entry.unlink()

    if {entry.name for entry in output_dir.iterdir()} != set(expected_records):
        raise RuntimeError("AI target directory inventory is not exact")
    if any(not _ai_project_record_matches(
            output_dir / name, record)
            for name, record in expected_records.items()):
        raise RuntimeError("AI target directory bytes are not exact")


def _ai_project_export_complete_locked(
        output_dir: Path, *, target: str, paths: PipelinePaths,
        publication_receipt: dict, split_manifest: dict,
        sources: list[_ai_project_export.SourceDocument]) -> bool:
    """Validate a target against the exact live source snapshot under leases."""
    try:
        if not _pipeline_publication_complete(
                paths, expected_receipt=publication_receipt):
            return False
        receipt = _ai_project_export.parse_export_receipt_bytes(
            _ai_project_receipt_path(output_dir).read_bytes())
        profile = _ai_project_export.target_profile(target)
        if receipt["target"] != profile.name:
            return False
        documents, parameters = _ai_project_export.build_project_documents(
            sources, target=profile.name,
            max_files=receipt["parameters"]["max_files"],
            validation_policy=(
                receipt["parameters"]["markdown_validation"]))
        output_records = _ai_project_output_records(documents)
        publication_raw = paths["publication_receipt"].read_bytes()
        split_raw = _artifact_completion_path(
            paths["chapters_dir"], stage="split_export").read_bytes()
        expected_receipt = _ai_project_export.build_export_receipt(
            target=profile.name,
            publication_receipt_sha256=hashlib.sha256(
                publication_raw).hexdigest(),
            publication_evidence_root_sha256=(
                publication_receipt["evidence_root_sha256"]),
            canonical_split_manifest_sha256=hashlib.sha256(split_raw).hexdigest(),
            canonical_chunks_sha256=str(split_manifest["source_sha256"]),
            source_record_count=int(split_manifest["source_record_count"]),
            parameters=parameters,
            documents=documents,
            output_records=output_records,
        )
        if receipt != expected_receipt:
            return False
        if (_publication_core.parse_publication_receipt_bytes(publication_raw)
                != publication_receipt):
            return False
        try:
            current_split = json.loads(split_raw.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError):
            return False
        if current_split != split_manifest:
            return False
        if (_storage_policy.path_is_link_like(output_dir)
                or not output_dir.is_dir()):
            return False
        expected = {record["name"]: record for record in output_records}
        entries = list(output_dir.iterdir())
        if {entry.name for entry in entries} != set(expected):
            return False
        return all(
            _ai_project_record_matches(entry, expected[entry.name])
            for entry in entries
        )
    except (KeyError, OSError, RuntimeError, TypeError, UnicodeError, ValueError,
            _ai_project_export.AIProjectExportError):
        return False


def _ai_project_export_complete(
        output_dir: Path, *, target: str, chunks_path: Path,
        lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT) -> bool:
    """Validate exact derivative bytes against a currently READY source run."""
    try:
        with _ai_project_source_lease(chunks_path, timeout=lock_timeout):
            paths, publication, split, sources = (
                _load_ready_ai_project_source(chunks_path))
            output_dir = _reject_nested_ai_project_target(
                output_dir, run_root=paths["doc"].parent,
                target=target)
            with _ai_project_output_lease(output_dir, timeout=lock_timeout):
                return _ai_project_export_complete_locked(
                    output_dir, target=target, paths=paths,
                    publication_receipt=publication, split_manifest=split,
                    sources=sources)
    except (OSError, UnicodeError, ValueError, RuntimeError,
            _ai_project_export.AIProjectExportError):
        return False


def export_ai_project(
        chunks_path: Path, output_dir: Path, *, target: str,
        max_files: int | None = None,
        validation_policy: str = "auto",
        lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT) -> Path:
    """Publish exactly one READY-bound AI Projects upload directory."""
    profile = _ai_project_export.target_profile(target)
    validation_policy = _markdown_validation.normalize_validation_policy(
        validation_policy)
    chunks_path = Path(chunks_path)
    output_dir = Path(output_dir)
    with _ai_project_source_lease(chunks_path, timeout=lock_timeout):
        paths, publication_receipt, split_manifest, sources = (
            _load_ready_ai_project_source(chunks_path))
        run_root = paths["doc"].parent.resolve(strict=True)
        output_dir = _reject_nested_ai_project_target(
            output_dir, run_root=run_root, target=profile.name)
        _storage_policy.ensure_private_directory(output_dir.parent)
        with _ai_project_output_lease(output_dir, timeout=lock_timeout):
            documents, parameters = _ai_project_export.build_project_documents(
                sources, target=profile.name, max_files=max_files,
                validation_policy=validation_policy)
            _validate_ai_project_documents(
                documents, sources,
                validation_policy=validation_policy)
            output_records = _ai_project_output_records(documents)
            expected_records = {
                record["name"]: record for record in output_records
            }
            prior_records = _existing_ai_project_owned_records(
                output_dir, target=profile.name,
                expected_records=expected_records, paths=paths,
                publication_receipt=publication_receipt,
                split_manifest=split_manifest, sources=sources)

            stage_dir = output_dir.parent / (
                f".{output_dir.name}.ai-project-stage-{uuid4().hex}")
            _storage_policy.ensure_private_directory(stage_dir)
            primary_error: BaseException | None = None
            try:
                for document in documents:
                    _atomic_write_exact_utf8(
                        stage_dir / document.name, document.text)
                _promote_ai_project_staging(
                    stage_dir, output_dir,
                    expected_records=expected_records,
                    prior_records=prior_records)

                publication_raw = paths["publication_receipt"].read_bytes()
                split_raw = _artifact_completion_path(
                    paths["chapters_dir"], stage="split_export").read_bytes()
                if (_publication_core.parse_publication_receipt_bytes(
                        publication_raw) != publication_receipt):
                    raise RuntimeError(
                        "five-gate publication changed during AI target export")
                try:
                    current_split_manifest = json.loads(
                        split_raw.decode("utf-8"))
                except (UnicodeError, json.JSONDecodeError) as exc:
                    raise RuntimeError(
                        "canonical chapter publication changed during AI "
                        "target export") from exc
                if (current_split_manifest != split_manifest
                        or not _pipeline_publication_complete(
                            paths, expected_receipt=publication_receipt)):
                    raise RuntimeError(
                        "canonical publication changed during AI target export")

                receipt = _ai_project_export.build_export_receipt(
                    target=profile.name,
                    publication_receipt_sha256=hashlib.sha256(
                        publication_raw).hexdigest(),
                    publication_evidence_root_sha256=(
                        publication_receipt["evidence_root_sha256"]),
                    canonical_split_manifest_sha256=hashlib.sha256(
                        split_raw).hexdigest(),
                    canonical_chunks_sha256=str(split_manifest["source_sha256"]),
                    source_record_count=int(
                        split_manifest["source_record_count"]),
                    parameters=parameters,
                    documents=documents,
                    output_records=output_records,
                )
                receipt_raw = _ai_project_export.serialize_export_receipt(
                    receipt)
                receipt_path = _ai_project_receipt_path(output_dir)
                _atomic_write_exact_utf8(
                    receipt_path, receipt_raw.decode("utf-8"),
                )
                if not _ai_project_export_complete_locked(
                        output_dir, target=profile.name, paths=paths,
                        publication_receipt=publication_receipt,
                        split_manifest=split_manifest, sources=sources):
                    try:
                        if (not _storage_policy.path_is_link_like(receipt_path)
                                and receipt_path.is_file()
                                and receipt_path.read_bytes() == receipt_raw):
                            receipt_path.unlink()
                    except OSError as cleanup_error:
                        _log_cleanup_error(
                            "Stale AI project receipt cleanup failed for %s",
                            receipt_path, error=cleanup_error)
                    raise RuntimeError("AI target export receipt did not verify")
            except BaseException as exc:
                primary_error = exc
                raise
            finally:
                try:
                    _remove_ai_project_staging(
                        stage_dir, output_dir=output_dir)
                except BaseException as cleanup_error:
                    if primary_error is None:
                        raise
                    _log_cleanup_error(
                        "AI project staging cleanup failed for %s",
                        stage_dir, error=cleanup_error)

    log.info(
        "Exported %d %s project file(s) from %d canonical chapter(s) -> %s",
        len(documents), profile.directory_name, len(sources), output_dir)
    return output_dir


# ---------------------------------------------------------------------------
# Step 6: Question Extraction
# ---------------------------------------------------------------------------

# Splits on numbered questions: "1.", "2.", "(a)", "(b)", etc.
_QUESTION_SPLIT_RE = re.compile(r"(?:^|\n)\s*(?:\d{1,2}\.\s+|\([a-z]\)\s+)")


def extract_questions(chunks_path: Path, output_path: Path) -> None:
    """Extract individual questions from Notes & Questions chunks.

    Produces a JSONL file of question/context pairs suitable for
    flashcard generation, fine-tuning, or evaluation harnesses.
    """
    _require_file(chunks_path, "Chunks JSONL")
    all_chunks, _, _ = _load_index_snapshot_strict(chunks_path)
    all_chunks = _table_retrieval_core.canonical_records(all_chunks)
    chunk_by_idx = {r["metadata"]["chunk_index"]: r for r in all_chunks}

    # Filter to notes_and_questions
    records = [r for r in all_chunks
               if r["metadata"]["content_type"] == "notes_and_questions"]

    if not records:
        log.warning("No notes_and_questions chunks found.")
        return

    questions = []
    for rec in records:
        text = rec["text"]
        meta = rec["metadata"]
        idx = meta["chunk_index"]

        # Split into individual questions
        parts = _QUESTION_SPLIT_RE.split(text)
        # First part is usually preamble (heading text), skip if short
        for part in parts:
            part = part.strip()
            if len(part) < 30:
                continue
            # Only keep parts that look like questions (end with ?)
            # or are substantive discussion prompts
            if "?" in part or len(part) > 80:
                # Walk backward to find the nearest non-N&Q context chunk
                context_chunk = None
                for walk_idx in range(idx - 1, max(idx - 10, -1), -1):
                    candidate = chunk_by_idx.get(walk_idx)
                    if candidate and candidate["metadata"]["content_type"] != "notes_and_questions":
                        context_chunk = candidate
                        break
                context_text = context_chunk["text"][:500] if context_chunk else ""
                context_case = (context_chunk["metadata"].get("primary_case", "")
                                if context_chunk else "")

                questions.append({
                    "question": part,
                    "source_chunk_index": idx,
                    "context_chunk_index": context_chunk["metadata"]["chunk_index"] if context_chunk else None,
                    "context_text": context_text,
                    "context_case": context_case,
                    "chapter_num": meta.get("chapter_num"),
                    "chapter_title": meta.get("chapter_title", ""),
                    "section_path": meta.get("section_path", ""),
                })

    _atomic_write_jsonl(output_path, questions)

    log.info(f"Extracted {len(questions)} questions from "
             f"{len(records)} N&Q chunks -> {output_path}")


# ---------------------------------------------------------------------------
# Step 6b: Exam Question Generation (via LLM)
# ---------------------------------------------------------------------------

_EXAM_PROMPT = """You are a law school professor. Based on these passages from a Civil Procedure textbook,
generate 5 exam-style questions. Include:
- 2 issue-spotter hypotheticals (short fact patterns requiring analysis)
- 2 doctrinal questions (testing understanding of rules and standards)
- 1 policy question (asking about rationale behind the doctrine)

For each question, provide a brief suggested answer outline (2-3 bullet points).

Format each question as:
[TYPE] (issue_spotter / doctrinal / policy)
Q: <question text>
A:
- <bullet 1>
- <bullet 2>
- <bullet 3>
---

Chapter: {chapter}
Topic: {topic}

Passages:
{passages}

Questions:"""


def generate_exam_questions(chunks_path: Path, output_path: Path, *,
                            cloud_url: str = DEFAULT_CLOUD_URL,
                            cloud_model: str = DEFAULT_CLOUD_MODEL,
                            cloud_key: str = "",
                            ollama_url: str = DEFAULT_OLLAMA_URL,
                            ollama_model: str = DEFAULT_OLLAMA_MODEL,
                            gemini_key: str = "",
                            llm_workers: int = DEFAULT_LLM_WORKERS,
                            thinking: bool = False,
                            security_policy: (
                                _release_security.ReleaseSecurityPolicy | None
                            ) = None) -> None:
    """Generate exam-style questions from chapter chunks via LLM.

    Groups chunks by chapter, selects representative passages (mix of
    case_opinion + author_narrative), sends to LLM with the exam prompt,
    and writes structured JSONL output.
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed

    _require_file(chunks_path, "Chunks JSONL")
    all_chunks, _, _ = _load_index_snapshot_strict(chunks_path)
    all_chunks = _table_retrieval_core.canonical_records(all_chunks)

    by_chapter: dict[int, list[dict]] = {}
    for rec in all_chunks:
        ch = rec["metadata"].get("chapter_num")
        if ch is not None:
            by_chapter.setdefault(ch, []).append(rec)

    if not by_chapter:
        log.warning("No chapters found in chunks. Cannot generate questions.")
        return

    log.info(f"Generating exam questions for {len(by_chapter)} chapters")

    llm_kwargs = dict(
        ollama_url=ollama_url, ollama_model=ollama_model,
        gemini_key=gemini_key, cloud_url=cloud_url,
        cloud_model=cloud_model, cloud_key=cloud_key,
        llm_workers=llm_workers, thinking=thinking,
        security_policy=security_policy,
    )

    def _generate_for_chapter(ch_num, ch_chunks):
        preferred_types = ("case_opinion", "author_narrative")
        preferred = [c for c in ch_chunks
                     if c["metadata"].get("content_type") in preferred_types]
        other = [c for c in ch_chunks
                 if c["metadata"].get("content_type") not in preferred_types]
        selected = preferred[:7] + other[:3]
        if len(selected) < 10 and len(preferred) > 7:
            selected = preferred[:10]
        selected = selected[:10]
        if not selected:
            return []

        ch_title = selected[0]["metadata"].get("chapter_title", f"Chapter {ch_num}")
        topic = selected[0]["metadata"].get("section_path", ch_title)
        passages = "\n\n---\n\n".join(c["text"][:600] for c in selected)
        prompt = _EXAM_PROMPT.format(
            chapter=f"Chapter {ch_num}: {ch_title}",
            topic=topic, passages=passages)

        result = _call_llm(
            prompt, operation="study.exam_questions", **llm_kwargs)
        if not result:
            log.warning(f"LLM returned no response for Chapter {ch_num}")
            return []
        result = _THINK_TAG_RE.sub("", result).strip()

        questions = []
        raw_questions = re.split(r"\n---\s*\n", result)
        for raw_q in raw_questions:
            raw_q = raw_q.strip()
            if not raw_q:
                continue
            q_type = "unknown"
            type_match = re.search(
                r"\[(issue_spotter|doctrinal|policy)\]", raw_q, re.IGNORECASE)
            if type_match:
                q_type = type_match.group(1).lower()
            q_match = re.search(r"Q:\s*(.+?)(?=\nA:|\Z)", raw_q, re.DOTALL)
            question_text = q_match.group(1).strip() if q_match else raw_q
            a_match = re.search(r"A:\s*(.+)", raw_q, re.DOTALL)
            answer_text = a_match.group(1).strip() if a_match else ""
            if len(question_text) < 20:
                continue
            questions.append({
                "question": question_text,
                "question_type": q_type,
                "chapter_num": ch_num,
                "chapter_title": ch_title,
                "suggested_answer": answer_text,
                "source_chunks": [c["metadata"]["chunk_index"] for c in selected],
            })
        return questions

    all_questions = []
    is_cloud = bool(cloud_url and cloud_key)
    workers = min(llm_workers, len(by_chapter)) if is_cloud else 1

    if workers > 1:
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futures = {
                pool.submit(_generate_for_chapter, ch_num, ch_chunks): ch_num
                for ch_num, ch_chunks in sorted(by_chapter.items())
            }
            for future in as_completed(futures):
                ch_num = futures[future]
                try:
                    qs = future.result()
                    all_questions.extend(qs)
                    log.info(f"  Chapter {ch_num}: {len(qs)} questions")
                except (LLMBudgetExceeded, LLMExecutionError):
                    raise
                except Exception as e:
                    log.warning(f"  Chapter {ch_num} failed: {e}")
    else:
        for ch_num, ch_chunks in sorted(by_chapter.items()):
            qs = _generate_for_chapter(ch_num, ch_chunks)
            all_questions.extend(qs)
            log.info(f"  Chapter {ch_num}: {len(qs)} questions")

    _atomic_write_jsonl(output_path, all_questions)

    log.info(f"Generated {len(all_questions)} exam questions from "
             f"{len(by_chapter)} chapters -> {output_path}")


# ---------------------------------------------------------------------------
# Step 7: Citation Graph
# ---------------------------------------------------------------------------

# Case citation: "International Shoe Co. v. Washington, 326 U.S. 310 (1945)"
_FULL_CITE_RE = re.compile(
    r"((?:(?:In re|Ex parte)\s+)?[A-Z][A-Za-z\'\-\.]+(?:\s+[A-Za-z\'\-\.]+)*"
    r"\s+v\.\s+"
    r"[A-Z][A-Za-z\'\-\.]+(?:\s+[A-Za-z\'\-\.,]+)*)"
    r"(?:,\s*(\d{1,3}\s+[A-Z][A-Za-z\.\s]+\s+\d{1,4}))?"  # reporter cite
    r"(?:\s*\((\d{4})\))?"  # year
)
# Short-form: "Shoe, supra", "Burger King, supra at 462"
_SUPRA_RE = re.compile(r"(\b[A-Z][A-Za-z\'\-\.]+(?:\s+[A-Z][A-Za-z\'\-\.]+)?),?\s+supra")
# Statute: "28 U.S.C. § 1332", "Fed. R. Civ. P. 12"
_STATUTE_RE = re.compile(
    r"(\d{1,2}\s+U\.S\.C\.\s*(?:§+\s*)?\d{1,5}(?:\([a-z]\))?|"
    r"Fed\.\s*R\.\s*Civ\.\s*P\.\s*\d{1,3}(?:\([a-z]\))?|"
    r"Rule\s+\d{1,3}(?:\([a-z]\))?)"
)


def build_citation_graph(chunks_path: Path, output_path: Path) -> None:
    """Parse cross-references from all chunks into a citation graph.

    Output JSON with nodes (chunks, cases, statutes) and edges (citations).
    """
    records = _load_and_filter_chunks(chunks_path)

    nodes = {}  # id -> {type, label, ...}
    edges = []  # {source, target, type}

    # Add all chunks as nodes (using stable content-hash IDs)
    for rec in records:
        cid = _chunk_id(rec)
        idx = rec["metadata"]["chunk_index"]
        nodes[cid] = {
            "id": cid,
            "type": "chunk",
            "label": rec["metadata"].get("section_path", f"Chunk {idx}")[:80],
            "chapter": rec["metadata"].get("chapter_num"),
            "content_type": rec["metadata"]["content_type"],
        }

    all_cases = {}   # normalized name -> first chunk seen
    all_statutes = {}  # statute text -> first chunk seen

    for rec in records:
        text = rec["text"]
        chunk_id = _chunk_id(rec)

        # Full case citations
        for m in _FULL_CITE_RE.finditer(text):
            case_name = m.group(1).strip().rstrip(".,;")
            if len(case_name) < 8:
                continue
            case_id = re.sub(r"[^a-z0-9]", "_", case_name.lower())

            if case_id not in nodes:
                reporter = m.group(2).strip() if m.group(2) else ""
                year = m.group(3) if m.group(3) else ""
                nodes[case_id] = {
                    "id": case_id,
                    "type": "case",
                    "label": case_name,
                    "reporter": reporter,
                    "year": year,
                }
                all_cases[case_id] = idx

            edges.append({
                "source": chunk_id,
                "target": case_id,
                "type": "cites_case",
            })

        # Supra references (short-form)
        for m in _SUPRA_RE.finditer(text):
            short_name = m.group(1).strip()
            # Try to match to a known case
            short_id = re.sub(r"[^a-z0-9]", "_", short_name.lower())
            matched = None
            for cid in all_cases:
                if short_id in cid:
                    matched = cid
                    break
            if matched:
                edges.append({
                    "source": chunk_id,
                    "target": matched,
                    "type": "cites_supra",
                })

        # Statute citations
        for m in _STATUTE_RE.finditer(text):
            statute = m.group(1).strip()
            stat_id = re.sub(r"[^a-z0-9]", "_", statute.lower())

            if stat_id not in nodes:
                nodes[stat_id] = {
                    "id": stat_id,
                    "type": "statute",
                    "label": statute,
                }
                all_statutes[stat_id] = idx

            edges.append({
                "source": chunk_id,
                "target": stat_id,
                "type": "cites_statute",
            })

        # Cross-chapter references (from existing metadata)
        for xref in rec["metadata"].get("cross_references", []):
            if xref not in nodes:
                nodes[xref] = {"id": xref, "type": "chapter_ref", "label": xref}
            edges.append({
                "source": chunk_id,
                "target": xref,
                "type": "cross_reference",
            })

    # Deduplicate edges
    seen_edges = set()
    unique_edges = []
    for e in edges:
        key = (e["source"], e["target"], e["type"])
        if key not in seen_edges:
            seen_edges.add(key)
            unique_edges.append(e)

    graph = {
        "nodes": list(nodes.values()),
        "edges": unique_edges,
        "stats": {
            "total_nodes": len(nodes),
            "chunk_nodes": sum(1 for n in nodes.values() if n["type"] == "chunk"),
            "case_nodes": sum(1 for n in nodes.values() if n["type"] == "case"),
            "statute_nodes": sum(1 for n in nodes.values() if n["type"] == "statute"),
            "total_edges": len(unique_edges),
        },
    }

    _atomic_write_text(
        output_path, json.dumps(graph, indent=2, ensure_ascii=False))

    s = graph["stats"]
    log.info(f"Citation graph -> {output_path}")
    log.info(f"  {s['chunk_nodes']} chunks, {s['case_nodes']} cases, "
             f"{s['statute_nodes']} statutes, {s['total_edges']} edges")


# ---------------------------------------------------------------------------
# Step 8b: Case Brief Generation
# ---------------------------------------------------------------------------

_BRIEF_PROMPT = """Generate a case brief for this judicial opinion from a law textbook.
Format your response as:
FACTS: [key facts in 2-3 sentences]
ISSUE: [the legal question presented]
HOLDING: [the court's decision]
REASONING: [the court's legal reasoning in 2-3 sentences]

Opinion text:
{text}

Case brief:"""


def generate_briefs(chunks_path: Path, output_path: Path, *,
                    cloud_url: str = DEFAULT_CLOUD_URL,
                    cloud_model: str = DEFAULT_CLOUD_MODEL,
                    cloud_key: str = "",
                    ollama_url: str = DEFAULT_OLLAMA_URL,
                    ollama_model: str = DEFAULT_OLLAMA_MODEL,
                    gemini_key: str = "",
                    llm_workers: int = DEFAULT_LLM_WORKERS,
                    thinking: bool = False,
                    security_policy: (
                        _release_security.ReleaseSecurityPolicy | None
                    ) = None) -> None:
    """Generate case briefs for all case_opinion chunks via LLM."""
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from tqdm import tqdm

    _require_file(chunks_path, "Chunks JSONL")
    records, _, _ = _load_index_snapshot_strict(chunks_path)
    records = _table_retrieval_core.canonical_records(records)

    # Filter to case opinions only
    case_chunks = [r for r in records
                   if r.get("metadata", {}).get("content_type") == "case_opinion"]

    if not case_chunks:
        log.warning("No case_opinion chunks found — nothing to brief.")
        return

    log.info(f"Generating briefs for {len(case_chunks)} case opinion chunks...")

    llm_kwargs = dict(ollama_url=ollama_url, ollama_model=ollama_model,
                      gemini_key=gemini_key, cloud_url=cloud_url,
                      cloud_model=cloud_model, cloud_key=cloud_key,
                      llm_workers=llm_workers, thinking=thinking,
                      security_policy=security_policy)

    def _parse_brief(response: str) -> dict:
        """Parse a brief response into structured fields."""
        fields = {"facts": "", "issue": "", "holding": "", "reasoning": ""}
        if not response:
            return fields
        # Clean think tags
        response = _THINK_TAG_RE.sub("", response).strip()
        current_key = None
        current_lines: list[str] = []
        for line in response.split("\n"):
            stripped = line.strip()
            matched = False
            for key in fields:
                if stripped.upper().startswith(key.upper() + ":"):
                    if current_key:
                        fields[current_key] = " ".join(current_lines).strip()
                    current_key = key
                    current_lines = [stripped[len(key) + 1:].strip()]
                    matched = True
                    break
            if not matched and current_key:
                current_lines.append(stripped)
        if current_key:
            fields[current_key] = " ".join(current_lines).strip()
        return fields

    def _brief_one(rec: dict) -> Optional[dict]:
        text = rec["text"]
        meta = rec["metadata"]
        prompt = _BRIEF_PROMPT.format(text=text[:3000])
        result = _call_llm(prompt, operation="study.case_brief", **llm_kwargs)
        if not result:
            return None
        parsed = _parse_brief(result)
        return {
            "case_name": meta.get("primary_case", "Unknown Case"),
            "facts": parsed["facts"],
            "issue": parsed["issue"],
            "holding": parsed["holding"],
            "reasoning": parsed["reasoning"],
            "page_range": meta.get("page_range", ""),
            "chapter_num": meta.get("chapter_num"),
        }

    briefs: list[dict] = []

    with ThreadPoolExecutor(max_workers=llm_workers) as pool:
        futures = {pool.submit(_brief_one, rec): i
                   for i, rec in enumerate(case_chunks)}
        for future in tqdm(as_completed(futures), total=len(futures),
                           desc="Briefing cases"):
            result = future.result()
            if result:
                briefs.append(result)

    # Sort by chapter then page for stable output
    briefs.sort(key=lambda b: (b.get("chapter_num") or 0, b.get("page_range", "")))

    _atomic_write_jsonl(output_path, briefs)

    log.info(f"Generated {len(briefs)} case briefs -> {output_path}")


# ---------------------------------------------------------------------------
# Step 7c: Chunk Quality Scoring
# ---------------------------------------------------------------------------

_QUALITY_PROMPT = """Rate this text from a law textbook for its usefulness in answering law school exam questions.
Score 1-5:
1 = Procedural noise, boilerplate, or formatting artifacts
2 = Background context with minimal legal content
3 = Useful explanatory text about legal concepts
4 = Important doctrinal analysis, key rules, or significant case discussion
5 = Essential doctrine: landmark holdings, foundational rules, or critical analysis

Text (first 500 chars):
{text}

Content type: {content_type}

Reply with ONLY the number (1-5):"""


def _score_chunk_quality(text: str, content_type: str, **llm_kwargs) -> int:
    """Rate a chunk's usefulness via LLM. Returns 1-5 (default 3 on failure)."""
    prompt = _QUALITY_PROMPT.format(text=text[:500], content_type=content_type)
    result = _call_llm(prompt, operation="chunk.quality", **llm_kwargs)
    if result:
        result = _THINK_TAG_RE.sub("", result).strip()
        for ch in result:
            if ch.isdigit() and 1 <= int(ch) <= 5:
                return int(ch)
    return 3  # default: useful


# ---------------------------------------------------------------------------
# Step 7d: Flashcard Export
# ---------------------------------------------------------------------------

_FLASHCARD_PROMPT = """Create a study flashcard from this law textbook passage.
Front: A clear question testing understanding of the legal concept.
Back: A concise answer (2-3 sentences) with the key rule or holding.

Passage ({content_type}, {page_range}):
{text}

Format your response exactly as:
Q: [question]
A: [answer]"""


def _export_flashcards(chunks: list[dict], export_path: Path, *,
                       cloud_url: str = DEFAULT_CLOUD_URL,
                       cloud_model: str = DEFAULT_CLOUD_MODEL,
                       cloud_key: str = "",
                       ollama_url: str = DEFAULT_OLLAMA_URL,
                       ollama_model: str = DEFAULT_OLLAMA_MODEL,
                       gemini_key: str = "",
                       llm_workers: int = DEFAULT_LLM_WORKERS,
                       thinking: bool = False,
                       security_policy: (
                           _release_security.ReleaseSecurityPolicy | None
                       ) = None) -> None:
    """Generate Anki-compatible flashcards from chunks via LLM."""
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from tqdm import tqdm

    is_cloud = bool(cloud_url and cloud_key)
    workers = llm_workers if is_cloud else 1
    llm_kwargs = dict(ollama_url=ollama_url, ollama_model=ollama_model,
                      gemini_key=gemini_key, cloud_url=cloud_url,
                      cloud_model=cloud_model, cloud_key=cloud_key,
                      llm_workers=llm_workers, thinking=thinking,
                      security_policy=security_policy)

    def _generate_card(rec):
        meta = rec["metadata"]
        prompt = _FLASHCARD_PROMPT.format(
            text=rec["text"][:800],
            content_type=meta.get("content_type", ""),
            page_range=meta.get("page_range", ""),
        )
        result = _call_llm(prompt, operation="study.flashcard", **llm_kwargs)
        if not result:
            return None
        result = _THINK_TAG_RE.sub("", result).strip()
        # Parse Q: / A: format
        q, a = "", ""
        for line in result.split("\n"):
            line = line.strip()
            if line.startswith("Q:"):
                q = line[2:].strip()
            elif line.startswith("A:"):
                a = line[2:].strip()
        if not q or not a:
            return None
        # Build tags from metadata
        tags = []
        ch = meta.get("chapter_num")
        if ch is not None:
            tags.append(f"ch{ch}")
        ct = meta.get("content_type", "")
        if ct:
            tags.append(ct)
        case = meta.get("primary_case", "")
        if case:
            tags.append(case.replace(" ", "_")[:30])
        return {"front": q, "back": a, "tags": tags, "metadata": {
            "chunk_index": meta.get("chunk_index"),
            "page_range": meta.get("page_range", ""),
            "chapter_num": ch,
            "content_type": ct,
        }}

    log.info(f"Generating flashcards from {len(chunks)} chunks "
             f"({workers} workers)...")
    cards = []
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = {pool.submit(_generate_card, rec): rec for rec in chunks}
        for future in tqdm(as_completed(futures), total=len(futures),
                           desc="Flashcards", unit="card"):
            card = future.result()
            if card:
                cards.append(card)

    if not cards:
        log.warning("No flashcards generated.")
        return

    # Write TSV (Anki import format)
    tsv_path = export_path.with_suffix(".tsv")
    tsv_lines = []
    for card in cards:
        tags_str = " ".join(card["tags"])
        tsv_lines.append(
            f"{card['front']}\t{card['back']}\t{tags_str}\n")
    _atomic_write_text(tsv_path, "".join(tsv_lines))

    # Write JSON sidecar with full metadata
    json_path = export_path.with_suffix(".flashcards.json")
    _atomic_write_text(
        json_path, json.dumps(cards, indent=2, ensure_ascii=False))

    log.info(f"Generated {len(cards)} flashcards")
    log.info(f"  Anki TSV:  {tsv_path}")
    log.info(f"  Full JSON: {json_path}")


# ---------------------------------------------------------------------------
# Step 8: RAPTOR — Recursive Abstractive Processing for Tree-Organized Retrieval
# ---------------------------------------------------------------------------

_RAPTOR_SUMMARY_PROMPT = """Summarize these {n} passages from a law school textbook.
Focus on: the legal concepts discussed, key case names and holdings, doctrinal
rules, and statutory provisions. Write 2-3 concise sentences.

Passages:
{texts}

Summary (2-3 sentences):"""


def _cluster_embeddings(embeddings: list[list[float]], k: int) -> list[list[int]]:
    """K-means clustering on embeddings. Returns list of index groups."""
    import numpy as np

    embs = np.array(embeddings)
    n = len(embs)
    if n == 0:
        return []
    k = min(k, n)
    if k <= 1:
        return [list(range(n))]

    # Simple k-means (sklearn-free)
    rng = np.random.default_rng(42)
    # Initialize centroids with k-means++
    centroids = [embs[rng.integers(n)]]
    for _ in range(k - 1):
        dists = np.min([np.sum((embs - c) ** 2, axis=1) for c in centroids], axis=0)
        total_distance = dists.sum()
        if not np.isfinite(total_distance) or total_distance <= 0:
            # All remaining points coincide with an existing centroid. Any
            # point is a valid deterministic fallback; k-means will collapse
            # duplicate centroids into a single non-empty cluster below.
            centroids.append(embs[len(centroids) % n])
        else:
            probs = dists / total_distance
            centroids.append(embs[rng.choice(n, p=probs)])
    centroids = np.array(centroids)

    for _ in range(20):  # max iterations
        # Assign points to nearest centroid
        dists = np.array([np.sum((embs - c) ** 2, axis=1) for c in centroids])
        labels = np.argmin(dists, axis=0)
        # Update centroids
        new_centroids = np.array([
            embs[labels == i].mean(axis=0) if (labels == i).any() else centroids[i]
            for i in range(k)
        ])
        if np.allclose(centroids, new_centroids, atol=1e-6):
            break
        centroids = new_centroids

    clusters: list[list[int]] = [[] for _ in range(k)]
    for idx, label in enumerate(labels):
        clusters[label].append(idx)
    return [c for c in clusters if c]  # remove empty clusters


def _raptor_parameters(*, embedding_model: str, cloud_url: str,
                       cloud_model: str, cloud_key: str,
                       ollama_url: str, ollama_model: str,
                       gemini_key: str, thinking: bool,
                       security_policy: (
                           _release_security.ReleaseSecurityPolicy | None
                       ) = None) -> dict:
    policy = _effective_security_policy(security_policy)
    gemini_configured = bool(
        policy.network_policy == "allow-cloud"
        and (gemini_key or "GEMINI_API_KEY" in os.environ))
    return {
        "embedding_model": embedding_model,
        "cloud_url": _endpoint_parameter_binding(cloud_url),
        "cloud_model": cloud_model,
        "cloud_configured": bool(cloud_url and cloud_key),
        "ollama_url": _endpoint_parameter_binding(ollama_url),
        "ollama_model": ollama_model,
        "gemini_configured": gemini_configured,
        "thinking": thinking,
        "prompt_version": 1,
        "release_security": policy.provenance(),
    }


def _raptor_output_complete(chunks_path: Path, output_path: Path, *,
                            parameters: dict) -> bool:
    try:
        source_records, source_sha256, _ = _load_index_snapshot_strict(
            chunks_path)
    except (OSError, UnicodeError, ValueError, RuntimeError):
        return False
    source_count = len(
        _table_retrieval_core.canonical_records(source_records))
    try:
        tree = json.loads(output_path.read_text(encoding="utf-8"))
        if not isinstance(tree, dict):
            return False
        expected = {
            "schema_version": ARTIFACT_COMPLETION_SCHEMA_VERSION,
            "source_sha256": source_sha256,
            "source_record_count": source_count,
            "parameters_sha256": _artifact_parameters_sha256(parameters),
        }
        if any(tree.get(key) != value for key, value in expected.items()):
            return False
        levels = tree.get("levels")
        nodes = tree.get("nodes")
        stats = tree.get("stats")
        if levels not in {2, 3} or not isinstance(nodes, list) or not nodes:
            return False
        if not isinstance(stats, dict):
            return False
        node_ids = []
        level_counts = {0: 0, 1: 0, 2: 0}
        for node in nodes:
            if not isinstance(node, dict):
                return False
            node_id = node.get("node_id")
            level = node.get("level")
            if (not isinstance(node_id, str) or not node_id
                    or level not in level_counts
                    or not isinstance(node.get("children"), list)):
                return False
            node_ids.append(node_id)
            level_counts[level] += 1
        if len(node_ids) != len(set(node_ids)):
            return False
        known_ids = set(node_ids)
        node_levels = {node["node_id"]: node["level"] for node in nodes}
        if any(child not in known_ids for node in nodes
               for child in node["children"]):
            return False
        if any(
                (node["level"] == 0 and node["children"])
                or any(node_levels[child] != node["level"] - 1
                       for child in node["children"])
                for node in nodes):
            return False
        if ((levels == 2 and level_counts[2] != 0)
                or (levels == 3 and level_counts[2] == 0)):
            return False
        return (
            level_counts[0] == source_count
            and stats.get("level_0") == level_counts[0]
            and stats.get("level_1") == level_counts[1]
            and stats.get("level_2") == level_counts[2]
            and stats.get("total") == len(nodes)
        )
    except (OSError, UnicodeError, json.JSONDecodeError, TypeError):
        return False


def build_raptor_tree(chunks_path: Path, output_path: Path, *,
                      embedding_model: str = DEFAULT_EMBEDDING_MODEL,
                      cloud_url: str = DEFAULT_CLOUD_URL,
                      cloud_model: str = DEFAULT_CLOUD_MODEL,
                      cloud_key: str = "",
                      ollama_url: str = DEFAULT_OLLAMA_URL,
                      ollama_model: str = DEFAULT_OLLAMA_MODEL,
                      gemini_key: str = "",
                      llm_workers: int = DEFAULT_LLM_WORKERS,
                      thinking: bool = False,
                      security_policy: (
                          _release_security.ReleaseSecurityPolicy | None
                      ) = None) -> None:
    """Build a 3-level RAPTOR tree over chunks.

    Level 0: Raw chunks (from JSONL)
    Level 1: Section summaries (clusters of ~5-10 chunks)
    Level 2: Chapter summaries (clusters of Level 1 nodes)

    Output is a JSON file with all tree nodes. Indexing those summaries is a
    separate concern; this command does not mutate an existing vector index.
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from tqdm import tqdm

    records, source_sha256, _ = _load_index_snapshot_strict(chunks_path)
    records = _table_retrieval_core.canonical_records(records)
    source_record_count = len(records)
    parameters = _raptor_parameters(
        embedding_model=embedding_model, cloud_url=cloud_url,
        cloud_model=cloud_model, cloud_key=cloud_key,
        ollama_url=ollama_url, ollama_model=ollama_model,
        gemini_key=gemini_key, thinking=thinking,
        security_policy=security_policy)
    log.info(f"RAPTOR: building tree over {len(records)} chunks")

    if not records:
        log.warning("No chunks to build RAPTOR tree from.")
        return

    is_cloud = bool(cloud_url and cloud_key)
    llm_kwargs = dict(ollama_url=ollama_url, ollama_model=ollama_model,
                      gemini_key=gemini_key, cloud_url=cloud_url,
                      cloud_model=cloud_model, cloud_key=cloud_key,
                      llm_workers=llm_workers, thinking=thinking,
                      security_policy=security_policy)

    def _summarize(texts: list[str]) -> str:
        """Summarize a cluster of texts via LLM."""
        combined = "\n\n---\n\n".join(t[:500] for t in texts)  # cap per-text
        prompt = _RAPTOR_SUMMARY_PROMPT.format(n=len(texts), texts=combined[:3000])
        result = _call_llm(prompt, operation="raptor.summarize", **llm_kwargs)
        if result:
            result = _THINK_TAG_RE.sub("", result).strip()
            sentences = re.split(r"(?<=[.!?])\s+", result)
            return " ".join(sentences[:3])
        return ""

    # --- Level 0: Raw chunks (already have embeddings implicitly) ---
    log.info("RAPTOR Level 0: Embedding chunks...")
    texts_l0 = [r["text"] for r in records]
    try:
        embeddings_l0 = _embed_texts(
            texts_l0, embedding_model, security_policy=security_policy)
    except Exception as e:
        log.error(f"RAPTOR embedding failed: {e}")
        log.error("  Check --embedding-model and API keys.")
        raise RuntimeError("RAPTOR embedding failed") from e

    tree_nodes = []
    # Add level 0 nodes
    for i, r in enumerate(records):
        tree_nodes.append({
            "text": r["text"],
            "level": 0,
            "is_summary": False,
            "node_id": f"L0_{i}",
            "children": [],
            "metadata": r["metadata"],
        })

    # --- Level 1: Section summaries (cluster into ~5-10 chunks each) ---
    # Target ~60-80 clusters for a textbook with ~275 chunks
    n_clusters_l1 = max(5, len(records) // 5)
    log.info(f"RAPTOR Level 1: Clustering {len(records)} chunks "
             f"into ~{n_clusters_l1} sections...")
    clusters_l1 = _cluster_embeddings(embeddings_l0, n_clusters_l1)
    log.info(f"  Formed {len(clusters_l1)} clusters")

    # Summarize each cluster (parallel for cloud, sequential for local)
    log.info(f"RAPTOR Level 1: Summarizing {len(clusters_l1)} sections...")
    texts_l1 = []
    metas_l1 = []
    workers = llm_workers if is_cloud else 1

    def _summarize_cluster(cluster_indices):
        cluster_texts = [texts_l0[i] for i in cluster_indices]
        summary = _summarize(cluster_texts)
        # Inherit chapter from majority of cluster members
        ch_counts: dict = {}
        for i in cluster_indices:
            ch = records[i]["metadata"].get("chapter_num")
            if ch is not None:
                ch_counts[ch] = ch_counts.get(ch, 0) + 1
        majority_ch = max(ch_counts, key=ch_counts.get) if ch_counts else None
        ch_title = ""
        if majority_ch is not None:
            for i in cluster_indices:
                t = records[i]["metadata"].get("chapter_title", "")
                if t and records[i]["metadata"].get("chapter_num") == majority_ch:
                    ch_title = t
                    break
        return summary, cluster_indices, majority_ch, ch_title

    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = [pool.submit(_summarize_cluster, c) for c in clusters_l1]
        for future in tqdm(as_completed(futures), total=len(futures),
                           desc="Level 1 summaries", unit="cluster"):
            summary, indices, ch_num, ch_title = future.result()
            if summary:
                node_id = f"L1_{len(texts_l1)}"
                texts_l1.append(summary)
                metas_l1.append({
                    "chapter_num": ch_num,
                    "chapter_title": ch_title,
                    "content_type": "raptor_summary",
                    "content_source": "summary",
                })
                tree_nodes.append({
                    "text": summary,
                    "level": 1,
                    "is_summary": True,
                    "node_id": node_id,
                    "children": [f"L0_{i}" for i in indices],
                    "metadata": metas_l1[-1],
                })

    log.info(f"  Generated {len(texts_l1)} section summaries")

    if not texts_l1:
        raise RuntimeError(
            "RAPTOR produced no summaries; check LLM connectivity")

    # --- Level 2: Chapter summaries (cluster Level 1 nodes) ---
    log.info("RAPTOR Level 2: Embedding section summaries...")
    try:
        embeddings_l1 = _embed_texts(
            texts_l1, embedding_model, security_policy=security_policy)
    except Exception as e:
        log.error(f"RAPTOR Level 2 embedding failed: {e}")
        log.error("  Saving partial tree (Level 0 + Level 1 only).")
        # Save what we have
        tree = {
                "schema_version": ARTIFACT_COMPLETION_SCHEMA_VERSION,
                "source_sha256": source_sha256,
                "source_record_count": source_record_count,
                "parameters_sha256": _artifact_parameters_sha256(parameters),
                "levels": 2, "nodes": tree_nodes,
                "stats": {"level_0": sum(1 for n in tree_nodes if n["level"] == 0),
                           "level_1": sum(1 for n in tree_nodes if n["level"] == 1),
                           "level_2": 0, "total": len(tree_nodes)}}
        _atomic_write_json(output_path, tree)
        return

    # Target ~15 chapter-level clusters
    n_clusters_l2 = max(3, len(texts_l1) // 4)
    log.info(f"RAPTOR Level 2: Clustering {len(texts_l1)} sections "
             f"into ~{n_clusters_l2} chapters...")
    clusters_l2 = _cluster_embeddings(embeddings_l1, n_clusters_l2)

    log.info(f"RAPTOR Level 2: Summarizing {len(clusters_l2)} chapter overviews...")
    texts_l2 = []

    with ThreadPoolExecutor(max_workers=workers) as pool:
        def _summarize_l2(cluster_indices):
            cluster_texts = [texts_l1[i] for i in cluster_indices]
            summary = _summarize(cluster_texts)
            ch_counts: dict = {}
            for i in cluster_indices:
                ch = metas_l1[i].get("chapter_num")
                if ch is not None:
                    ch_counts[ch] = ch_counts.get(ch, 0) + 1
            majority_ch = max(ch_counts, key=ch_counts.get) if ch_counts else None
            ch_title = metas_l1[cluster_indices[0]].get("chapter_title", "") if cluster_indices else ""
            return summary, cluster_indices, majority_ch, ch_title

        futures = [pool.submit(_summarize_l2, c) for c in clusters_l2]
        for future in tqdm(as_completed(futures), total=len(futures),
                           desc="Level 2 summaries", unit="cluster"):
            summary, indices, ch_num, ch_title = future.result()
            if summary:
                node_id = f"L2_{len(texts_l2)}"
                texts_l2.append(summary)
                tree_nodes.append({
                    "text": summary,
                    "level": 2,
                    "is_summary": True,
                    "node_id": node_id,
                    "children": [f"L1_{i}" for i in indices],
                    "metadata": {
                        "chapter_num": ch_num,
                        "chapter_title": ch_title,
                        "content_type": "raptor_summary",
                        "content_source": "summary",
                    },
                })

    # --- Save tree ---
    _storage_policy.ensure_private_directory(output_path.parent)
    tree = {
        "schema_version": ARTIFACT_COMPLETION_SCHEMA_VERSION,
        "source_sha256": source_sha256,
        "source_record_count": source_record_count,
        "parameters_sha256": _artifact_parameters_sha256(parameters),
        "levels": 3,
        "nodes": tree_nodes,
        "stats": {
            "level_0": sum(1 for n in tree_nodes if n["level"] == 0),
            "level_1": sum(1 for n in tree_nodes if n["level"] == 1),
            "level_2": sum(1 for n in tree_nodes if n["level"] == 2),
            "total": len(tree_nodes),
        },
    }
    _atomic_write_json(output_path, tree)

    s = tree["stats"]
    log.info(f"RAPTOR tree -> {output_path}")
    log.info(f"  Level 0 (chunks):   {s['level_0']}")
    log.info(f"  Level 1 (sections): {s['level_1']}")
    log.info(f"  Level 2 (chapters): {s['level_2']}")
    log.info(f"  Total nodes:        {s['total']}")


# ---------------------------------------------------------------------------
# Step 9: Info
# ---------------------------------------------------------------------------

def _pipeline_run_is_ready(
        output_root: Path, run_name: str, *,
        lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT) -> bool:
    """Return whether one lease-held run and its five-gate commit both pass."""
    output_root = Path(output_root)
    try:
        observed_path, observed = _retention.load_pipeline_run_manifest(
            output_root, run_name)
        if observed.get("state") != "complete":
            return False
        observed_scope = observed.get("job_scope")
        observed_token = observed.get("ownership_token")
        if (not isinstance(observed_scope, str) or not observed_scope
                or not isinstance(observed_token, str) or not observed_token):
            return False
        with _pipeline_job_lock(
                scope_name=observed_scope, timeout=lock_timeout,
                output_root=output_root):
            current_path, current = _retention.load_pipeline_run_manifest(
                output_root, run_name)
            current_scope = current.get("job_scope")
            if (current_path.resolve(strict=True)
                    != observed_path.resolve(strict=True)
                    or current.get("state") != "complete"
                    or current.get("ownership_token") != observed_token
                    or not isinstance(current_scope, str)
                    or os.path.normcase(current_scope)
                    != os.path.normcase(observed_scope)):
                return False
            run_root = output_root / run_name
            paths = dict(_output_paths_for_name(run_name))
            paths["doc"] = run_root / f"{run_name}.json"
            paths["publication_receipt"] = (
                run_root / ".rag-publication.json")
            return _pipeline_publication_complete(paths)
    except (OSError, UnicodeError, ValueError, RuntimeError):
        return False


def show_info(chroma_dir: Path, collection_name: str = DEFAULT_COLLECTION, *,
              db_backend: str = DEFAULT_DB_BACKEND,
              lock_timeout: float = DEFAULT_DB_LOCK_TIMEOUT) -> None:
    """Show status of pipeline output artifacts.

    Scans the output directory for all pipeline artifacts, not just default paths.

    ``chroma_dir`` retains the original public keyword for compatibility; when
    ``db_backend='qdrant'`` it identifies the selected Qdrant directory instead.
    """
    db_dir = Path(chroma_dir)
    print(f"\n{'='*60}")
    print(" Pipeline Output Status")
    print(f"{'='*60}\n")

    out = OUTPUT_DIR
    if not out.exists():
        print("  No output directory found.")
        return

    # Scan for all pipeline outputs in the output directory
    def _show_file(label: str, path: Path):
        try:
            try:
                display_name = str(path.relative_to(out))
            except ValueError:
                display_name = str(path)
            if path.is_dir():
                size = sum(
                    f.stat().st_size
                    for f in path.rglob("*") if f.is_file())
                print(
                    f"  [OK] {label:20s} {display_name:40s} "
                    f"({size / 1e6:.1f} MB)")
            else:
                stat_result = path.stat()
                size = stat_result.st_size
                mtime = time.strftime(
                    "%Y-%m-%d %H:%M",
                    time.localtime(stat_result.st_mtime))
                print(f"  [OK] {label:20s} {display_name:40s} "
                      f"({size / 1e6:.1f} MB, {mtime})")
        except OSError as exc:
            print(f"  [BUSY] {label:20s} {path} (status unavailable: {exc})")

    # Group by file type. Current runs live under output/<book>/ while older
    # runs may still use the output root, so scan recursively.
    jsons = sorted(
        p for p in out.rglob("*.json")
        if (p.parent == out or p.stem == p.parent.name)
        and not p.name.endswith(("_raptor.json", ".metadata.json"))
        and "citation" not in p.stem.lower()
    )
    chunks = sorted(out.rglob("*_chunks.jsonl"))
    quality_reports = sorted(out.rglob("*_chunks.quality.json"))
    questions_jsonls = sorted(out.rglob("*questions*.jsonl"))
    citations_jsons = sorted(out.rglob("*citations*.json"))
    markdowns = sorted(out.rglob("*.md"))
    chroma_dirs = sorted(
        p for p in out.rglob("*")
        if p.is_dir() and (p.name.endswith("_chroma") or p.name == "chroma_db")
    )
    qdrant_dirs = sorted(
        p for p in out.rglob("*")
        if p.is_dir() and (p.name.endswith("_qdrant") or p.name == "qdrant_db")
    )
    chapter_dirs = sorted(
        p for p in out.rglob("*")
        if p.is_dir() and (p.name == "Chapters" or p.name.endswith("_chapters"))
    )

    logical_run_roots = sorted(
        {
            marker.parent
            for pattern in (
                f"*/{_retention.RUN_MANIFEST_NAME}",
                "*/.rag-publication.json",
            )
            for marker in out.glob(pattern)
        },
        key=lambda path: path.name.casefold(),
    )
    if logical_run_roots:
        print("  Logical publications (artifact [OK] alone is not readiness):")
        for run_root in logical_run_roots:
            status = (
                "READY" if _pipeline_run_is_ready(
                    out, run_root.name, lock_timeout=lock_timeout)
                else "STALE"
            )
            print(f"  [{status}] {run_root.name}")

    if jsons:
        print("  DoclingDocuments:")
        for p in jsons:
            # Skip sidecar files (chunk hashes)
            if p.name in ("chunk_hashes.json",):
                continue
            _show_file("", p)

    if chunks:
        print("  Chunk files:")
        for p in chunks:
            _show_file("", p)

    if quality_reports:
        print("  Corpus quality reports:")
        for report_path in quality_reports:
            chunks_path = report_path.with_name(
                report_path.name.removesuffix(".quality.json") + ".jsonl")
            try:
                records, _, _ = _load_index_snapshot_strict(chunks_path)
                payload = json.loads(report_path.read_text(encoding="utf-8"))
                label = (
                    f"PASS v{payload.get('schema_version')} "
                    f"({len(records)} chunks)"
                )
            except (OSError, UnicodeError, json.JSONDecodeError, ValueError,
                    RuntimeError):
                label = "FAIL"
            _show_file(label, report_path)

    if questions_jsonls:
        print("  Questions files:")
        for p in questions_jsonls:
            _show_file("", p)

    if citations_jsons:
        print("  Citations files:")
        for p in citations_jsons:
            _show_file("", p)

    if markdowns:
        print("  Markdown exports:")
        for p in markdowns:
            _show_file("", p)

    if chapter_dirs:
        print("  Chapter splits:")
        for d in chapter_dirs:
            n_files = len(list(d.glob("*.md")))
            _show_file(f"({n_files} files)", d)

    if chroma_dirs:
        print("  ChromaDB indexes:")
        for d in chroma_dirs:
            _show_file("", d)

    # RAPTOR trees
    raptor_files = sorted(out.rglob("*_raptor.json"))
    if raptor_files:
        print("  RAPTOR trees:")
        for p in raptor_files:
            try:
                tree = json.loads(p.read_text(encoding="utf-8"))
                stats = tree.get("stats", {})
                label = (f"L0:{stats.get('level_0', '?')} "
                         f"L1:{stats.get('level_1', '?')} "
                         f"L2:{stats.get('level_2', '?')}")
                _show_file(label, p)
            except Exception:
                _show_file("", p)

    if qdrant_dirs:
        print("  Qdrant indexes:")
        for d in qdrant_dirs:
            _show_file("", d)

    if not any([jsons, chunks, questions_jsonls, citations_jsons,
                markdowns, chroma_dirs, qdrant_dirs, raptor_files]):
        print("  No pipeline output found.")

    # Chunk stats for each chunks file
    for cp in chunks:
        records = _load_jsonl(cp)
        if not records:
            continue
        print(f"\n--- {cp.name} ({len(records)} chunks) ---")
        type_counts: dict[str, int] = {}
        ch_counts: dict[int, int] = {}
        for rec in records:
            ct = rec["metadata"]["content_type"]
            type_counts[ct] = type_counts.get(ct, 0) + 1
            ch = rec["metadata"].get("chapter_num")
            if ch is not None:
                ch_counts[ch] = ch_counts.get(ch, 0) + 1
        print("  Content types:")
        for ct, n in sorted(type_counts.items(), key=lambda x: -x[1]):
            print(f"    {ct:25s} {n:5d}  ({100*n/len(records):.0f}%)")
        if ch_counts:
            print(f"  Chapters ({len(ch_counts)} detected):")
            for ch in sorted(ch_counts):
                print(f"    Ch {ch:2d}: {ch_counts[ch]:4d} chunks")

    # Exact selected-backend stats are protected by the vector-store lease.
    if db_dir.exists():
        label = "Qdrant" if db_backend == "qdrant" else "ChromaDB"
        unit = "Points" if db_backend == "qdrant" else "Documents"
        try:
            count = _index_collection_count(
                db_dir, collection_name, db_backend=db_backend,
                lock_timeout=lock_timeout)
            print(f"\n--- {label} ---")
            print(f"  Collection: {collection_name}")
            print(f"  {unit}:  {count}")
        except LookupError:
            print(f"\n--- {label} ---")
            print(f"  Collection '{collection_name}' not found")
        except Exception as exc:
            print(f"\n--- {label} ---")
            print(f"  Collection status unavailable: {exc}")

    print()


